// Islamic history after the Prophet: the rightly-guided caliphs, Umayyads, Abbasids, Andalus, Fatimids, Crusades and Mongols, Mamluks, Ottomans and others, scholars' lives and the classical historians. Draft content, needs scholarly review.
export const QS: RawQ[] = [
  // ---------- Stage 1 (foundation) ----------
  { id: "hs-001", s: "history", g: 1, d: 1, t: ["rashidun", "caliphs"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, on the caliphate of Abū Bakr",
    en: ["Who became the first caliph after the death of the Prophet?", ["Abū Bakr al-Ṣiddīq", "ʿUmar ibn al-Khaṭṭāb", "ʿUthmān ibn ʿAffān", "ʿAlī ibn Abī Ṭālib"], "Abū Bakr was chosen at the gathering of Banū Sāʿida and the pledge was then given to him publicly in the mosque. He ruled for about two years until his death."],
    de: ["Wer wurde nach dem Tod des Propheten der erste Kalif?", ["Abū Bakr aṣ-Ṣiddīq", "ʿUmar ibn al-Ḫaṭṭāb", "ʿUṯmān ibn ʿAffān", "ʿAlī ibn Abī Ṭālib"], "Abū Bakr wurde bei der Versammlung der Banū Sāʿida gewählt, und ihm wurde dann öffentlich in der Moschee gehuldigt. Er regierte etwa zwei Jahre bis zu seinem Tod."],
    ar: ["من الذي تولى الخلافة أولًا بعد وفاة النبي ﷺ؟", ["أبو بكر الصديق", "عمر بن الخطاب", "عثمان بن عفان", "علي بن أبي طالب"], "اختير أبو بكر في اجتماع بني ساعدة ثم بايعه الناس عامة في المسجد، وحكم نحو سنتين حتى وفاته."] },

  { id: "hs-002", s: "history", g: 1, d: 1, t: ["rashidun", "caliphs"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, on the caliphate of ʿUmar",
    en: ["Who was the second caliph, nominated by Abū Bakr before his death?", ["ʿUmar ibn al-Khaṭṭāb", "ʿUthmān ibn ʿAffān", "ʿAlī ibn Abī Ṭālib", "Khālid ibn al-Walīd"], "Abū Bakr consulted the leading Companions and nominated ʿUmar, whose caliphate saw the great conquests and the organisation of the state."],
    de: ["Wer war der zweite Kalif, von Abū Bakr vor seinem Tod bestimmt?", ["ʿUmar ibn al-Ḫaṭṭāb", "ʿUṯmān ibn ʿAffān", "ʿAlī ibn Abī Ṭālib", "Ḫālid ibn al-Walīd"], "Abū Bakr beriet sich mit den führenden Gefährten und bestimmte ʿUmar, unter dessen Kalifat die großen Eroberungen und der Aufbau des Staates stattfanden."],
    ar: ["من الخليفة الثاني الذي عهد إليه أبو بكر قبل وفاته؟", ["عمر بن الخطاب", "عثمان بن عفان", "علي بن أبي طالب", "خالد بن الوليد"], "استشار أبو بكر كبار الصحابة ثم عهد إلى عمر، وفي خلافته كانت الفتوح الكبرى وتنظيم الدولة."] },

  { id: "hs-003", s: "history", g: 1, d: 1, t: ["rashidun", "caliphs"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, on the caliphate of ʿUthmān",
    en: ["Who was the third of the rightly-guided caliphs, known as Dhū al-Nūrayn?", ["ʿUthmān ibn ʿAffān", "ʿAlī ibn Abī Ṭālib", "Ṭalḥa ibn ʿUbayd Allāh", "Saʿd ibn Abī Waqqāṣ"], "ʿUthmān was given the title Dhū al-Nūrayn (the possessor of two lights) because he married two daughters of the Prophet, one after the other."],
    de: ["Wer war der dritte der rechtgeleiteten Kalifen, bekannt als Ḏū n-Nūrain?", ["ʿUṯmān ibn ʿAffān", "ʿAlī ibn Abī Ṭālib", "Ṭalḥa ibn ʿUbaid Allāh", "Saʿd ibn Abī Waqqāṣ"], "ʿUṯmān erhielt den Titel Ḏū n-Nūrain (Besitzer zweier Lichter), weil er nacheinander zwei Töchter des Propheten heiratete."],
    ar: ["من الخليفة الراشد الثالث الملقب بذي النورين؟", ["عثمان بن عفان", "علي بن أبي طالب", "طلحة بن عبيد الله", "سعد بن أبي وقاص"], "لُقّب عثمان بذي النورين لأنه تزوج ابنتين من بنات النبي ﷺ الواحدة بعد الأخرى."] },

  { id: "hs-004", s: "history", g: 1, d: 1, t: ["rashidun", "caliphs"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, on the caliphate of ʿAlī",
    en: ["Who was the fourth of the rightly-guided caliphs?", ["ʿAlī ibn Abī Ṭālib", "Muʿāwiya ibn Abī Sufyān", "al-Ḥasan ibn ʿAlī", "al-Zubayr ibn al-ʿAwwām"], "ʿAlī, the Prophet's cousin and son-in-law, became caliph after the killing of ʿUthmān and moved his capital to Kūfa."],
    de: ["Wer war der vierte der rechtgeleiteten Kalifen?", ["ʿAlī ibn Abī Ṭālib", "Muʿāwiya ibn Abī Sufyān", "al-Ḥasan ibn ʿAlī", "az-Zubair ibn al-ʿAwwām"], "ʿAlī, der Cousin und Schwiegersohn des Propheten, wurde nach der Ermordung ʿUṯmāns Kalif und verlegte seine Hauptstadt nach Kūfa."],
    ar: ["من الخليفة الراشد الرابع؟", ["علي بن أبي طالب", "معاوية بن أبي سفيان", "الحسن بن علي", "الزبير بن العوام"], "تولى علي، ابن عم النبي ﷺ وصهره، الخلافة بعد مقتل عثمان، ونقل عاصمته إلى الكوفة."] },

  { id: "hs-005", s: "history", g: 1, d: 1, t: ["rashidun", "terminology"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, introduction to the caliphate",
    en: ["What is the Arabic title given to the first four caliphs?", ["al-Khulafāʾ al-Rāshidūn (the rightly-guided caliphs)", "al-Ashra al-Mubashshara (the ten promised Paradise)", "al-Muhājirūn (the emigrants)", "al-Anṣār (the helpers)"], "The first four caliphs are called al-Khulafāʾ al-Rāshidūn, based on a hadith about the sunna of the rightly-guided caliphs after the Prophet. The other terms describe different groups of Companions."],
    de: ["Wie lautet der arabische Titel der ersten vier Kalifen?", ["al-Ḫulafāʾ ar-Rāšidūn (die rechtgeleiteten Kalifen)", "al-ʿAšara al-Mubaššara (die zehn Paradiesverheißenen)", "al-Muhāǧirūn (die Auswanderer)", "al-Anṣār (die Helfer)"], "Die ersten vier Kalifen heißen al-Ḫulafāʾ ar-Rāšidūn, gestützt auf einen Hadith über die Sunna der rechtgeleiteten Kalifen nach dem Propheten. Die anderen Begriffe bezeichnen andere Gruppen von Gefährten."],
    ar: ["ما اللقب العربي للخلفاء الأربعة الأوائل؟", ["الخلفاء الراشدون", "العشرة المبشرون بالجنة", "المهاجرون", "الأنصار"], "يسمى الخلفاء الأربعة الأوائل الراشدين استنادًا إلى حديث في سنة الخلفاء الراشدين من بعده، أما الألقاب الأخرى فتعني فئات أخرى من الصحابة."] },

  { id: "hs-006", s: "history", g: 1, d: 1, t: ["hijri-calendar", "terminology"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, on the beginning of the Hijri calendar",
    en: ["From which event does the Hijri calendar count its years?", ["The Hijra of the Prophet from Makka to Madīna", "The birth of the Prophet", "The first revelation in the cave of Ḥirāʾ", "The conquest of Makka"], "The Companions under ʿUmar chose the Hijra as the starting point because it marked the founding of the Muslim community in Madīna. The year count begins with the first of Muḥarram of that year."],
    de: ["Von welchem Ereignis an zählt der Hidschra-Kalender seine Jahre?", ["Von der Hidschra des Propheten von Mekka nach Medina", "Von der Geburt des Propheten", "Von der ersten Offenbarung in der Höhle Ḥirāʾ", "Von der Eroberung Mekkas"], "Die Gefährten unter ʿUmar wählten die Hidschra als Ausgangspunkt, weil sie die Gründung der muslimischen Gemeinschaft in Medina markierte. Die Jahreszählung beginnt mit dem 1. Muḥarram jenes Jahres."],
    ar: ["من أي حدث يبدأ العدّ في التاريخ الهجري؟", ["هجرة النبي ﷺ من مكة إلى المدينة", "مولد النبي ﷺ", "نزول الوحي الأول في غار حراء", "فتح مكة"], "اختار الصحابة في عهد عمر الهجرة مبدأ للتاريخ لأنها كانت بداية تأسيس الأمة في المدينة، ويبدأ عدّ السنة من أول محرم."] },

  { id: "hs-007", s: "history", g: 1, d: 2, t: ["hijri-calendar", "umar"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, on the beginning of the Hijri dating",
    en: ["Under which caliph was the Hijri calendar introduced as the official system of dating?", ["ʿUmar ibn al-Khaṭṭāb", "Abū Bakr al-Ṣiddīq", "ʿUthmān ibn ʿAffān", "Muʿāwiya ibn Abī Sufyān"], "The sources say ʿUmar introduced the dating after a letter without a clear year caused confusion; the Companions agreed on the Hijra as the starting point. The exact year of introduction is variously reported."],
    de: ["Unter welchem Kalifen wurde der Hidschra-Kalender als offizielle Zeitrechnung eingeführt?", ["ʿUmar ibn al-Ḫaṭṭāb", "Abū Bakr aṣ-Ṣiddīq", "ʿUṯmān ibn ʿAffān", "Muʿāwiya ibn Abī Sufyān"], "Die Quellen berichten, ʿUmar habe die Datierung eingeführt, nachdem ein Brief ohne klares Jahr Verwirrung gestiftet hatte; die Gefährten einigten sich auf die Hidschra als Ausgangspunkt. Das genaue Jahr der Einführung wird unterschiedlich überliefert."],
    ar: ["في عهد أي خليفة اعتُمد التاريخ الهجري تأريخًا رسميًّا؟", ["عمر بن الخطاب", "أبو بكر الصديق", "عثمان بن عفان", "معاوية بن أبي سفيان"], "تذكر المصادر أن عمر وضع التأريخ بعد أن التبس أمر كتاب بلا سنة واضحة، فاتفق الصحابة على الهجرة مبدأً، وتختلف الروايات في سنة وضعه."] },

  { id: "hs-008", s: "history", g: 1, d: 1, t: ["umayyads", "capitals"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, on the Umayyad caliphs",
    en: ["Which city was the capital of the Umayyad caliphate?", ["Damascus", "Baghdad", "Cairo", "Madīna"], "Muʿāwiya made Damascus the centre of power, and it stayed the Umayyad capital. Baghdad was founded later by the Abbasids; Cairo was founded by the Fatimids."],
    de: ["Welche Stadt war die Hauptstadt des Umayyadenkalifats?", ["Damaskus", "Bagdad", "Kairo", "Medina"], "Muʿāwiya machte Damaskus zum Machtzentrum, und es blieb die Hauptstadt der Umayyaden. Bagdad wurde später von den Abbasiden gegründet, Kairo von den Fatimiden."],
    ar: ["ما عاصمة الدولة الأموية؟", ["دمشق", "بغداد", "القاهرة", "المدينة المنورة"], "جعل معاوية دمشق مركز الحكم وبقيت عاصمة الأمويين، أما بغداد فأسسها العباسيون والقاهرة بناها الفاطميون."] },

  { id: "hs-009", s: "history", g: 1, d: 1, t: ["abbasids", "capitals"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, on the founding of Baghdad",
    en: ["Which Abbasid caliph founded the city of Baghdad as his capital?", ["al-Manṣūr", "Hārūn al-Rashīd", "al-Maʾmūn", "al-Saffāḥ"], "Al-Manṣūr founded Baghdad in the year commonly dated 145 AH (762 CE) as the round city of Madīnat al-Salām. Hārūn al-Rashīd and al-Maʾmūn made it a centre of learning later."],
    de: ["Welcher abbasidische Kalif gründete die Stadt Bagdad als Hauptstadt?", ["al-Manṣūr", "Hārūn ar-Rašīd", "al-Maʾmūn", "as-Saffāḥ"], "Al-Manṣūr gründete Bagdad in dem Jahr, das üblicherweise mit 145 n. H. (762 n. Chr.) angegeben wird, als die runde Stadt Madīnat as-Salām. Hārūn ar-Rašīd und al-Maʾmūn machten sie später zu einem Zentrum der Gelehrsamkeit."],
    ar: ["أي خليفة عباسي أسس مدينة بغداد عاصمةً له؟", ["المنصور", "هارون الرشيد", "المأمون", "السفاح"], "أسس المنصور بغداد في السنة المشهورة 145هـ (762م) مدينةً مدوّرة سُميت مدينة السلام، ثم جعلها هارون الرشيد والمأمون مركز علم."] },

  { id: "hs-010", s: "history", g: 1, d: 1, t: ["umayyads", "dynasties"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, on the year of the community (ʿām al-jamāʿa)",
    en: ["Who founded the Umayyad dynasty after the year of unity?", ["Muʿāwiya ibn Abī Sufyān", "Yazīd ibn Muʿāwiya", "ʿAbd al-Malik ibn Marwān", "ʿUmar ibn ʿAbd al-ʿAzīz"], "Muʿāwiya, governor of Syria, became sole ruler in 41 AH when al-Ḥasan ibn ʿAlī handed over the caliphate to unite the community. His descendants and the line of Marwān ruled until 132 AH."],
    de: ["Wer gründete nach dem Jahr der Einheit die Umayyaden-Dynastie?", ["Muʿāwiya ibn Abī Sufyān", "Yazīd ibn Muʿāwiya", "ʿAbd al-Malik ibn Marwān", "ʿUmar ibn ʿAbd al-ʿAzīz"], "Muʿāwiya, Statthalter von Syrien, wurde 41 n. H. Alleinherrscher, als al-Ḥasan ibn ʿAlī ihm das Kalifat übergab, um die Gemeinschaft zu einen. Seine Nachkommen und die Linie Marwāns regierten bis 132 n. H."],
    ar: ["من مؤسس الدولة الأموية بعد عام الجماعة؟", ["معاوية بن أبي سفيان", "يزيد بن معاوية", "عبد الملك بن مروان", "عمر بن عبد العزيز"], "صار معاوية، والي الشام، أميرًا للمؤمنين سنة 41هـ حين تنازل له الحسن بن علي حقنًا للدماء، وحكم أبناؤه ثم آل مروان حتى 132هـ."] },

  { id: "hs-011", s: "history", g: 1, d: 1, t: ["andalus", "conquests"], src: "al-Maqqarī, Nafḥ al-Ṭīb, on the conquest of al-Andalus",
    en: ["Which commander led the Muslim army across the strait into Spain in 92 AH (711 CE)?", ["Ṭāriq ibn Ziyād", "Mūsā ibn Nuṣayr", "ʿUqba ibn Nāfiʿ", "ʿAbd al-Raḥmān al-Ghāfiqī"], "Ṭāriq ibn Ziyād crossed with his army and defeated the Visigothic king Roderic; the mountain where he landed is named after him, Jabal Ṭāriq. His superior Mūsā ibn Nuṣayr followed."],
    de: ["Welcher Befehlshaber führte 92 n. H. (711 n. Chr.) das muslimische Heer über die Meerenge nach Spanien?", ["Ṭāriq ibn Ziyād", "Mūsā ibn Nuṣair", "ʿUqba ibn Nāfiʿ", "ʿAbd ar-Raḥmān al-Ġāfiqī"], "Ṭāriq ibn Ziyād setzte mit seinem Heer über und besiegte den westgotischen König Roderich; der Berg, an dem er landete, ist nach ihm benannt, Ǧabal Ṭāriq. Sein Vorgesetzter Mūsā ibn Nuṣair folgte."],
    ar: ["أي قائد عبر بجيشه المضيق إلى الأندلس سنة 92هـ (711م)؟", ["طارق بن زياد", "موسى بن نصير", "عقبة بن نافع", "عبد الرحمن الغافقي"], "عبر طارق بن زياد بجيشه وهزم الملك القوطي لذريق، وسُمي الجبل الذي نزل عنده جبل طارق، ثم لحق به قائده موسى بن نصير."] },

  { id: "hs-012", s: "history", g: 1, d: 1, t: ["andalus", "cities"], src: "al-Maqqarī, Nafḥ al-Ṭīb, on Cordoba",
    en: ["Which city became the capital of the Umayyad state in al-Andalus and a centre of learning?", ["Cordoba (Qurṭuba)", "Seville (Ishbīliya)", "Toledo (Ṭulayṭula)", "Granada (Gharnāṭa)"], "Cordoba was the capital of the Umayyads of al-Andalus from ʿAbd al-Raḥmān I onwards and had a great library and a famous mosque. Granada became the last Muslim capital in Spain."],
    de: ["Welche Stadt wurde Hauptstadt des Umayyadenstaates in al-Andalus und Zentrum der Gelehrsamkeit?", ["Córdoba (Qurṭuba)", "Sevilla (Išbīliya)", "Toledo (Ṭulaiṭula)", "Granada (Ġarnāṭa)"], "Córdoba war seit ʿAbd ar-Raḥmān I. Hauptstadt der andalusischen Umayyaden und besaß eine große Bibliothek und eine berühmte Moschee. Granada wurde die letzte muslimische Hauptstadt in Spanien."],
    ar: ["أي مدينة صارت عاصمة الأمويين في الأندلس ومركز علم؟", ["قرطبة", "إشبيلية", "طليطلة", "غرناطة"], "كانت قرطبة عاصمة أمويي الأندلس منذ عبد الرحمن الداخل، وفيها مكتبة كبرى ومسجد شهير، أما غرناطة فصارت آخر عواصم المسلمين في إسبانيا."] },

  { id: "hs-013", s: "history", g: 1, d: 1, t: ["crusades", "ayyubids"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 583 AH",
    en: ["Which Muslim ruler recaptured Jerusalem from the Crusaders in 583 AH (1187 CE)?", ["Ṣalāḥ al-Dīn al-Ayyūbī (Saladin)", "Nūr al-Dīn Zangī", "Baybars", "Qutuz"], "After the victory at Ḥaṭṭīn, Ṣalāḥ al-Dīn entered Jerusalem. Nūr al-Dīn had prepared the ground earlier, while Baybars and Qutuz lived in the following century."],
    de: ["Welcher muslimische Herrscher eroberte 583 n. H. (1187 n. Chr.) Jerusalem von den Kreuzfahrern zurück?", ["Ṣalāḥ ad-Dīn al-Aiyūbī (Saladin)", "Nūr ad-Dīn Zangī", "Baibars", "Quṭuz"], "Nach dem Sieg bei Ḥaṭṭīn zog Ṣalāḥ ad-Dīn in Jerusalem ein. Nūr ad-Dīn hatte den Boden früher bereitet, Baibars und Quṭuz lebten im folgenden Jahrhundert."],
    ar: ["أي حاكم مسلم استرد القدس من الصليبيين سنة 583هـ (1187م)؟", ["صلاح الدين الأيوبي", "نور الدين زنكي", "بيبرس", "قطز"], "بعد نصر حطين دخل صلاح الدين القدس، وكان نور الدين قد مهّد الطريق قبله، أما بيبرس وقطز فعاشا في القرن التالي."] },

  { id: "hs-014", s: "history", g: 1, d: 2, t: ["crusades", "battles"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 583 AH",
    en: ["Which battle in 583 AH opened the way to the recapture of Jerusalem by Ṣalāḥ al-Dīn?", ["Ḥaṭṭīn", "ʿAyn Jālūt", "Yarmūk", "Malāzgird"], "At Ḥaṭṭīn near Tiberias the Crusader army was destroyed, which left the kingdom of Jerusalem undefended. ʿAyn Jālūt was against the Mongols, Yarmūk against Byzantium and Malāzgird against Byzantium again."],
    de: ["Welche Schlacht des Jahres 583 n. H. öffnete Ṣalāḥ ad-Dīn den Weg zur Rückeroberung Jerusalems?", ["Ḥaṭṭīn", "ʿAin Ǧālūt", "Yarmūk", "Malāzgird"], "Bei Ḥaṭṭīn nahe Tiberias wurde das Kreuzfahrerheer vernichtet, wodurch das Königreich Jerusalem schutzlos war. ʿAin Ǧālūt war gegen die Mongolen, Yarmūk gegen Byzanz und Malāzgird wiederum gegen Byzanz."],
    ar: ["أي معركة سنة 583هـ فتحت لصلاح الدين طريق استرداد القدس؟", ["حطين", "عين جالوت", "اليرموك", "ملاذكرد"], "في حطين قرب طبرية أُبيد جيش الصليبيين فصارت مملكة القدس بلا حماية، أما عين جالوت فضد المغول واليرموك ضد البيزنطيين وملاذكرد ضدهم أيضًا."] },

  { id: "hs-015", s: "history", g: 1, d: 1, t: ["ottomans", "conquests"], src: "Ibn Iyās, Badāʾiʿ al-Zuhūr; Ottoman chronicles on the conquest of Constantinople",
    en: ["Which Ottoman sultan conquered Constantinople in 857 AH (1453 CE)?", ["Muḥammad II, known as al-Fātiḥ (the Conqueror)", "Sulaymān the Magnificent", "Selim I", "Murād II"], "Mehmed II, aged about twenty-one, took the Byzantine capital after a siege of about fifty days. The city became Istanbul and the Ottoman capital."],
    de: ["Welcher osmanische Sultan eroberte 857 n. H. (1453 n. Chr.) Konstantinopel?", ["Muḥammad II., genannt al-Fātiḥ (der Eroberer)", "Sulaimān der Prächtige", "Selim I.", "Murād II."], "Mehmed II., etwa einundzwanzig Jahre alt, nahm die byzantinische Hauptstadt nach einer Belagerung von rund fünfzig Tagen ein. Die Stadt wurde Istanbul und osmanische Hauptstadt."],
    ar: ["أي سلطان عثماني فتح القسطنطينية سنة 857هـ (1453م)؟", ["محمد الثاني (الفاتح)", "سليمان القانوني", "سليم الأول", "مراد الثاني"], "فتح محمد الثاني وهو في نحو الحادية والعشرين العاصمة البيزنطية بعد حصار دام نحو خمسين يومًا، فصارت إسطنبول عاصمة العثمانيين."] },

  { id: "hs-016", s: "history", g: 1, d: 1, t: ["abbasids", "dynasties"], src: "al-Masʿūdī, Murūj al-Dhahab, on the end of the Umayyads",
    en: ["Which dynasty replaced the Umayyads as the ruling caliphal house in the East in 132 AH (750 CE)?", ["The Abbasids", "The Fatimids", "The Ayyubids", "The Seljuks"], "The Abbasids, descendants of the Prophet's uncle al-ʿAbbās, overthrew the Umayyads at the Battle of the Zab and ruled from Iraq. The Fatimids, Ayyubids and Seljuks came later."],
    de: ["Welche Dynastie löste 132 n. H. (750 n. Chr.) im Osten die Umayyaden als herrschendes Kalifenhaus ab?", ["Die Abbasiden", "Die Fatimiden", "Die Aiyubiden", "Die Seldschuken"], "Die Abbasiden, Nachkommen des Prophetenonkels al-ʿAbbās, stürzten die Umayyaden in der Schlacht am Zab und regierten vom Irak aus. Fatimiden, Aiyubiden und Seldschuken kamen später."],
    ar: ["أي أسرة حلّت محل الأمويين في الخلافة بالمشرق سنة 132هـ (750م)؟", ["العباسيون", "الفاطميون", "الأيوبيون", "السلاجقة"], "أطاح العباسيون، وهم من ذرية عم النبي ﷺ العباس، بالأمويين في معركة الزاب وحكموا من العراق، أما الفاطميون والأيوبيون والسلاجقة فجاؤوا بعدهم."] },

  { id: "hs-017", s: "history", g: 1, d: 2, t: ["rashidun", "ridda"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, on the wars of apostasy",
    en: ["What is the name of the wars that Abū Bakr fought against tribes that refused to pay zakāt or abandoned Islam?", ["Ḥurūb al-Ridda (wars of apostasy)", "Futūḥ al-Shām (conquests of Syria)", "Ghazwat Tabūk", "Ḥurūb al-Jamal"], "After the Prophet's death several tribes rebelled or refused zakāt, and false prophets appeared. Abū Bakr sent armies against them and re-established unity within about a year."],
    de: ["Wie heißen die Kriege, die Abū Bakr gegen Stämme führte, die die Zakāt verweigerten oder den Islam aufgaben?", ["Ḥurūb ar-Ridda (Abfallkriege)", "Futūḥ aš-Šām (Eroberung Syriens)", "Ġazwat Tabūk", "Ḥurūb al-Ǧamal"], "Nach dem Tod des Propheten rebellierten mehrere Stämme oder verweigerten die Zakāt, und falsche Propheten traten auf. Abū Bakr schickte Heere gegen sie und stellte die Einheit binnen etwa eines Jahres wieder her."],
    ar: ["ما اسم الحروب التي خاضها أبو بكر ضد القبائل التي منعت الزكاة أو ارتدت؟", ["حروب الردة", "فتوح الشام", "غزوة تبوك", "حرب الجمل"], "بعد وفاة النبي ﷺ ارتدّت قبائل أو منعت الزكاة وظهر مدّعو النبوة، فبعث أبو بكر الجيوش إليهم وأعاد الوحدة في نحو سنة."] },

  { id: "hs-018", s: "history", g: 1, d: 2, t: ["rashidun", "umar"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, on the death of ʿUmar",
    en: ["Which caliph was stabbed while leading the dawn prayer by Abū Luʾluʾa, a Persian slave?", ["ʿUmar ibn al-Khaṭṭāb", "ʿUthmān ibn ʿAffān", "ʿAlī ibn Abī Ṭālib", "Abū Bakr al-Ṣiddīq"], "ʿUmar was attacked in the mosque at dawn in 23 AH and died of his wounds a few days later. Before dying he appointed a council of six to choose the next caliph."],
    de: ["Welcher Kalif wurde beim Morgengebet von Abū Luʾluʾa, einem persischen Sklaven, niedergestochen?", ["ʿUmar ibn al-Ḫaṭṭāb", "ʿUṯmān ibn ʿAffān", "ʿAlī ibn Abī Ṭālib", "Abū Bakr aṣ-Ṣiddīq"], "ʿUmar wurde im Jahr 23 n. H. im Morgengrauen in der Moschee angegriffen und starb wenige Tage später an seinen Wunden. Vor seinem Tod ernannte er einen Rat von sechs Männern zur Wahl des nächsten Kalifen."],
    ar: ["أي خليفة طعنه أبو لؤلؤة الفارسي وهو يصلي الفجر؟", ["عمر بن الخطاب", "عثمان بن عفان", "علي بن أبي طالب", "أبو بكر الصديق"], "طُعن عمر في المسجد فجرًا سنة 23هـ وتوفي بعد أيام، وقبل وفاته جعل الأمر شورى في ستة."] },

  { id: "hs-019", s: "history", g: 1, d: 2, t: ["rashidun", "uthman"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, on the year 35 AH",
    en: ["Which caliph was besieged in his house in Madīna and killed by rebels in 35 AH?", ["ʿUthmān ibn ʿAffān", "ʿUmar ibn al-Khaṭṭāb", "ʿAlī ibn Abī Ṭālib", "al-Ḥusayn ibn ʿAlī"], "Rebels from several provinces besieged ʿUthmān for weeks and killed him while he was reading the Quran. His death began the first great civil strife (fitna) of the community."],
    de: ["Welcher Kalif wurde in seinem Haus in Medina belagert und 35 n. H. von Aufständischen getötet?", ["ʿUṯmān ibn ʿAffān", "ʿUmar ibn al-Ḫaṭṭāb", "ʿAlī ibn Abī Ṭālib", "al-Ḥusain ibn ʿAlī"], "Aufständische aus mehreren Provinzen belagerten ʿUṯmān wochenlang und töteten ihn, als er im Koran las. Sein Tod löste die erste große Zwietracht (Fitna) der Gemeinschaft aus."],
    ar: ["أي خليفة حوصر في داره بالمدينة وقتله الثوار سنة 35هـ؟", ["عثمان بن عفان", "عمر بن الخطاب", "علي بن أبي طالب", "الحسين بن علي"], "حاصر ثوار من أمصار عدة عثمان أسابيع وقتلوه وهو يقرأ القرآن، فبدأت بمقتله الفتنة الكبرى الأولى."] },

  { id: "hs-020", s: "history", g: 1, d: 1, t: ["conquests", "jerusalem"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, on the conquest of Bayt al-Maqdis",
    en: ["Which caliph travelled to receive the surrender of Jerusalem in person?", ["ʿUmar ibn al-Khaṭṭāb", "Abū Bakr al-Ṣiddīq", "ʿAlī ibn Abī Ṭālib", "Muʿāwiya ibn Abī Sufyān"], "The Christian leader of the city asked for a treaty to be concluded with the caliph himself, so ʿUmar came to Jerusalem and agreed terms that guaranteed the safety of the people and their churches."],
    de: ["Welcher Kalif reiste persönlich an, um die Übergabe Jerusalems entgegenzunehmen?", ["ʿUmar ibn al-Ḫaṭṭāb", "Abū Bakr aṣ-Ṣiddīq", "ʿAlī ibn Abī Ṭālib", "Muʿāwiya ibn Abī Sufyān"], "Der christliche Führer der Stadt bat darum, den Vertrag mit dem Kalifen selbst zu schließen; daher kam ʿUmar nach Jerusalem und vereinbarte Bedingungen, die den Menschen und ihren Kirchen Sicherheit garantierten."],
    ar: ["أي خليفة سافر بنفسه لتسلّم بيت المقدس؟", ["عمر بن الخطاب", "أبو بكر الصديق", "علي بن أبي طالب", "معاوية بن أبي سفيان"], "طلب بطريرك المدينة أن يكتب الصلح مع الخليفة نفسه، فقدم عمر وكتب لهم العهدة التي أمّنتهم على أنفسهم وكنائسهم."] },

  { id: "hs-021", s: "history", g: 1, d: 1, t: ["scholars-lives", "madhhabs"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, biography of Abū Ḥanīfa",
    en: ["Which scholar is the founder of the Ḥanafī school of law?", ["Abū Ḥanīfa al-Nuʿmān ibn Thābit", "Mālik ibn Anas", "Muḥammad ibn Idrīs al-Shāfiʿī", "Aḥmad ibn Ḥanbal"], "Abū Ḥanīfa (80–150 AH, commonly given), who lived in Kūfa and Baghdad, is the eponym of the Ḥanafī school, which grew through his students Abū Yūsuf and Muḥammad al-Shaybānī."],
    de: ["Welcher Gelehrte ist der Gründer der hanafitischen Rechtsschule?", ["Abū Ḥanīfa an-Nuʿmān ibn Ṯābit", "Mālik ibn Anas", "Muḥammad ibn Idrīs aš-Šāfiʿī", "Aḥmad ibn Ḥanbal"], "Abū Ḥanīfa (80–150 n. H., gängige Angabe), der in Kūfa und Bagdad lebte, ist der Namensgeber der hanafitischen Schule, die durch seine Schüler Abū Yūsuf und Muḥammad aš-Šaibānī wuchs."],
    ar: ["من مؤسس المذهب الحنفي؟", ["أبو حنيفة النعمان بن ثابت", "مالك بن أنس", "محمد بن إدريس الشافعي", "أحمد بن حنبل"], "أبو حنيفة (80–150هـ على المشهور) عاش في الكوفة وبغداد وإليه ينسب المذهب الحنفي الذي نشره تلاميذه أبو يوسف ومحمد بن الحسن الشيباني."] },

  { id: "hs-022", s: "history", g: 1, d: 1, t: ["scholars-lives", "madhhabs"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, biography of Mālik",
    en: ["Which scholar of Madīna is the founder of the Mālikī school and author of al-Muwaṭṭaʾ?", ["Mālik ibn Anas", "Abū Ḥanīfa", "al-Shāfiʿī", "Aḥmad ibn Ḥanbal"], "Mālik ibn Anas (93–179 AH, commonly given) spent his life in Madīna. His al-Muwaṭṭaʾ is one of the earliest surviving collections of hadith and legal rulings."],
    de: ["Welcher Gelehrte aus Medina ist der Gründer der malikitischen Schule und Verfasser von al-Muwaṭṭaʾ?", ["Mālik ibn Anas", "Abū Ḥanīfa", "aš-Šāfiʿī", "Aḥmad ibn Ḥanbal"], "Mālik ibn Anas (93–179 n. H., gängige Angabe) verbrachte sein Leben in Medina. Sein al-Muwaṭṭaʾ ist eine der frühesten erhaltenen Sammlungen von Hadithen und Rechtsurteilen."],
    ar: ["أي عالم من المدينة مؤسس المذهب المالكي وصاحب «الموطأ»؟", ["مالك بن أنس", "أبو حنيفة", "الشافعي", "أحمد بن حنبل"], "أمضى مالك بن أنس (93–179هـ على المشهور) حياته في المدينة، و«الموطأ» من أقدم ما وصل من مجموعات الحديث والأحكام."] },

  { id: "hs-023", s: "history", g: 1, d: 1, t: ["scholars-lives", "madhhabs"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, biography of al-Shāfiʿī",
    en: ["Which scholar, born in Gaza, is the founder of the Shāfiʿī school and author of al-Risāla?", ["Muḥammad ibn Idrīs al-Shāfiʿī", "Mālik ibn Anas", "Abū Ḥanīfa", "Aḥmad ibn Ḥanbal"], "Al-Shāfiʿī (150–204 AH, commonly given) studied in Makka, Madīna and Iraq and settled in Egypt. His al-Risāla is regarded as the first systematic work on the principles of jurisprudence."],
    de: ["Welcher in Gaza geborene Gelehrte ist der Gründer der schafiitischen Schule und Verfasser von al-Risāla?", ["Muḥammad ibn Idrīs aš-Šāfiʿī", "Mālik ibn Anas", "Abū Ḥanīfa", "Aḥmad ibn Ḥanbal"], "Aš-Šāfiʿī (150–204 n. H., gängige Angabe) studierte in Mekka, Medina und im Irak und ließ sich in Ägypten nieder. Seine al-Risāla gilt als das erste systematische Werk über die Prinzipien der Rechtswissenschaft."],
    ar: ["أي عالم وُلد في غزة هو مؤسس المذهب الشافعي وصاحب «الرسالة»؟", ["محمد بن إدريس الشافعي", "مالك بن أنس", "أبو حنيفة", "أحمد بن حنبل"], "درس الشافعي (150–204هـ على المشهور) في مكة والمدينة والعراق ثم استقر في مصر، و«الرسالة» تُعدّ أول مؤلَّف منهجي في أصول الفقه."] },

  { id: "hs-024", s: "history", g: 1, d: 1, t: ["scholars-lives", "madhhabs"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, biography of Aḥmad ibn Ḥanbal",
    en: ["Which scholar of Baghdad, tested during the miḥna, is the namesake of the Ḥanbalī school and author of the Musnad?", ["Aḥmad ibn Ḥanbal", "Mālik ibn Anas", "Abū Ḥanīfa", "al-Shāfiʿī"], "Aḥmad ibn Ḥanbal (164–241 AH, commonly given) refused to say that the Quran is created under the caliphs' inquisition, was flogged, and became a symbol of steadfastness."],
    de: ["Welcher Gelehrte aus Bagdad, während der Miḥna geprüft, ist der Namensgeber der hanbalitischen Schule und Verfasser des Musnad?", ["Aḥmad ibn Ḥanbal", "Mālik ibn Anas", "Abū Ḥanīfa", "aš-Šāfiʿī"], "Aḥmad ibn Ḥanbal (164–241 n. H., gängige Angabe) weigerte sich, unter der Inquisition der Kalifen zu sagen, der Koran sei erschaffen, wurde ausgepeitscht und wurde zum Sinnbild der Standhaftigkeit."],
    ar: ["أي عالم من بغداد امتُحن في المحنة وهو صاحب «المسند» وإليه ينسب المذهب الحنبلي؟", ["أحمد بن حنبل", "مالك بن أنس", "أبو حنيفة", "الشافعي"], "رفض أحمد بن حنبل (164–241هـ على المشهور) القول بخلق القرآن في محنة الخلفاء فجُلد وصار رمزًا للثبات."] },

  { id: "hs-025", s: "history", g: 1, d: 2, t: ["mongols", "abbasids"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, events of 656 AH",
    en: ["Which event in 656 AH (1258 CE) ended the Abbasid caliphate in Baghdad?", ["The Mongol sack of Baghdad under Hülegü", "The Crusader siege of Baghdad", "The Fatimid conquest of Baghdad", "The Ottoman conquest of Iraq"], "The Mongol army under Hülegü besieged and sacked the city, killed the caliph al-Mustaʿṣim and destroyed much of its libraries and population. An Abbasid line later continued in Cairo under the Mamluks."],
    de: ["Welches Ereignis des Jahres 656 n. H. (1258 n. Chr.) beendete das abbasidische Kalifat in Bagdad?", ["Die mongolische Plünderung Bagdads unter Hülegü", "Die Belagerung Bagdads durch die Kreuzfahrer", "Die fatimidische Eroberung Bagdads", "Die osmanische Eroberung des Irak"], "Das mongolische Heer unter Hülegü belagerte und plünderte die Stadt, tötete den Kalifen al-Mustaʿṣim und zerstörte einen großen Teil ihrer Bibliotheken und Bevölkerung. Eine abbasidische Linie bestand später in Kairo unter den Mamluken fort."],
    ar: ["أي حدث سنة 656هـ (1258م) أنهى الخلافة العباسية في بغداد؟", ["سقوط بغداد على يد المغول بقيادة هولاكو", "حصار الصليبيين لبغداد", "فتح الفاطميين لبغداد", "فتح العثمانيين للعراق"], "حاصر الجيش المغولي بقيادة هولاكو بغداد ونهبها وقتل الخليفة المستعصم ودمر كثيرًا من مكتباتها وأهلها، ثم استمرت خلافة عباسية رمزية في القاهرة زمن المماليك."] },

  { id: "hs-026", s: "history", g: 1, d: 2, t: ["ottomans", "caliphate"], src: "Standard modern histories of Turkey and the late Ottoman Empire (e.g. Lewis, The Emergence of Modern Turkey)",
    en: ["In which year was the caliphate formally abolished by the Turkish Grand National Assembly?", ["1924 CE", "1453 CE", "1517 CE", "1258 CE"], "The Grand National Assembly in Ankara abolished the caliphate on 3 March 1924 after the sultanate had been abolished in 1922. The other years mark the conquest of Constantinople, the Ottoman conquest of Egypt and the fall of Baghdad."],
    de: ["In welchem Jahr wurde das Kalifat von der Großen Türkischen Nationalversammlung formell abgeschafft?", ["1924 n. Chr.", "1453 n. Chr.", "1517 n. Chr.", "1258 n. Chr."], "Die Große Nationalversammlung in Ankara schaffte das Kalifat am 3. März 1924 ab, nachdem 1922 bereits das Sultanat abgeschafft worden war. Die anderen Jahre markieren die Eroberung Konstantinopels, die osmanische Eroberung Ägyptens und den Fall Bagdads."],
    ar: ["في أي سنة ألغى المجلس الوطني التركي الكبير الخلافة رسميًّا؟", ["1924م", "1453م", "1517م", "1258م"], "ألغى المجلس الوطني الكبير في أنقرة الخلافة في 3 مارس 1924 بعد أن ألغى السلطنة سنة 1922، أما التواريخ الأخرى ففتح القسطنطينية وفتح العثمانيين لمصر وسقوط بغداد."] },

  { id: "hs-027", s: "history", g: 1, d: 2, t: ["fatimids", "cities"], src: "al-Maqrīzī, al-Mawāʿiẓ wa-l-Iʿtibār (al-Khiṭaṭ), on the founding of Cairo",
    en: ["Which dynasty founded the city of Cairo and the mosque of al-Azhar?", ["The Fatimids", "The Umayyads", "The Mamluks", "The Ottomans"], "The Fatimid general Jawhar al-Ṣiqillī founded al-Qāhira in 358 AH (969 CE) for the caliph al-Muʿizz; al-Azhar was established in the same period. Its later role as a centre of Sunni learning developed under later dynasties."],
    de: ["Welche Dynastie gründete die Stadt Kairo und die Moschee al-Azhar?", ["Die Fatimiden", "Die Umayyaden", "Die Mamluken", "Die Osmanen"], "Der fatimidische Feldherr Ǧauhar aṣ-Ṣiqillī gründete al-Qāhira 358 n. H. (969 n. Chr.) für den Kalifen al-Muʿizz; al-Azhar entstand in derselben Zeit. Seine spätere Rolle als Zentrum sunnitischer Gelehrsamkeit entwickelte sich unter späteren Dynastien."],
    ar: ["أي سلالة أسست مدينة القاهرة والجامع الأزهر؟", ["الفاطميون", "الأمويون", "المماليك", "العثمانيون"], "أسس القائد الفاطمي جوهر الصقلي القاهرة سنة 358هـ (969م) للخليفة المعز، وأُنشئ الأزهر في الحقبة نفسها، ثم صار مركزًا للعلم السني في عهود لاحقة."] },

  { id: "hs-028", s: "history", g: 1, d: 2, t: ["africa", "mali"], src: "Ibn Khaldūn, Kitāb al-ʿIbar, on the kings of Mali; al-ʿUmarī, Masālik al-Abṣār",
    en: ["Which ruler of the Mali empire made a famous pilgrimage to Makka in 724 AH (1324 CE) and spread gold along the way?", ["Mansa Mūsā", "Askia Muḥammad", "Sunni ʿAlī", "Usman dan Fodio"], "Mansa Mūsā travelled across the Sahara to Makka with a huge retinue; his generosity was so great that, according to the reports, the value of gold dropped in Cairo. He later brought scholars and builders back to Mali."],
    de: ["Welcher Herrscher des Mali-Reiches unternahm 724 n. H. (1324 n. Chr.) eine berühmte Pilgerfahrt nach Mekka und verteilte unterwegs Gold?", ["Mansa Mūsā", "Askia Muḥammad", "Sunni ʿAlī", "Usman dan Fodio"], "Mansa Mūsā reiste mit einem riesigen Gefolge durch die Sahara nach Mekka; seine Freigebigkeit war so groß, dass nach den Berichten der Goldwert in Kairo sank. Später brachte er Gelehrte und Baumeister nach Mali mit."],
    ar: ["أي حاكم لإمبراطورية مالي حجّ سنة 724هـ (1324م) في رحلة مشهورة ووزّع الذهب في طريقه؟", ["منسا موسى", "أسكيا محمد", "سني علي", "عثمان بن فودي"], "سافر منسا موسى عبر الصحراء إلى مكة في موكب ضخم، وبلغ كرمه حتى تذكر الأخبار أن سعر الذهب انخفض في القاهرة، ثم عاد بعلماء وبنّائين إلى مالي."] },

  { id: "hs-029", s: "history", g: 1, d: 2, t: ["historians", "works"], src: "Ibn Khaldūn, al-Muqaddima, introduction",
    en: ["Which scholar wrote the Muqaddima, an introduction to the study of history and society?", ["Ibn Khaldūn", "al-Ṭabarī", "Ibn Kathīr", "al-Masʿūdī"], "Ibn Khaldūn (732–808 AH, commonly given) wrote the Muqaddima as the introduction to his universal history, Kitāb al-ʿIbar, discussing the rise and fall of states and the nature of society."],
    de: ["Welcher Gelehrte schrieb die Muqaddima, eine Einführung in die Erforschung von Geschichte und Gesellschaft?", ["Ibn Ḫaldūn", "aṭ-Ṭabarī", "Ibn Kaṯīr", "al-Masʿūdī"], "Ibn Ḫaldūn (732–808 n. H., gängige Angabe) schrieb die Muqaddima als Einleitung zu seiner Universalgeschichte Kitāb al-ʿIbar und erörterte Aufstieg und Untergang von Staaten sowie das Wesen der Gesellschaft."],
    ar: ["أي عالم ألّف «المقدمة» وهي تمهيد لدراسة التاريخ والاجتماع؟", ["ابن خلدون", "الطبري", "ابن كثير", "المسعودي"], "كتب ابن خلدون (732–808هـ على المشهور) المقدمة تمهيدًا لتاريخه العام «كتاب العبر»، وبحث فيها قيام الدول وسقوطها وطبيعة العمران."] },

  { id: "hs-030", s: "history", g: 1, d: 2, t: ["sciences", "abbasids"], src: "Ibn al-Nadīm, al-Fihrist; standard histories of Islamic science",
    en: ["Which scholar of the Abbasid period wrote a famous book on al-jabr and gave algebra its name?", ["Muḥammad ibn Mūsā al-Khwārizmī", "Ibn al-Haytham", "Ibn Sīnā", "al-Zahrāwī"], "Al-Khwārizmī wrote al-Kitāb al-Mukhtaṣar fī Ḥisāb al-Jabr wa-l-Muqābala at the court of al-Maʾmūn. The word algebra comes from al-jabr, and ‘algorithm’ from his name."],
    de: ["Welcher Gelehrte der Abbasidenzeit schrieb ein berühmtes Buch über al-ǧabr und gab der Algebra ihren Namen?", ["Muḥammad ibn Mūsā al-Ḫwārizmī", "Ibn al-Haiṯam", "Ibn Sīnā", "az-Zahrāwī"], "Al-Ḫwārizmī schrieb al-Kitāb al-Muḫtaṣar fī Ḥisāb al-Ǧabr wa-l-Muqābala am Hof al-Maʾmūns. Das Wort Algebra stammt von al-ǧabr, ‚Algorithmus‘ von seinem Namen."],
    ar: ["أي عالم من العصر العباسي ألّف كتابًا مشهورًا في الجبر وأعطى علم الجبر اسمه؟", ["محمد بن موسى الخوارزمي", "ابن الهيثم", "ابن سينا", "الزهراوي"], "ألّف الخوارزمي «الكتاب المختصر في حساب الجبر والمقابلة» في بلاط المأمون، ومن «الجبر» أُخذت كلمة algebra الأوروبية، ومن اسمه كلمة algorithm."] },

  // ---------- Stage 2 (preparatory) ----------
  { id: "hs-031", s: "history", g: 2, d: 2, t: ["rashidun", "abu-bakr"], src: "Ibn Hishām, al-Sīra al-Nabawiyya, on the events at Saqīfat Banī Sāʿida; Ibn Kathīr, al-Bidāya wa-l-Nihāya",
    en: ["Where did the Anṣār gather after the Prophet's death, which led to the choice of Abū Bakr?", ["The hall (saqīfa) of Banū Sāʿida", "The Mosque of Qubāʾ", "The house of ʿĀʾisha", "The marketplace of Madīna"], "The Anṣār met at the saqīfa of Banū Sāʿida to choose a leader. Abū Bakr, ʿUmar and Abū ʿUbayda joined them, and after discussion the pledge was given to Abū Bakr."],
    de: ["Wo versammelten sich die Anṣār nach dem Tod des Propheten, was zur Wahl Abū Bakrs führte?", ["In der Halle (Saqīfa) der Banū Sāʿida", "In der Moschee von Qubāʾ", "Im Haus der ʿĀʾiša", "Auf dem Markt von Medina"], "Die Anṣār trafen sich in der Saqīfa der Banū Sāʿida, um einen Anführer zu wählen. Abū Bakr, ʿUmar und Abū ʿUbaida stießen dazu, und nach der Beratung wurde Abū Bakr gehuldigt."],
    ar: ["أين اجتمع الأنصار بعد وفاة النبي ﷺ مما انتهى إلى اختيار أبي بكر؟", ["في سقيفة بني ساعدة", "في مسجد قباء", "في بيت عائشة", "في سوق المدينة"], "اجتمع الأنصار في سقيفة بني ساعدة للتشاور في أمر الخلافة، وحضر أبو بكر وعمر وأبو عبيدة، وبعد النقاش بويع أبو بكر."] },

  { id: "hs-032", s: "history", g: 2, d: 2, t: ["rashidun", "ridda"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, on the Battle of al-Yamāma",
    en: ["Which false prophet was killed at the Battle of al-Yamāma in the wars of apostasy?", ["Musaylima", "al-Aswad al-ʿAnsī", "Ṭulayḥa al-Asadī", "Sajāḥ"], "Musaylima of Banū Ḥanīfa was killed at al-Yamāma (12 AH) and many Quran reciters fell in the battle. Al-Aswad was killed in Yemen and Ṭulayḥa and Sajāḥ later repented or retreated."],
    de: ["Welcher falsche Prophet wurde in den Abfallkriegen bei der Schlacht von al-Yamāma getötet?", ["Musailima", "al-Aswad al-ʿAnsī", "Ṭulaiḥa al-Asadī", "Saǧāḥ"], "Musailima von den Banū Ḥanīfa fiel bei al-Yamāma (12 n. H.), und viele Koranrezitatoren starben in der Schlacht. Al-Aswad wurde im Jemen getötet, Ṭulaiḥa und Saǧāḥ bereuten später oder zogen sich zurück."],
    ar: ["أي مدعٍ للنبوة قُتل في معركة اليمامة في حروب الردة؟", ["مسيلمة الكذاب", "الأسود العنسي", "طليحة الأسدي", "سجاح"], "قُتل مسيلمة من بني حنيفة في اليمامة سنة 12هـ واستُشهد فيها كثير من القراء، أما الأسود فقُتل في اليمن، وطليحة وسجاح تابا أو انسحبا."] },

  { id: "hs-033", s: "history", g: 2, d: 2, t: ["conquests", "military-leaders"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, biography of Khālid ibn al-Walīd",
    en: ["Which Companion, nicknamed Sayf Allāh (the sword of God), led the Muslim armies in many early victories?", ["Khālid ibn al-Walīd", "ʿAmr ibn al-ʿĀṣ", "Saʿd ibn Abī Waqqāṣ", "Abū ʿUbayda ibn al-Jarrāḥ"], "The Prophet gave Khālid ibn al-Walīd this title after Mūta. He fought in the wars of apostasy and the conquest of Iraq and Syria, including the battle of Yarmūk."],
    de: ["Welcher Gefährte, mit dem Beinamen Saif Allāh (Schwert Gottes), führte die muslimischen Heere in vielen frühen Siegen?", ["Ḫālid ibn al-Walīd", "ʿAmr ibn al-ʿĀṣ", "Saʿd ibn Abī Waqqāṣ", "Abū ʿUbaida ibn al-Ǧarrāḥ"], "Der Prophet gab Ḫālid ibn al-Walīd diesen Titel nach Mūta. Er kämpfte in den Abfallkriegen und bei der Eroberung des Irak und Syriens, einschließlich der Schlacht am Yarmūk."],
    ar: ["أي صحابي لُقّب بسيف الله وقاد الجيوش الإسلامية في انتصارات مبكرة كثيرة؟", ["خالد بن الوليد", "عمرو بن العاص", "سعد بن أبي وقاص", "أبو عبيدة بن الجراح"], "لقّب النبي ﷺ خالد بن الوليد بهذا اللقب بعد مؤتة، وقاتل في الردة وفتوح العراق والشام ومنها اليرموك."] },

  { id: "hs-034", s: "history", g: 2, d: 2, t: ["conquests", "battles"], src: "al-Balādhurī, Futūḥ al-Buldān, on the conquest of Iraq",
    en: ["Against which empire was the Battle of al-Qādisiyya fought under the command of Saʿd ibn Abī Waqqāṣ?", ["The Sasanian Persian empire", "The Byzantine empire", "The Visigothic kingdom", "The Crusader kingdoms"], "Al-Qādisiyya (commonly dated 15 AH) broke the Sasanian army and opened Iraq to the Muslims. The Byzantines were fought at Yarmūk."],
    de: ["Gegen welches Reich wurde die Schlacht von al-Qādisiyya unter dem Befehl von Saʿd ibn Abī Waqqāṣ geschlagen?", ["Das sasanidisch-persische Reich", "Das byzantinische Reich", "Das westgotische Königreich", "Die Kreuzfahrerstaaten"], "Al-Qādisiyya (gängig auf 15 n. H. datiert) brach das sasanidische Heer und öffnete den Irak für die Muslime. Gegen die Byzantiner wurde am Yarmūk gekämpft."],
    ar: ["ضد أي إمبراطورية دارت معركة القادسية بقيادة سعد بن أبي وقاص؟", ["الإمبراطورية الساسانية الفارسية", "الإمبراطورية البيزنطية", "المملكة القوطية", "الممالك الصليبية"], "حطمت القادسية (المشهور 15هـ) الجيش الساساني وفتحت العراق أمام المسلمين، أما البيزنطيون فقوتلوا في اليرموك."] },

  { id: "hs-035", s: "history", g: 2, d: 2, t: ["conquests", "egypt"], src: "al-Balādhurī, Futūḥ al-Buldān, on the conquest of Egypt",
    en: ["Which commander led the conquest of Egypt under ʿUmar and founded the garrison city of al-Fusṭāṭ?", ["ʿAmr ibn al-ʿĀṣ", "Khālid ibn al-Walīd", "ʿUqba ibn Nāfiʿ", "al-Zubayr ibn al-ʿAwwām"], "ʿAmr ibn al-ʿĀṣ entered Egypt in about 20 AH and founded al-Fusṭāṭ with the first mosque in Africa, which still bears his name. Later Cairo grew near this site."],
    de: ["Welcher Befehlshaber führte unter ʿUmar die Eroberung Ägyptens an und gründete die Garnisonsstadt al-Fusṭāṭ?", ["ʿAmr ibn al-ʿĀṣ", "Ḫālid ibn al-Walīd", "ʿUqba ibn Nāfiʿ", "az-Zubair ibn al-ʿAwwām"], "ʿAmr ibn al-ʿĀṣ zog um 20 n. H. in Ägypten ein und gründete al-Fusṭāṭ mit der ersten Moschee Afrikas, die noch heute seinen Namen trägt. Später wuchs Kairo in der Nähe dieses Ortes."],
    ar: ["أي قائد فتح مصر في عهد عمر وأسس مدينة الفسطاط؟", ["عمرو بن العاص", "خالد بن الوليد", "عقبة بن نافع", "الزبير بن العوام"], "دخل عمرو بن العاص مصر نحو سنة 20هـ وأسس الفسطاط ومسجدها الأول في إفريقيا الذي ما زال يحمل اسمه، ونشأت القاهرة لاحقًا قرب موضعها."] },

  { id: "hs-036", s: "history", g: 2, d: 3, t: ["rashidun", "umar", "administration"], src: "al-Māwardī, al-Aḥkām al-Sulṭāniyya; al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk",
    en: ["What was the dīwān that ʿUmar established?", ["A register of soldiers and stipends paid from the public treasury", "A court for criminal cases", "A school for the Companions' children", "A council of poets"], "ʿUmar created the dīwān to record the fighters and others entitled to stipends from the state treasury (bayt al-māl), ranking them by precedence in Islam. The word later came to mean government bureau."],
    de: ["Was war der Dīwān, den ʿUmar einrichtete?", ["Ein Register der Soldaten und Bezüge, die aus der Staatskasse gezahlt wurden", "Ein Gericht für Strafsachen", "Eine Schule für die Kinder der Gefährten", "Ein Rat der Dichter"], "ʿUmar schuf den Dīwān, um die Kämpfer und andere Anspruchsberechtigte auf Bezüge aus der Staatskasse (Bait al-Māl) zu erfassen, nach ihrem Vorrang im Islam geordnet. Das Wort bezeichnete später ein Regierungsamt."],
    ar: ["ما الديوان الذي أنشأه عمر؟", ["سجل بأسماء الجند وأعطياتهم من بيت المال", "محكمة للقضايا الجنائية", "مدرسة لأبناء الصحابة", "مجلس للشعراء"], "أنشأ عمر الديوان لتسجيل المقاتلين وغيرهم ممن لهم عطاء من بيت المال مرتّبين بحسب سبقهم في الإسلام، ثم صارت الكلمة تعني الدائرة الحكومية."] },

  { id: "hs-037", s: "history", g: 2, d: 3, t: ["rashidun", "umar", "shura"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb Faḍāʾil al-Ṣaḥāba (the shūrā after ʿUmar); Ibn Kathīr, al-Bidāya wa-l-Nihāya",
    en: ["ʿUmar named a council of six to choose his successor. Which of these was NOT among them?", ["Abū ʿUbayda ibn al-Jarrāḥ", "ʿAbd al-Raḥmān ibn ʿAwf", "Saʿd ibn Abī Waqqāṣ", "al-Zubayr ibn al-ʿAwwām"], "The six were ʿUthmān, ʿAlī, Ṭalḥa, al-Zubayr, Saʿd and ʿAbd al-Raḥmān ibn ʿAwf. Abū ʿUbayda had already died in the plague of ʿAmwās (18 AH). ʿAbd al-Raḥmān ibn ʿAwf conducted the consultation that chose ʿUthmān."],
    de: ["ʿUmar bestimmte einen Rat von sechs Männern zur Wahl seines Nachfolgers. Wer von diesen gehörte NICHT dazu?", ["Abū ʿUbaida ibn al-Ǧarrāḥ", "ʿAbd ar-Raḥmān ibn ʿAuf", "Saʿd ibn Abī Waqqāṣ", "az-Zubair ibn al-ʿAwwām"], "Die sechs waren ʿUṯmān, ʿAlī, Ṭalḥa, az-Zubair, Saʿd und ʿAbd ar-Raḥmān ibn ʿAuf. Abū ʿUbaida war schon an der Pest von ʿAmwās (18 n. H.) gestorben. ʿAbd ar-Raḥmān ibn ʿAuf leitete die Beratung, die ʿUṯmān wählte."],
    ar: ["عيّن عمر ستة للشورى في اختيار خليفته. من ليس منهم من هؤلاء؟", ["أبو عبيدة بن الجراح", "عبد الرحمن بن عوف", "سعد بن أبي وقاص", "الزبير بن العوام"], "أصحاب الشورى هم عثمان وعلي وطلحة والزبير وسعد وعبد الرحمن بن عوف، أما أبو عبيدة فقد توفي في طاعون عمواس سنة 18هـ، وتولى عبد الرحمن بن عوف المشاورة التي انتهت إلى عثمان."] },

  { id: "hs-038", s: "history", g: 2, d: 3, t: ["rashidun", "umar", "plague"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, events of 18 AH",
    en: ["Which disaster struck Syria in 18 AH and killed Abū ʿUbayda and Muʿādh ibn Jabal among many others?", ["The plague of ʿAmwās", "The Year of Ashes famine", "The earthquake of Antioch", "The battle of the Camel"], "The plague of ʿAmwās (Emmaus) struck Syria and Palestine in 18 AH. The Year of Ashes famine in the Hijāz fell in the same period but affected Arabia, not Syria."],
    de: ["Welche Katastrophe traf 18 n. H. Syrien und tötete unter vielen anderen Abū ʿUbaida und Muʿāḏ ibn Ǧabal?", ["Die Pest von ʿAmwās", "Die Hungersnot des Aschejahres", "Das Erdbeben von Antiochia", "Die Kamelschlacht"], "Die Pest von ʿAmwās (Emmaus) suchte 18 n. H. Syrien und Palästina heim. Die Hungersnot des Aschejahres im Hidschas fiel in dieselbe Zeit, betraf aber Arabien, nicht Syrien."],
    ar: ["أي كارثة أصابت الشام سنة 18هـ وأودت بأبي عبيدة ومعاذ بن جبل وغيرهما؟", ["طاعون عمواس", "مجاعة عام الرمادة", "زلزال أنطاكية", "معركة الجمل"], "أصاب طاعون عمواس الشام وفلسطين سنة 18هـ، أما مجاعة عام الرمادة فكانت في الحجاز في الفترة نفسها ولم تكن في الشام."] },

  { id: "hs-039", s: "history", g: 2, d: 3, t: ["rashidun", "uthman", "navy"], src: "al-Balādhurī, Futūḥ al-Buldān, on the conquest of Cyprus",
    en: ["Under ʿUthmān, which commander was permitted to build a fleet and raid Cyprus around 28 AH?", ["Muʿāwiya ibn Abī Sufyān", "ʿAmr ibn al-ʿĀṣ", "Saʿd ibn Abī Waqqāṣ", "Abū Mūsā al-Ashʿarī"], "ʿUmar had refused sea expeditions as dangerous, but ʿUthmān allowed Muʿāwiya, governor of Syria, to launch the first Muslim naval campaign, against Cyprus. The Battle of the Masts followed in 34 AH."],
    de: ["Welchem Befehlshaber wurde unter ʿUṯmān gestattet, eine Flotte zu bauen und um 28 n. H. Zypern anzugreifen?", ["Muʿāwiya ibn Abī Sufyān", "ʿAmr ibn al-ʿĀṣ", "Saʿd ibn Abī Waqqāṣ", "Abū Mūsā al-Ašʿarī"], "ʿUmar hatte Seezüge als zu gefährlich abgelehnt, aber ʿUṯmān erlaubte Muʿāwiya, dem Statthalter Syriens, den ersten muslimischen Seefeldzug gegen Zypern. Die Schlacht der Masten folgte 34 n. H."],
    ar: ["أي قائد أُذن له في عهد عثمان ببناء أسطول وغزو قبرص نحو سنة 28هـ؟", ["معاوية بن أبي سفيان", "عمرو بن العاص", "سعد بن أبي وقاص", "أبو موسى الأشعري"], "كان عمر قد منع ركوب البحر خشية الخطر، فأذن عثمان لمعاوية والي الشام بأول غزوة بحرية إلى قبرص، وتلتها معركة ذات الصواري سنة 34هـ."] },

  { id: "hs-040", s: "history", g: 2, d: 2, t: ["fitna", "ali"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, events of 36 AH",
    en: ["What was the Battle of the Camel (al-Jamal) in 36 AH?", ["A clash near Basra between the army of ʿAlī and the party of ʿĀʾisha, Ṭalḥa and al-Zubayr", "A battle between ʿAlī and the Khawārij", "A battle with the Byzantines in Syria", "A battle over the control of Makka"], "After ʿUthmān's killing, ʿĀʾisha, Ṭalḥa and al-Zubayr went to Basra demanding justice for him; war broke out against their intentions near Basra. ʿAlī won, and both Ṭalḥa and al-Zubayr were killed."],
    de: ["Was war die Kamelschlacht (al-Ǧamal) im Jahr 36 n. H.?", ["Ein Zusammenstoß bei Basra zwischen dem Heer ʿAlīs und der Partei von ʿĀʾiša, Ṭalḥa und az-Zubair", "Eine Schlacht zwischen ʿAlī und den Ḫawāriǧ", "Eine Schlacht gegen die Byzantiner in Syrien", "Eine Schlacht um die Herrschaft über Mekka"], "Nach der Ermordung ʿUṯmāns gingen ʿĀʾiša, Ṭalḥa und az-Zubair nach Basra und forderten Gerechtigkeit für ihn; entgegen ihrer Absicht brach bei Basra Krieg aus. ʿAlī siegte, und sowohl Ṭalḥa als auch az-Zubair kamen ums Leben."],
    ar: ["ما معركة الجمل سنة 36هـ؟", ["مواجهة قرب البصرة بين جيش علي وفريق عائشة وطلحة والزبير", "معركة بين علي والخوارج", "معركة مع البيزنطيين في الشام", "معركة على حكم مكة"], "بعد مقتل عثمان توجهت عائشة وطلحة والزبير إلى البصرة للمطالبة بالقصاص، فاندلع القتال خلافًا لقصدهم قرب البصرة، وانتصر علي وقُتل طلحة والزبير."] },

  { id: "hs-041", s: "history", g: 2, d: 2, t: ["fitna", "ali", "muawiya"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, events of 37 AH",
    en: ["Which battle in 37 AH between the armies of ʿAlī and Muʿāwiya ended with the call to arbitration?", ["Ṣiffīn", "al-Qādisiyya", "Naharwān", "Muʾta"], "At Ṣiffīn on the Euphrates the armies fought for weeks until Muʿāwiya's side raised copies of the Quran and called for arbitration. The arbitration split ʿAlī's camp and produced the Khawārij."],
    de: ["Welche Schlacht des Jahres 37 n. H. zwischen den Heeren ʿAlīs und Muʿāwiyas endete mit dem Ruf nach einem Schiedsgericht?", ["Ṣiffīn", "al-Qādisiyya", "Nahrawān", "Muʾta"], "Bei Ṣiffīn am Euphrat kämpften die Heere wochenlang, bis Muʿāwiyas Seite Koranexemplare erhob und zum Schiedsgericht aufrief. Das Schiedsgericht spaltete ʿAlīs Lager und brachte die Ḫawāriǧ hervor."],
    ar: ["أي معركة سنة 37هـ بين جيشي علي ومعاوية انتهت بالدعوة إلى التحكيم؟", ["صفين", "القادسية", "النهروان", "مؤتة"], "قاتل الجيشان أسابيع في صفين على الفرات حتى رفع أصحاب معاوية المصاحف ودعوا إلى التحكيم، فانقسم معسكر علي وظهر الخوارج."] },

  { id: "hs-042", s: "history", g: 2, d: 3, t: ["fitna", "khawarij"], src: "al-Shahristānī, al-Milal wa-l-Niḥal; al-Ṭabarī, Tārīkh",
    en: ["Who were the Khawārij?", ["Those who left ʿAlī's army after the arbitration at Ṣiffīn and then fought him", "The people who killed ʿUthmān", "The Anṣār of Madīna", "The followers of Muʿāwiya in Syria"], "The Khawārij (‘those who went out’) objected to the arbitration, left ʿAlī's army and were fought by him at Naharwān in 38 AH. ʿAlī was later killed by a man of this movement."],
    de: ["Wer waren die Ḫawāriǧ?", ["Die, die nach dem Schiedsgericht von Ṣiffīn ʿAlīs Heer verließen und dann gegen ihn kämpften", "Die Leute, die ʿUṯmān töteten", "Die Anṣār von Medina", "Die Anhänger Muʿāwiyas in Syrien"], "Die Ḫawāriǧ (‚die Ausgezogenen‘) lehnten das Schiedsgericht ab, verließen ʿAlīs Heer und wurden von ihm 38 n. H. bei Nahrawān bekämpft. ʿAlī wurde später von einem Mann dieser Bewegung getötet."],
    ar: ["من الخوارج؟", ["الذين خرجوا على جيش علي بعد التحكيم في صفين ثم قاتلوه", "الذين قتلوا عثمان", "أنصار المدينة", "أتباع معاوية في الشام"], "اعترض الخوارج على التحكيم وخرجوا من جيش علي فقاتلهم في النهروان سنة 38هـ، وقتل عليًّا لاحقًا رجل منهم."] },

  { id: "hs-043", s: "history", g: 2, d: 2, t: ["umayyads", "hasan"], src: "al-Bukhārī, Ṣaḥīḥ, Kitāb al-Ṣulḥ (the hadith about al-Ḥasan); al-Ṭabarī, Tārīkh",
    en: ["What did al-Ḥasan ibn ʿAlī do in 41 AH to end the strife?", ["He handed over the caliphate to Muʿāwiya", "He led an army against Muʿāwiya in Syria", "He left for Yemen", "He asked the Byzantines for help"], "Al-Ḥasan reconciled with Muʿāwiya and surrendered the office in order to save Muslim blood; the year is called ʿām al-jamāʿa. A hadith in al-Bukhārī records the Prophet's words about him as a means to reconcile two groups of Muslims."],
    de: ["Was tat al-Ḥasan ibn ʿAlī 41 n. H., um die Zwietracht zu beenden?", ["Er übergab das Kalifat an Muʿāwiya", "Er führte ein Heer gegen Muʿāwiya in Syrien", "Er ging in den Jemen", "Er bat die Byzantiner um Hilfe"], "Al-Ḥasan söhnte sich mit Muʿāwiya aus und gab das Amt ab, um Muslimenblut zu schonen; das Jahr heißt ʿĀm al-Ǧamāʿa. Ein Hadith bei al-Buḫārī überliefert die Worte des Propheten über ihn als Mittel, zwei Gruppen von Muslimen zu versöhnen."],
    ar: ["ماذا فعل الحسن بن علي سنة 41هـ لإنهاء الفتنة؟", ["تنازل عن الخلافة لمعاوية", "قاد جيشًا ضد معاوية في الشام", "غادر إلى اليمن", "استنجد بالبيزنطيين"], "صالح الحسن معاوية وتنازل عن الأمر حقنًا لدماء المسلمين، ويسمى العام عام الجماعة، وفي صحيح البخاري حديث في ثناء النبي ﷺ على إصلاحه بين فئتين من المسلمين."] },

  { id: "hs-044", s: "history", g: 2, d: 2, t: ["umayyads", "karbala"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, events of 61 AH; Ibn Kathīr, al-Bidāya wa-l-Nihāya",
    en: ["What happened at Karbalāʾ in Muḥarram 61 AH?", ["al-Ḥusayn ibn ʿAlī and his companions were killed by the forces of the Umayyad governor", "The Muslims defeated the Byzantines", "Makka was besieged by the Umayyads", "The Mongols reached Iraq"], "Al-Ḥusayn, grandson of the Prophet, set out for Kūfa after being invited and was stopped at Karbalāʾ, where he and a small band were killed on 10 Muḥarram. The event deeply affected the Muslim community."],
    de: ["Was geschah im Muḥarram 61 n. H. bei Kerbela?", ["Al-Ḥusain ibn ʿAlī und seine Gefährten wurden von den Truppen des umayyadischen Statthalters getötet", "Die Muslime besiegten die Byzantiner", "Mekka wurde von den Umayyaden belagert", "Die Mongolen erreichten den Irak"], "Al-Ḥusain, Enkel des Propheten, brach nach einer Einladung nach Kūfa auf und wurde bei Kerbela aufgehalten, wo er und eine kleine Schar am 10. Muḥarram getötet wurden. Das Ereignis erschütterte die muslimische Gemeinschaft tief."],
    ar: ["ماذا حدث في كربلاء في محرم سنة 61هـ؟", ["قُتل الحسين بن علي وأصحابه على يد جيش والي الأمويين", "انتصر المسلمون على البيزنطيين", "حاصر الأمويون مكة", "وصل المغول إلى العراق"], "خرج الحسين، سبط النبي ﷺ، إلى الكوفة بعد أن دُعي إليها فاعترضه جيش في كربلاء وقُتل مع نفر قليل يوم عاشوراء، وكان للحدث أثر عميق في الأمة."] },

  { id: "hs-045", s: "history", g: 2, d: 2, t: ["umayyads", "monuments"], src: "al-Ṭabarī, Tārīkh; standard histories of Islamic architecture",
    en: ["Which Umayyad caliph built the Dome of the Rock in Jerusalem, completed around 72 AH?", ["ʿAbd al-Malik ibn Marwān", "al-Walīd ibn ʿAbd al-Malik", "Muʿāwiya ibn Abī Sufyān", "Hishām ibn ʿAbd al-Malik"], "ʿAbd al-Malik ordered the Dome of the Rock, the oldest surviving major Islamic monument. His son al-Walīd later built the Great Mosque of Damascus and renovated al-Aqṣā."],
    de: ["Welcher umayyadische Kalif ließ den Felsendom in Jerusalem errichten, um 72 n. H. vollendet?", ["ʿAbd al-Malik ibn Marwān", "al-Walīd ibn ʿAbd al-Malik", "Muʿāwiya ibn Abī Sufyān", "Hišām ibn ʿAbd al-Malik"], "ʿAbd al-Malik ließ den Felsendom bauen, das älteste erhaltene bedeutende islamische Bauwerk. Sein Sohn al-Walīd erbaute später die Große Moschee von Damaskus und erneuerte al-Aqṣā."],
    ar: ["أي خليفة أموي بنى قبة الصخرة في القدس، وأُنجزت نحو سنة 72هـ؟", ["عبد الملك بن مروان", "الوليد بن عبد الملك", "معاوية بن أبي سفيان", "هشام بن عبد الملك"], "أمر عبد الملك ببناء قبة الصخرة، وهي أقدم أثر إسلامي كبير باقٍ، ثم بنى ابنه الوليد الجامع الأموي بدمشق وجدد المسجد الأقصى."] },

  { id: "hs-046", s: "history", g: 2, d: 3, t: ["umayyads", "umar-ii"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, on ʿUmar ibn ʿAbd al-ʿAzīz",
    en: ["Which Umayyad caliph, who reigned about two and a half years from 99 AH, is remembered for justice and for ordering the collection of hadith?", ["ʿUmar ibn ʿAbd al-ʿAzīz", "Yazīd ibn Muʿāwiya", "Marwān ibn al-Ḥakam", "al-Walīd ibn Yazīd"], "ʿUmar ibn ʿAbd al-ʿAzīz (r. 99–101 AH) lifted unjust taxes, stopped the cursing of ʿAlī from pulpits and, according to reports, instructed scholars such as Ibn Shihāb al-Zuhrī to write down the sunna."],
    de: ["Welcher umayyadische Kalif, der etwa zweieinhalb Jahre ab 99 n. H. regierte, ist für Gerechtigkeit und den Auftrag zur Sammlung von Hadithen bekannt?", ["ʿUmar ibn ʿAbd al-ʿAzīz", "Yazīd ibn Muʿāwiya", "Marwān ibn al-Ḥakam", "al-Walīd ibn Yazīd"], "ʿUmar ibn ʿAbd al-ʿAzīz (reg. 99–101 n. H.) schaffte ungerechte Steuern ab, beendete die Verfluchung ʿAlīs von den Kanzeln und wies nach Berichten Gelehrte wie Ibn Šihāb az-Zuhrī an, die Sunna aufzuschreiben."],
    ar: ["أي خليفة أموي حكم نحو سنتين ونصف من سنة 99هـ واشتهر بالعدل وبالأمر بتدوين الحديث؟", ["عمر بن عبد العزيز", "يزيد بن معاوية", "مروان بن الحكم", "الوليد بن يزيد"], "رفع عمر بن عبد العزيز (99–101هـ) المظالم والضرائب الجائرة وأوقف سبّ علي على المنابر، وتذكر الأخبار أنه كتب إلى العلماء كابن شهاب الزهري بتدوين السنة."] },

  { id: "hs-047", s: "history", g: 2, d: 3, t: ["abbasids", "culture"], src: "Ibn al-Nadīm, al-Fihrist; al-Ṭabarī, Tārīkh",
    en: ["Which Abbasid caliph is especially associated with the Bayt al-Ḥikma (House of Wisdom) and the translation movement in Baghdad?", ["al-Maʾmūn", "al-Manṣūr", "al-Mutawakkil", "al-Mustaʿṣim"], "Al-Maʾmūn (r. 198–218 AH) supported the translation of Greek, Persian and Indian works into Arabic and the work of scholars like al-Khwārizmī. The translation activity had begun earlier under al-Manṣūr and Hārūn al-Rashīd."],
    de: ["Welcher abbasidische Kalif wird besonders mit dem Bait al-Ḥikma (Haus der Weisheit) und der Übersetzungsbewegung in Bagdad verbunden?", ["al-Maʾmūn", "al-Manṣūr", "al-Mutawakkil", "al-Mustaʿṣim"], "Al-Maʾmūn (reg. 198–218 n. H.) förderte die Übersetzung griechischer, persischer und indischer Werke ins Arabische sowie die Arbeit von Gelehrten wie al-Ḫwārizmī. Die Übersetzungstätigkeit hatte schon unter al-Manṣūr und Hārūn ar-Rašīd begonnen."],
    ar: ["أي خليفة عباسي ارتبط اسمه خاصة ببيت الحكمة وحركة الترجمة في بغداد؟", ["المأمون", "المنصور", "المتوكل", "المستعصم"], "رعى المأمون (198–218هـ) ترجمة الكتب اليونانية والفارسية والهندية إلى العربية وعمل علماء مثل الخوارزمي، وكانت الترجمة قد بدأت قبله في عهد المنصور وهارون الرشيد."] },

  { id: "hs-048", s: "history", g: 2, d: 3, t: ["abbasids", "mihna"], src: "al-Ṭabarī, Tārīkh; Ibn Kathīr, al-Bidāya wa-l-Nihāya, on the miḥna",
    en: ["What was the miḥna that began under al-Maʾmūn in 218 AH?", ["A state inquisition testing scholars on the doctrine that the Quran is created", "A famine in Iraq", "A war against the Byzantines", "A tax reform"], "Al-Maʾmūn, influenced by Muʿtazilī thinkers, required judges and scholars to affirm that the Quran is created. Aḥmad ibn Ḥanbal's refusal made him a symbol, and al-Mutawakkil ended the policy in about 234 AH."],
    de: ["Was war die Miḥna, die 218 n. H. unter al-Maʾmūn begann?", ["Eine staatliche Inquisition, die Gelehrte auf die Lehre prüfte, der Koran sei erschaffen", "Eine Hungersnot im Irak", "Ein Krieg gegen die Byzantiner", "Eine Steuerreform"], "Al-Maʾmūn verlangte, beeinflusst von mu‘tazilitischen Denkern, von Richtern und Gelehrten das Bekenntnis, der Koran sei erschaffen. Aḥmad ibn Ḥanbals Weigerung machte ihn zum Sinnbild, und al-Mutawakkil beendete die Politik um 234 n. H."],
    ar: ["ما المحنة التي بدأت في عهد المأمون سنة 218هـ؟", ["امتحان رسمي للعلماء في القول بخلق القرآن", "مجاعة في العراق", "حرب ضد البيزنطيين", "إصلاح ضريبي"], "فرض المأمون متأثرًا بالمعتزلة على القضاة والعلماء القول بخلق القرآن، وصار ثبات أحمد بن حنبل رمزًا، وأنهى المتوكل هذه السياسة نحو سنة 234هـ."] },

  { id: "hs-049", s: "history", g: 2, d: 3, t: ["education", "morocco"], src: "Ibn Abī Zarʿ, al-Anīs al-Muṭrib bi-Rawḍ al-Qirṭās; standard histories of Fez",
    en: ["Who founded the al-Qarawiyyīn mosque and school in Fez, around 245 AH (859 CE)?", ["Fāṭima al-Fihriyya", "Zubayda, wife of Hārūn al-Rashīd", "Shajar al-Durr", "ʿĀʾisha bint Ṭalḥa"], "Fāṭima al-Fihriyya, who had inherited wealth from her father, financed the mosque and its school, which became a major centre of learning and is often described as one of the oldest continuously operating educational institutions."],
    de: ["Wer gründete um 245 n. H. (859 n. Chr.) die Qarawiyyīn-Moschee und -Schule in Fès?", ["Fāṭima al-Fihriyya", "Zubaida, die Frau Hārūn ar-Rašīds", "Šaǧar ad-Durr", "ʿĀʾiša bint Ṭalḥa"], "Fāṭima al-Fihriyya, die von ihrem Vater Vermögen geerbt hatte, finanzierte die Moschee und ihre Schule, die ein bedeutendes Zentrum der Gelehrsamkeit wurde und oft als eine der ältesten ununterbrochen arbeitenden Bildungseinrichtungen beschrieben wird."],
    ar: ["من أسست جامع القرويين ومدرسته في فاس نحو سنة 245هـ (859م)؟", ["فاطمة الفهرية", "زبيدة زوجة هارون الرشيد", "شجرة الدر", "عائشة بنت طلحة"], "موّلت فاطمة الفهرية، وقد ورثت عن أبيها مالًا، بناء المسجد ومدرسته، فصار مركزًا علميًّا كبيرًا يُوصف بأنه من أقدم المؤسسات التعليمية المستمرة."] },

  { id: "hs-050", s: "history", g: 2, d: 3, t: ["mongols", "mamluks"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, events of 658 AH",
    en: ["Which Mamluk victory in 658 AH (1260 CE) stopped the Mongol advance towards Egypt?", ["ʿAyn Jālūt", "Ḥaṭṭīn", "Malāzgird", "al-Zallāqa"], "At ʿAyn Jālūt in Palestine the Mamluk army under Sultan Qutuz, with Baybars among its commanders, defeated the Mongols. Ḥaṭṭīn was against the Crusaders, Malāzgird against Byzantium and al-Zallāqa in Spain."],
    de: ["Welcher Mamlukensieg des Jahres 658 n. H. (1260 n. Chr.) stoppte den mongolischen Vormarsch auf Ägypten?", ["ʿAin Ǧālūt", "Ḥaṭṭīn", "Malāzgird", "az-Zallāqa"], "Bei ʿAin Ǧālūt in Palästina besiegte das Mamlukenheer unter Sultan Quṭuz, mit Baibars unter den Befehlshabern, die Mongolen. Ḥaṭṭīn war gegen die Kreuzfahrer, Malāzgird gegen Byzanz und az-Zallāqa in Spanien."],
    ar: ["أي نصر مملوكي سنة 658هـ (1260م) أوقف تقدم المغول نحو مصر؟", ["عين جالوت", "حطين", "ملاذكرد", "الزلاقة"], "هزم الجيش المملوكي بقيادة السلطان قطز، وبيبرس بين قادته، المغول في عين جالوت بفلسطين، أما حطين فضد الصليبيين وملاذكرد ضد البيزنطيين والزلاقة في الأندلس."] },

  { id: "hs-051", s: "history", g: 2, d: 3, t: ["andalus", "fall-of-granada"], src: "al-Maqqarī, Nafḥ al-Ṭīb, on the end of Muslim rule in Granada",
    en: ["In which year did Granada, the last Muslim kingdom in Spain, fall?", ["1492 CE (897 AH)", "1085 CE", "1212 CE", "1031 CE"], "Granada, ruled by the Naṣrid dynasty, surrendered to the Catholic monarchs in January 1492. The year 1085 saw Toledo's fall, 1212 the defeat at Las Navas de Tolosa and 1031 the end of the Caliphate of Córdoba."],
    de: ["In welchem Jahr fiel Granada, das letzte muslimische Königreich in Spanien?", ["1492 n. Chr. (897 n. H.)", "1085 n. Chr.", "1212 n. Chr.", "1031 n. Chr."], "Granada, von der Nasridendynastie regiert, ergab sich im Januar 1492 den Katholischen Königen. 1085 fiel Toledo, 1212 war die Niederlage bei Las Navas de Tolosa und 1031 das Ende des Kalifats von Córdoba."],
    ar: ["في أي سنة سقطت غرناطة آخر الممالك الإسلامية في إسبانيا؟", ["1492م (897هـ)", "1085م", "1212م", "1031م"], "سلّمت غرناطة التي حكمها بنو نصر نفسها للملكين الكاثوليكيين في يناير 1492، أما 1085 فسقوط طليطلة و1212 هزيمة العقاب و1031 نهاية خلافة قرطبة."] },

  { id: "hs-052", s: "history", g: 2, d: 3, t: ["ottomans", "expansion"], src: "Ibn Iyās, Badāʾiʿ al-Zuhūr, on the Ottoman conquest of Egypt",
    en: ["Which Ottoman sultan conquered Syria and Egypt from the Mamluks in 1516–1517?", ["Selim I (Yavuz Sultan Selim)", "Muḥammad II", "Sulaymān I", "Murād IV"], "Selim I defeated the Mamluks at Marj Dābiq (1516) and al-Raydāniyya (1517) and took control of the Hijāz, becoming protector of the two holy cities. Later sources link him to the transfer of the caliphal title, a point historians debate."],
    de: ["Welcher osmanische Sultan eroberte 1516–1517 Syrien und Ägypten von den Mamluken?", ["Selim I. (Yavuz Sultan Selim)", "Muḥammad II.", "Sulaimān I.", "Murād IV."], "Selim I. besiegte die Mamluken bei Marǧ Dābiq (1516) und ar-Raidānīya (1517) und übernahm die Kontrolle über den Hidschas als Beschützer der beiden heiligen Städte. Spätere Quellen verbinden ihn mit der Übertragung des Kalifentitels, ein Punkt, den Historiker diskutieren."],
    ar: ["أي سلطان عثماني ضم الشام ومصر من المماليك سنة 1516–1517م؟", ["سليم الأول", "محمد الثاني", "سليمان الأول", "مراد الرابع"], "هزم سليم الأول المماليك في مرج دابق (1516) والريدانية (1517) وأخضع الحجاز فصار خادم الحرمين، وتربط مصادر متأخرة به انتقال لقب الخلافة وهي مسألة يناقشها المؤرخون."] },

  { id: "hs-053", s: "history", g: 2, d: 3, t: ["mughals", "india"], src: "Standard histories of the Mughal empire (e.g. Richards, The Mughal Empire)",
    en: ["Which Mughal emperor commissioned the Taj Mahal in Āgra as a tomb for his wife Mumtāz Maḥal?", ["Shāh Jahān", "Akbar", "Aurangzeb", "Bābur"], "Shāh Jahān built the Taj Mahal, completed in the mid-seventeenth century, after his wife's death in 1631. Bābur founded the dynasty at the First Battle of Pānīpat in 1526."],
    de: ["Welcher Mogulkaiser ließ das Taj Mahal in Āgra als Grabmal für seine Frau Mumtāz Maḥal errichten?", ["Šāh Ǧahān", "Akbar", "Aurangzeb", "Bābur"], "Šāh Ǧahān ließ das Taj Mahal erbauen, in der Mitte des 17. Jahrhunderts vollendet, nach dem Tod seiner Frau 1631. Bābur gründete die Dynastie 1526 in der ersten Schlacht von Pānīpat."],
    ar: ["أي إمبراطور مغولي في الهند أمر ببناء تاج محل في آغرا ضريحًا لزوجته ممتاز محل؟", ["شاه جهان", "أكبر", "أورنكزيب", "بابر"], "بنى شاه جهان تاج محل الذي اكتمل في منتصف القرن السابع عشر بعد وفاة زوجته سنة 1631، أما بابر فأسس الدولة بعد معركة بانيبت الأولى سنة 1526."] },

  { id: "hs-054", s: "history", g: 2, d: 3, t: ["sciences", "medicine"], src: "Ibn Abī Uṣaybiʿa, ʿUyūn al-Anbāʾ fī Ṭabaqāt al-Aṭibbāʾ; Ibn Sīnā, al-Qānūn fī al-Ṭibb",
    en: ["Which scholar of Bukhārā wrote al-Qānūn fī al-Ṭibb (The Canon of Medicine), used in medical teaching for centuries?", ["Ibn Sīnā (Avicenna)", "Ibn Rushd (Averroes)", "al-Rāzī (Rhazes)", "Ibn al-Nafīs"], "Ibn Sīnā (c. 370–428 AH) wrote the Canon, a systematic summary of medical knowledge that was taught in Europe and the Muslim world. Al-Rāzī wrote al-Ḥāwī and Ibn al-Nafīs described the pulmonary circulation."],
    de: ["Welcher Gelehrte aus Buchara schrieb al-Qānūn fī ṭ-Ṭibb (Der Kanon der Medizin), der jahrhundertelang im medizinischen Unterricht genutzt wurde?", ["Ibn Sīnā (Avicenna)", "Ibn Rušd (Averroes)", "ar-Rāzī (Rhazes)", "Ibn an-Nafīs"], "Ibn Sīnā (ca. 370–428 n. H.) schrieb den Kanon, eine systematische Zusammenfassung des medizinischen Wissens, das in Europa und der muslimischen Welt gelehrt wurde. Ar-Rāzī schrieb al-Ḥāwī, und Ibn an-Nafīs beschrieb den Lungenkreislauf."],
    ar: ["أي عالم من بخارى ألّف «القانون في الطب» الذي دُرِّس قرونًا؟", ["ابن سينا", "ابن رشد", "الرازي", "ابن النفيس"], "ألّف ابن سينا (نحو 370–428هـ) القانون وهو ملخص منهجي للمعرفة الطبية دُرِّس في أوروبا والعالم الإسلامي، أما الرازي فألّف «الحاوي» وابن النفيس وصف الدورة الدموية الرئوية."] },

  { id: "hs-055", s: "history", g: 2, d: 3, t: ["travel", "geography"], src: "Ibn Juzayy (ed.), Riḥlat Ibn Baṭṭūṭa (Tuḥfat al-Nuẓẓār)",
    en: ["Which traveller from Tangier wrote a famous account of his journeys across Africa, Asia and the Muslim lands in the 8th century AH?", ["Ibn Baṭṭūṭa", "Ibn Jubayr", "al-Idrīsī", "Ibn Ḥawqal"], "Ibn Baṭṭūṭa (703–c. 770 AH) travelled for about thirty years and dictated his Riḥla to Ibn Juzayy. Ibn Jubayr, al-Idrīsī and Ibn Ḥawqal are other geographers or travellers of earlier centuries."],
    de: ["Welcher Reisende aus Tanger schrieb im 8. Jh. n. H. einen berühmten Bericht über seine Reisen durch Afrika, Asien und die muslimischen Länder?", ["Ibn Baṭṭūṭa", "Ibn Ǧubair", "al-Idrīsī", "Ibn Ḥauqal"], "Ibn Baṭṭūṭa (703–ca. 770 n. H.) reiste etwa dreißig Jahre lang und diktierte seine Riḥla an Ibn Ǧuzayy. Ibn Ǧubair, al-Idrīsī und Ibn Ḥauqal sind andere Geographen oder Reisende früherer Jahrhunderte."],
    ar: ["أي رحالة من طنجة كتب في القرن الثامن الهجري كتابًا مشهورًا عن رحلاته في إفريقيا وآسيا وبلاد المسلمين؟", ["ابن بطوطة", "ابن جبير", "الإدريسي", "ابن حوقل"], "جاب ابن بطوطة (703–نحو 770هـ) الأرض قرابة ثلاثين عامًا وأملى «الرحلة» على ابن جزي، أما ابن جبير والإدريسي وابن حوقل فجغرافيون أو رحالة من قرون سابقة."] },

  { id: "hs-056", s: "history", g: 2, d: 3, t: ["historians", "works"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, introduction; al-Dhahabī, Siyar Aʿlām al-Nubalāʾ",
    en: ["Which scholar wrote the large chronicle Tārīkh al-Rusul wa-l-Mulūk, as well as a well-known Quran commentary?", ["Muḥammad ibn Jarīr al-Ṭabarī", "Ibn Kathīr", "Ibn al-Athīr", "al-Balādhurī"], "Al-Ṭabarī (224–310 AH, commonly given) wrote both Jāmiʿ al-Bayān in tafsīr and the universal history Tārīkh al-Rusul wa-l-Mulūk, which records events year by year with chains of transmitters."],
    de: ["Welcher Gelehrte schrieb die umfangreiche Chronik Tārīḫ ar-Rusul wa-l-Mulūk und zugleich einen bekannten Korankommentar?", ["Muḥammad ibn Ǧarīr aṭ-Ṭabarī", "Ibn Kaṯīr", "Ibn al-Aṯīr", "al-Balāḏurī"], "Aṭ-Ṭabarī (224–310 n. H., gängige Angabe) schrieb sowohl Ǧāmiʿ al-Bayān im Tafsīr als auch die Universalgeschichte Tārīḫ ar-Rusul wa-l-Mulūk, die Ereignisse Jahr für Jahr mit Überliefererketten verzeichnet."],
    ar: ["أي عالم ألّف الموسوعة التاريخية «تاريخ الرسل والملوك» وتفسيرًا مشهورًا للقرآن؟", ["محمد بن جرير الطبري", "ابن كثير", "ابن الأثير", "البلاذري"], "ألّف الطبري (224–310هـ على المشهور) «جامع البيان» في التفسير و«تاريخ الرسل والملوك» وهو تاريخ عام يسرد الأحداث بحسب السنين بالأسانيد."] },

  { id: "hs-057", s: "history", g: 2, d: 3, t: ["historians", "works"], src: "Ibn Kathīr, al-Bidāya wa-l-Nihāya, introduction",
    en: ["Which work by Ibn Kathīr is a universal history from creation to his own time?", ["al-Bidāya wa-l-Nihāya", "al-Kāmil fī al-Tārīkh", "Siyar Aʿlām al-Nubalāʾ", "Murūj al-Dhahab"], "Ibn Kathīr (701–774 AH, commonly given) wrote al-Bidāya wa-l-Nihāya, a history from the beginning of creation to the events of his time. Al-Kāmil is by Ibn al-Athīr, Siyar by al-Dhahabī and Murūj by al-Masʿūdī."],
    de: ["Welches Werk Ibn Kaṯīrs ist eine Universalgeschichte von der Schöpfung bis zu seiner Zeit?", ["al-Bidāya wa-n-Nihāya", "al-Kāmil fī t-Tārīḫ", "Siyar Aʿlām an-Nubalāʾ", "Murūǧ aḏ-Ḏahab"], "Ibn Kaṯīr (701–774 n. H., gängige Angabe) schrieb al-Bidāya wa-n-Nihāya, eine Geschichte vom Beginn der Schöpfung bis zu den Ereignissen seiner Zeit. Al-Kāmil stammt von Ibn al-Aṯīr, Siyar von aḏ-Ḏahabī und Murūǧ von al-Masʿūdī."],
    ar: ["أي كتاب لابن كثير هو تاريخ عام من بدء الخلق إلى عصره؟", ["البداية والنهاية", "الكامل في التاريخ", "سير أعلام النبلاء", "مروج الذهب"], "ألّف ابن كثير (701–774هـ على المشهور) «البداية والنهاية» وهو تاريخ من بدء الخلق إلى أحداث زمانه، أما «الكامل» فلابن الأثير و«السير» للذهبي و«المروج» للمسعودي."] },

  { id: "hs-058", s: "history", g: 2, d: 3, t: ["historians", "works"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, introduction",
    en: ["Which work by al-Dhahabī gives biographies of scholars and notable figures, arranged by generations?", ["Siyar Aʿlām al-Nubalāʾ", "al-Bidāya wa-l-Nihāya", "Futūḥ al-Buldān", "Wafayāt al-Aʿyān"], "Al-Dhahabī (673–748 AH, commonly given) compiled Siyar Aʿlām al-Nubalāʾ and the larger Tārīkh al-Islām. Wafayāt al-Aʿyān is by Ibn Khallikān and Futūḥ al-Buldān by al-Balādhurī."],
    de: ["Welches Werk aḏ-Ḏahabīs enthält Biografien von Gelehrten und bedeutenden Personen, nach Generationen geordnet?", ["Siyar Aʿlām an-Nubalāʾ", "al-Bidāya wa-n-Nihāya", "Futūḥ al-Buldān", "Wafayāt al-Aʿyān"], "Aḏ-Ḏahabī (673–748 n. H., gängige Angabe) verfasste Siyar Aʿlām an-Nubalāʾ und das größere Tārīḫ al-Islām. Wafayāt al-Aʿyān stammt von Ibn Ḫallikān und Futūḥ al-Buldān von al-Balāḏurī."],
    ar: ["أي كتاب للذهبي يضم تراجم العلماء والأعيان على الطبقات؟", ["سير أعلام النبلاء", "البداية والنهاية", "فتوح البلدان", "وفيات الأعيان"], "ألّف الذهبي (673–748هـ على المشهور) «سير أعلام النبلاء» و«تاريخ الإسلام» الأكبر، أما «وفيات الأعيان» فلابن خلكان و«فتوح البلدان» للبلاذري."] },

  { id: "hs-059", s: "history", g: 2, d: 3, t: ["scholars-lives", "hadith"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, biography of al-Bukhārī",
    en: ["Where was Imam al-Bukhārī born, in 194 AH?", ["Bukhārā (in Transoxiana)", "Madīna", "Baghdad", "Damascus"], "Muḥammad ibn Ismāʿīl al-Bukhārī was born in Bukhārā, travelled for hadith across the Muslim world and died in 256 AH near Samarkand. His Ṣaḥīḥ is the most authoritative collection for most scholars."],
    de: ["Wo wurde Imam al-Buḫārī im Jahr 194 n. H. geboren?", ["In Buchara (in Transoxanien)", "In Medina", "In Bagdad", "In Damaskus"], "Muḥammad ibn Ismāʿīl al-Buḫārī wurde in Buchara geboren, reiste für Hadithe durch die muslimische Welt und starb 256 n. H. bei Samarkand. Sein Ṣaḥīḥ gilt den meisten Gelehrten als die maßgeblichste Sammlung."],
    ar: ["أين وُلد الإمام البخاري سنة 194هـ؟", ["في بخارى ببلاد ما وراء النهر", "في المدينة المنورة", "في بغداد", "في دمشق"], "وُلد محمد بن إسماعيل البخاري في بخارى وارتحل في طلب الحديث ومات سنة 256هـ قرب سمرقند، و«صحيحه» أصح الكتب عند أكثر العلماء."] },

  { id: "hs-060", s: "history", g: 2, d: 3, t: ["scholars-lives", "theology"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, biography of al-Ghazālī; Ibn ʿAsākir, Tabyīn Kadhib al-Muftarī",
    en: ["Which scholar of Ṭūs (450–505 AH, commonly given) taught at the Niẓāmiyya of Baghdad and wrote Iḥyāʾ ʿUlūm al-Dīn?", ["Abū Ḥāmid al-Ghazālī", "Fakhr al-Dīn al-Rāzī", "Ibn Rushd", "al-Nawawī"], "Al-Ghazālī became professor at the Niẓāmiyya in Baghdad, left his post in a spiritual crisis and later wrote Iḥyāʾ ʿUlūm al-Dīn. Al-Rāzī and Ibn Rushd lived later, and al-Nawawī lived in Syria in the 7th century AH."],
    de: ["Welcher Gelehrte aus Ṭūs (450–505 n. H., gängige Angabe) lehrte an der Niẓāmiyya in Bagdad und schrieb Iḥyāʾ ʿUlūm ad-Dīn?", ["Abū Ḥāmid al-Ġazālī", "Faḫr ad-Dīn ar-Rāzī", "Ibn Rušd", "an-Nawawī"], "Al-Ġazālī wurde Professor an der Niẓāmiyya in Bagdad, gab in einer geistigen Krise sein Amt auf und schrieb später Iḥyāʾ ʿUlūm ad-Dīn. Ar-Rāzī und Ibn Rušd lebten später, an-Nawawī im 7. Jh. n. H. in Syrien."],
    ar: ["أي عالم من طوس (450–505هـ على المشهور) درّس في النظامية ببغداد وألّف «إحياء علوم الدين»؟", ["أبو حامد الغزالي", "فخر الدين الرازي", "ابن رشد", "النووي"], "صار الغزالي أستاذًا في النظامية ببغداد ثم ترك منصبه في أزمة روحية وكتب بعدها «إحياء علوم الدين»، أما الرازي وابن رشد فجاءا بعده والنووي عاش في الشام في القرن السابع."] },

  { id: "hs-061", s: "history", g: 2, d: 3, t: ["sciences", "optics"], src: "Ibn Abī Uṣaybiʿa, ʿUyūn al-Anbāʾ; Ibn al-Haytham, Kitāb al-Manāẓir",
    en: ["Which scientist wrote Kitāb al-Manāẓir (Book of Optics), shaping the study of light and vision?", ["Ibn al-Haytham", "al-Bīrūnī", "al-Khwārizmī", "al-Zahrāwī"], "Ibn al-Haytham (born in Basra, worked in Cairo, d. c. 430 AH) argued that vision happens when light enters the eye and used experiments. Al-Zahrāwī was a surgeon of Andalus and al-Bīrūnī worked on astronomy and geography."],
    de: ["Welcher Wissenschaftler schrieb Kitāb al-Manāẓir (Buch der Optik), das die Erforschung von Licht und Sehen prägte?", ["Ibn al-Haiṯam", "al-Bīrūnī", "al-Ḫwārizmī", "az-Zahrāwī"], "Ibn al-Haiṯam (in Basra geboren, in Kairo tätig, gest. um 430 n. H.) legte dar, dass Sehen entsteht, wenn Licht ins Auge gelangt, und arbeitete mit Experimenten. Az-Zahrāwī war ein Chirurg Andalusiens, al-Bīrūnī arbeitete zu Astronomie und Geographie."],
    ar: ["أي عالم ألّف «كتاب المناظر» وأثّر في دراسة الضوء والبصر؟", ["ابن الهيثم", "البيروني", "الخوارزمي", "الزهراوي"], "وُلد ابن الهيثم في البصرة وعمل في القاهرة (توفي نحو 430هـ)، وقرر أن الإبصار يتم بدخول الضوء إلى العين واعتمد التجربة، أما الزهراوي فجرّاح أندلسي والبيروني اشتغل بالفلك والجغرافيا."] },

  { id: "hs-062", s: "history", g: 2, d: 3, t: ["resistance", "colonial-era"], src: "Standard histories of the Maghrib and Algeria (e.g. Danziger, Abd al-Qadir and the Algerians)",
    en: ["Which scholar and emir led the resistance against the French conquest of Algeria from 1832 until 1847?", ["al-Amīr ʿAbd al-Qādir al-Jazāʾirī", "ʿUmar al-Mukhtār", "Imām Shāmil", "Usman dan Fodio"], "ʿAbd al-Qādir, a Sufi scholar, built an organised state in western and central Algeria before surrendering in 1847. ʿUmar al-Mukhtār resisted Italy in Libya; Shāmil resisted Russia in the Caucasus."],
    de: ["Welcher Gelehrte und Emir führte von 1832 bis 1847 den Widerstand gegen die französische Eroberung Algeriens an?", ["al-Amīr ʿAbd al-Qādir al-Ǧazāʾirī", "ʿUmar al-Muḫtār", "Imām Šāmil", "Usman dan Fodio"], "ʿAbd al-Qādir, ein sufischer Gelehrter, baute einen organisierten Staat in West- und Zentralalgerien auf, bevor er 1847 kapitulierte. ʿUmar al-Muḫtār widerstand Italien in Libyen, Šāmil Russland im Kaukasus."],
    ar: ["أي عالم وأمير قاد المقاومة ضد الغزو الفرنسي للجزائر من 1832 إلى 1847؟", ["الأمير عبد القادر الجزائري", "عمر المختار", "الإمام شامل", "عثمان بن فودي"], "أقام الأمير عبد القادر، وهو عالم صوفي، دولة منظمة في غرب الجزائر ووسطها قبل أن يسلّم نفسه سنة 1847، أما عمر المختار فقاوم إيطاليا في ليبيا وشامل روسيا في القوقاز."] },

  // ---------- Stage 3 (secondary) ----------
  { id: "hs-063", s: "history", g: 3, d: 3, t: ["conquests", "battles"], src: "al-Balādhurī, Futūḥ al-Buldān, on the conquest of Syria; al-Ṭabarī, Tārīkh",
    en: ["What was the main consequence of the Muslim victory at the Yarmūk (15 AH)?", ["Byzantine rule in Syria effectively ended", "The Persian empire collapsed", "Egypt was lost to Byzantium", "Spain was opened to Muslim armies"], "At Yarmūk the Muslim army under Khālid ibn al-Walīd and Abū ʿUbayda defeated a much larger Byzantine force, after which the remaining Syrian cities fell. Persia was broken at al-Qādisiyya and Nihāvand."],
    de: ["Was war die wichtigste Folge des muslimischen Sieges am Yarmūk (15 n. H.)?", ["Die byzantinische Herrschaft in Syrien endete faktisch", "Das persische Reich brach zusammen", "Ägypten ging an Byzanz verloren", "Spanien wurde für muslimische Heere geöffnet"], "Am Yarmūk besiegte das muslimische Heer unter Ḫālid ibn al-Walīd und Abū ʿUbaida eine weit größere byzantinische Streitmacht, danach fielen die übrigen syrischen Städte. Persien wurde bei al-Qādisiyya und Nihāwand gebrochen."],
    ar: ["ما أهم نتيجة لانتصار المسلمين في اليرموك (15هـ)؟", ["انتهاء الحكم البيزنطي في الشام عمليًّا", "انهيار الدولة الفارسية", "خروج مصر من يد المسلمين", "فتح الأندلس"], "هزم جيش المسلمين بقيادة خالد وأبي عبيدة في اليرموك جيشًا بيزنطيًّا أكبر منه عددًا، فسقطت بقية مدن الشام، أما الفرس فكُسروا في القادسية ونهاوند."] },

  { id: "hs-064", s: "history", g: 3, d: 3, t: ["conquests", "battles"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, on Nihāvand",
    en: ["Which battle (commonly dated 21 AH) is called ‘the victory of victories’ (fatḥ al-futūḥ) because it ended Sasanian resistance in Persia?", ["Nihāvand", "Yarmūk", "Ṣiffīn", "al-Jamal"], "At Nihāvand in the Jibāl region, the Muslim army under al-Nuʿmān ibn Muqarrin defeated the last large Sasanian army. After that, the Persian plateau was gradually opened."],
    de: ["Welche Schlacht (gängig auf 21 n. H. datiert) heißt ‚der Sieg der Siege‘ (fatḥ al-futūḥ), weil sie den sasanidischen Widerstand in Persien beendete?", ["Nihāwand", "Yarmūk", "Ṣiffīn", "al-Ǧamal"], "Bei Nihāwand im Gebiet der Ǧibāl besiegte das muslimische Heer unter an-Nuʿmān ibn Muqarrin das letzte große sasanidische Heer. Danach wurde das persische Hochland schrittweise erschlossen."],
    ar: ["أي معركة (المشهور 21هـ) تسمى «فتح الفتوح» لأنها أنهت مقاومة الساسانيين في فارس؟", ["نهاوند", "اليرموك", "صفين", "الجمل"], "هزم المسلمون بقيادة النعمان بن مقرّن في نهاوند بإقليم الجبال آخر جيش ساساني كبير، ثم فُتحت هضبة فارس تدريجيًّا."] },

  { id: "hs-065", s: "history", g: 3, d: 3, t: ["umayyads", "battles"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 114 AH",
    en: ["Which battle in 114 AH (732 CE), in Gaul, ended the northward advance of the army of ʿAbd al-Raḥmān al-Ghāfiqī?", ["Balāṭ al-Shuhadāʾ (Tours/Poitiers)", "al-ʿIqāb (Las Navas de Tolosa)", "al-Zallāqa", "Wādī Lakka"], "ʿAbd al-Raḥmān al-Ghāfiqī, governor of al-Andalus, was killed in the battle called Balāṭ al-Shuhadāʾ against the Frankish forces of Charles Martel, and the Muslim force withdrew. Wādī Lakka (92 AH) was the battle that opened Spain."],
    de: ["Welche Schlacht des Jahres 114 n. H. (732 n. Chr.) in Gallien beendete den Vormarsch des Heeres von ʿAbd ar-Raḥmān al-Ġāfiqī nach Norden?", ["Balāṭ aš-Šuhadāʾ (Tours/Poitiers)", "al-ʿIqāb (Las Navas de Tolosa)", "az-Zallāqa", "Wādī Lakka"], "ʿAbd ar-Raḥmān al-Ġāfiqī, Statthalter von al-Andalus, fiel in der Schlacht von Balāṭ aš-Šuhadāʾ gegen die fränkischen Truppen Karl Martells, und das muslimische Heer zog sich zurück. Wādī Lakka (92 n. H.) war die Schlacht, die Spanien öffnete."],
    ar: ["أي معركة سنة 114هـ (732م) في بلاد الغال أوقفت تقدم جيش عبد الرحمن الغافقي شمالًا؟", ["بلاط الشهداء (تور/بواتييه)", "العقاب (لاس نافاس دي تولوسا)", "الزلاقة", "وادي لكة"], "قُتل عبد الرحمن الغافقي، والي الأندلس، في معركة بلاط الشهداء ضد الفرنجة بقيادة شارل مارتل فانسحب المسلمون، أما وادي لكة (92هـ) فهي التي فتحت الأندلس."] },

  { id: "hs-066", s: "history", g: 3, d: 3, t: ["abbasids", "revolution"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, events of 129–132 AH",
    en: ["Which leader organised the armies in Khurāsān that brought the Abbasid revolution to power in 129–132 AH?", ["Abū Muslim al-Khurāsānī", "Ibn al-Ashʿath", "Qutayba ibn Muslim", "Ziyād ibn Abīhi"], "Abū Muslim raised the black banners in Khurāsān in 129 AH, and his armies defeated the Umayyads at the Battle of the Zab (132 AH); Marwān II, the last Umayyad caliph, was killed soon after. Al-Manṣūr later had Abū Muslim killed."],
    de: ["Welcher Anführer organisierte die Heere in Ḫurāsān, die die abbasidische Revolution 129–132 n. H. an die Macht brachten?", ["Abū Muslim al-Ḫurāsānī", "Ibn al-Ašʿaṯ", "Qutaiba ibn Muslim", "Ziyād ibn Abīhi"], "Abū Muslim hisste 129 n. H. in Ḫurāsān die schwarzen Banner, und seine Heere besiegten die Umayyaden in der Schlacht am Zab (132 n. H.); Marwān II., der letzte umayyadische Kalif, wurde bald darauf getötet. Al-Manṣūr ließ Abū Muslim später töten."],
    ar: ["أي قائد نظّم الجيوش في خراسان التي أوصلت الدعوة العباسية إلى الحكم بين 129 و132هـ؟", ["أبو مسلم الخراساني", "ابن الأشعث", "قتيبة بن مسلم", "زياد بن أبيه"], "رفع أبو مسلم الرايات السود في خراسان سنة 129هـ وهزمت جيوشه الأمويين في معركة الزاب سنة 132هـ، وقُتل مروان الثاني آخر الخلفاء الأمويين بعدها، ثم قتل المنصور أبا مسلم."] },

  { id: "hs-067", s: "history", g: 3, d: 3, t: ["abbasids", "cities"], src: "al-Yaʿqūbī, Kitāb al-Buldān; al-Ṭabarī, Tārīkh",
    en: ["Which Abbasid caliph founded the city of Sāmarrāʾ as a new capital, around 221 AH?", ["al-Muʿtaṣim", "al-Maʾmūn", "Hārūn al-Rashīd", "al-Mahdī"], "Al-Muʿtaṣim moved the court from Baghdad to Sāmarrāʾ to keep his Turkish troops away from the population. The city remained the capital for about half a century."],
    de: ["Welcher abbasidische Kalif gründete um 221 n. H. die Stadt Sāmarrāʾ als neue Hauptstadt?", ["al-Muʿtaṣim", "al-Maʾmūn", "Hārūn ar-Rašīd", "al-Mahdī"], "Al-Muʿtaṣim verlegte den Hof von Bagdad nach Sāmarrāʾ, um seine türkischen Truppen von der Bevölkerung fernzuhalten. Die Stadt blieb rund ein halbes Jahrhundert Hauptstadt."],
    ar: ["أي خليفة عباسي أسس مدينة سامراء عاصمةً جديدة نحو سنة 221هـ؟", ["المعتصم", "المأمون", "هارون الرشيد", "المهدي"], "نقل المعتصم البلاط من بغداد إلى سامراء ليبعد جنده الأتراك عن أهل المدينة، وبقيت عاصمة نحو نصف قرن."] },

  { id: "hs-068", s: "history", g: 3, d: 4, t: ["abbasids", "battles"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 133 AH",
    en: ["The Battle of Talas in 133 AH (751 CE) is traditionally linked to the spread of what craft from China to the Muslim world?", ["Papermaking", "Silk weaving", "Gunpowder weapons", "The compass"], "At Talas in Central Asia an Abbasid-allied army met Tang forces. The tradition holds that Chinese prisoners taught papermaking in Samarkand, from where it spread to Baghdad; some historians treat the story with caution and note earlier paper contact."],
    de: ["Die Schlacht von Talas 133 n. H. (751 n. Chr.) wird traditionell mit der Verbreitung welchen Handwerks von China in die muslimische Welt verbunden?", ["Papierherstellung", "Seidenweberei", "Schießpulverwaffen", "Kompass"], "Bei Talas in Zentralasien traf ein mit den Abbasiden verbündetes Heer auf Tang-Truppen. Nach der Überlieferung lehrten chinesische Gefangene in Samarkand die Papierherstellung, von wo sie sich nach Bagdad verbreitete; manche Historiker sehen die Geschichte skeptisch und verweisen auf früheren Papierkontakt."],
    ar: ["تُربط معركة طلاس سنة 133هـ (751م) في الرواية التقليدية بانتقال أي صناعة من الصين إلى العالم الإسلامي؟", ["صناعة الورق", "نسج الحرير", "أسلحة البارود", "البوصلة"], "التقى في طلاس بآسيا الوسطى جيش حليف للعباسيين بجيش التانغ، وتقول الرواية التقليدية إن أسرى صينيين علّموا صناعة الورق في سمرقند ومنها إلى بغداد، وبعض المؤرخين يتحفظ على الرواية ويذكر اتصالًا أقدم بالورق."] },

  { id: "hs-069", s: "history", g: 3, d: 3, t: ["andalus", "umayyads"], src: "al-Maqqarī, Nafḥ al-Ṭīb, on ʿAbd al-Raḥmān al-Dākhil",
    en: ["Who founded the Umayyad emirate of al-Andalus after escaping the Abbasid massacre of his family?", ["ʿAbd al-Raḥmān I, known as al-Dākhil (the Entrant)", "ʿAbd al-Raḥmān III", "Ṭāriq ibn Ziyād", "al-Manṣūr ibn Abī ʿĀmir"], "ʿAbd al-Raḥmān ibn Muʿāwiya, a grandson of the caliph Hishām, fled Syria, reached Spain and established his rule in 138 AH (756 CE). ʿAbd al-Raḥmān III declared the caliphate nearly two centuries later."],
    de: ["Wer gründete das umayyadische Emirat von al-Andalus, nachdem er dem abbasidischen Massaker an seiner Familie entkommen war?", ["ʿAbd ar-Raḥmān I., genannt ad-Dāḫil (der Eingetretene)", "ʿAbd ar-Raḥmān III.", "Ṭāriq ibn Ziyād", "al-Manṣūr ibn Abī ʿĀmir"], "ʿAbd ar-Raḥmān ibn Muʿāwiya, ein Enkel des Kalifen Hišām, floh aus Syrien, erreichte Spanien und errichtete 138 n. H. (756 n. Chr.) seine Herrschaft. ʿAbd ar-Raḥmān III. rief fast zwei Jahrhunderte später das Kalifat aus."],
    ar: ["من مؤسس الإمارة الأموية في الأندلس بعد أن نجا من مذبحة العباسيين لأسرته؟", ["عبد الرحمن الأول الداخل", "عبد الرحمن الثالث", "طارق بن زياد", "المنصور بن أبي عامر"], "فرّ عبد الرحمن بن معاوية، حفيد الخليفة هشام، من الشام ووصل الأندلس وأقام حكمه سنة 138هـ (756م)، وأعلن عبد الرحمن الثالث الخلافة بعده بنحو قرنين."] },

  { id: "hs-070", s: "history", g: 3, d: 3, t: ["andalus", "caliphate"], src: "al-Maqqarī, Nafḥ al-Ṭīb, on ʿAbd al-Raḥmān al-Nāṣir",
    en: ["Which ruler declared the caliphate of Córdoba in 316 AH (929 CE), taking the title al-Nāṣir li-Dīn Allāh?", ["ʿAbd al-Raḥmān III", "ʿAbd al-Raḥmān I", "Hishām II", "Yūsuf ibn Tāshfīn"], "ʿAbd al-Raḥmān III, facing the rise of the Fatimid caliphate in North Africa, declared himself caliph. His reign is regarded as the peak of Umayyad Andalus; the caliphate collapsed in 422 AH (1031)."],
    de: ["Welcher Herrscher rief 316 n. H. (929 n. Chr.) das Kalifat von Córdoba aus und nahm den Titel an-Nāṣir li-Dīn Allāh an?", ["ʿAbd ar-Raḥmān III.", "ʿAbd ar-Raḥmān I.", "Hišām II.", "Yūsuf ibn Tāšufīn"], "ʿAbd ar-Raḥmān III. erklärte sich angesichts des Aufstiegs des fatimidischen Kalifats in Nordafrika zum Kalifen. Seine Regierung gilt als Höhepunkt des umayyadischen Andalus; das Kalifat zerfiel 422 n. H. (1031)."],
    ar: ["أي حاكم أعلن خلافة قرطبة سنة 316هـ (929م) متلقبًا بالناصر لدين الله؟", ["عبد الرحمن الثالث", "عبد الرحمن الأول", "هشام الثاني", "يوسف بن تاشفين"], "أعلن عبد الرحمن الثالث نفسه خليفة بعد صعود الخلافة الفاطمية في شمال إفريقيا، ويُعدّ عهده ذروة الأندلس الأموية، وانهارت الخلافة سنة 422هـ (1031م)."] },

  { id: "hs-071", s: "history", g: 3, d: 3, t: ["andalus", "cities"], src: "al-Maqqarī, Nafḥ al-Ṭīb, on Madīnat al-Zahrāʾ",
    en: ["What was Madīnat al-Zahrāʾ, built by ʿAbd al-Raḥmān III?", ["A palace-city near Córdoba that served as the seat of government", "A fortress on the Strait of Gibraltar", "A university in Granada", "A port on the Atlantic coast"], "Madīnat al-Zahrāʾ was a royal palace-city outside Córdoba, begun around 325 AH (936 CE). It was ruined in the civil war that ended the caliphate and was rediscovered by archaeologists."],
    de: ["Was war Madīnat az-Zahrāʾ, von ʿAbd ar-Raḥmān III. erbaut?", ["Eine Palaststadt bei Córdoba, die als Regierungssitz diente", "Eine Festung an der Straße von Gibraltar", "Eine Universität in Granada", "Ein Hafen an der Atlantikküste"], "Madīnat az-Zahrāʾ war eine königliche Palaststadt vor Córdoba, um 325 n. H. (936 n. Chr.) begonnen. Sie wurde im Bürgerkrieg, der das Kalifat beendete, zerstört und von Archäologen wiederentdeckt."],
    ar: ["ما مدينة الزهراء التي بناها عبد الرحمن الثالث؟", ["مدينة قصور قرب قرطبة كانت مقر الحكم", "حصن على مضيق جبل طارق", "جامعة في غرناطة", "ميناء على المحيط الأطلسي"], "كانت الزهراء مدينة ملكية خارج قرطبة بدأ بناؤها نحو سنة 325هـ (936م)، وخُربت في الفتنة التي أنهت الخلافة ثم كشفها علماء الآثار."] },

  { id: "hs-072", s: "history", g: 3, d: 3, t: ["andalus", "almoravids"], src: "Ibn Abī Zarʿ, Rawḍ al-Qirṭās; al-Maqqarī, Nafḥ al-Ṭīb",
    en: ["Which victory in 479 AH (1086 CE) did the Almoravid ruler Yūsuf ibn Tāshfīn win after being called to help by the Andalusian princes?", ["al-Zallāqa (Sagrajas) against Alfonso VI", "Alarcos against Alfonso VIII", "ʿAyn Jālūt against the Mongols", "Ḥaṭṭīn against the Crusaders"], "After the fall of Toledo in 478 AH, the taifa kings, led by al-Muʿtamid of Seville, asked the Almoravids for help. Yūsuf crossed with his army and defeated the Castilian king at al-Zallāqa, delaying the Christian advance."],
    de: ["Welchen Sieg errang der Almoravidenherrscher Yūsuf ibn Tāšufīn 479 n. H. (1086 n. Chr.), nachdem die andalusischen Fürsten ihn zu Hilfe gerufen hatten?", ["Az-Zallāqa (Sagrajas) gegen Alfons VI.", "Alarcos gegen Alfons VIII.", "ʿAin Ǧālūt gegen die Mongolen", "Ḥaṭṭīn gegen die Kreuzfahrer"], "Nach dem Fall Toledos 478 n. H. baten die Taifa-Könige, angeführt von al-Muʿtamid von Sevilla, die Almoraviden um Hilfe. Yūsuf setzte mit seinem Heer über und besiegte den kastilischen König bei az-Zallāqa, womit der christliche Vormarsch verzögert wurde."],
    ar: ["أي نصر حققه المرابطي يوسف بن تاشفين سنة 479هـ (1086م) بعد استنجاد أمراء الأندلس به؟", ["الزلاقة على ألفونسو السادس", "الأرك على ألفونسو الثامن", "عين جالوت على المغول", "حطين على الصليبيين"], "بعد سقوط طليطلة سنة 478هـ استنجد ملوك الطوائف بقيادة المعتمد بن عباد بالمرابطين، فعبر يوسف وهزم ملك قشتالة في الزلاقة وأخّر زحف النصارى."] },

  { id: "hs-073", s: "history", g: 3, d: 3, t: ["andalus", "almohads"], src: "Ibn Abī Zarʿ, Rawḍ al-Qirṭās; Ibn Khaldūn, Kitāb al-ʿIbar",
    en: ["Who was the spiritual founder of the Almohad (al-Muwaḥḥidūn) movement in the Maghrib?", ["Muḥammad ibn Tūmart", "Yūsuf ibn Tāshfīn", "ʿAbd al-Mu'min ibn ʿAlī", "Idrīs ibn ʿAbd Allāh"], "Ibn Tūmart, a Berber scholar from the Atlas, started the movement against the Almoravids with a reform call based on tawḥīd. His successor ʿAbd al-Muʾmin built the Almohad state."],
    de: ["Wer war der geistige Gründer der Almohadenbewegung (al-Muwaḥḥidūn) im Maghreb?", ["Muḥammad ibn Tūmart", "Yūsuf ibn Tāšufīn", "ʿAbd al-Muʾmin ibn ʿAlī", "Idrīs ibn ʿAbd Allāh"], "Ibn Tūmart, ein berberischer Gelehrter aus dem Atlas, begann die Bewegung gegen die Almoraviden mit einem auf dem Tawḥīd gegründeten Reformruf. Sein Nachfolger ʿAbd al-Muʾmin baute den almohadischen Staat auf."],
    ar: ["من الداعية المؤسس لحركة الموحدين في المغرب؟", ["محمد بن تومرت", "يوسف بن تاشفين", "عبد المؤمن بن علي", "إدريس بن عبد الله"], "بدأ ابن تومرت، وهو عالم أمازيغي من الأطلس، الحركة ضد المرابطين بدعوة إصلاحية على التوحيد، وبنى خليفته عبد المؤمن الدولة الموحدية."] },

  { id: "hs-074", s: "history", g: 3, d: 3, t: ["fatimids", "dynasties"], src: "al-Maqrīzī, Ittiʿāẓ al-Ḥunafāʾ bi-Akhbār al-Aʾimma al-Fāṭimiyyīn al-Khulafāʾ",
    en: ["Where was the Fatimid caliphate first established in 297 AH (909 CE)?", ["Ifrīqiya (modern Tunisia)", "Egypt", "Syria", "Yemen"], "The Fatimid caliphate, an Ismāʿīlī Shīʿī dynasty, was proclaimed by ʿUbayd Allāh al-Mahdī in Ifrīqiya; it moved to Egypt in 358 AH when al-Muʿizz entered the new city of Cairo."],
    de: ["Wo wurde das fatimidische Kalifat 297 n. H. (909 n. Chr.) zuerst errichtet?", ["In Ifrīqiya (heutiges Tunesien)", "In Ägypten", "In Syrien", "Im Jemen"], "Das fatimidische Kalifat, eine ismailitisch-schiitische Dynastie, wurde von ʿUbaid Allāh al-Mahdī in Ifrīqiya ausgerufen; es verlegte seinen Sitz 358 n. H. nach Ägypten, als al-Muʿizz die neue Stadt Kairo betrat."],
    ar: ["أين قامت الدولة الفاطمية أولًا سنة 297هـ (909م)؟", ["في إفريقية (تونس اليوم)", "في مصر", "في الشام", "في اليمن"], "أُعلنت الخلافة الفاطمية، وهي دولة إسماعيلية شيعية، على يد عبيد الله المهدي في إفريقية، وانتقلت إلى مصر سنة 358هـ حين دخل المعز القاهرة الجديدة."] },

  { id: "hs-075", s: "history", g: 3, d: 3, t: ["ayyubids", "fatimids"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 567 AH",
    en: ["Who ended the Fatimid caliphate in Egypt in 567 AH (1171 CE) and restored Sunni allegiance to the Abbasids?", ["Ṣalāḥ al-Dīn al-Ayyūbī", "Nūr al-Dīn Zangī", "Baybars", "Jawhar al-Ṣiqillī"], "After the death of the last Fatimid caliph al-ʿĀḍid, Ṣalāḥ al-Dīn had the sermon said in the name of the Abbasid caliph and founded the Ayyubid dynasty. Jawhar was the Fatimid founder of Cairo."],
    de: ["Wer beendete 567 n. H. (1171 n. Chr.) das fatimidische Kalifat in Ägypten und stellte die sunnitische Gefolgschaft zu den Abbasiden wieder her?", ["Ṣalāḥ ad-Dīn al-Aiyūbī", "Nūr ad-Dīn Zangī", "Baibars", "Ǧauhar aṣ-Ṣiqillī"], "Nach dem Tod des letzten fatimidischen Kalifen al-ʿĀḍid ließ Ṣalāḥ ad-Dīn die Predigt im Namen des abbasidischen Kalifen halten und gründete die Aiyubidendynastie. Ǧauhar war der fatimidische Gründer Kairos."],
    ar: ["من الذي أنهى الخلافة الفاطمية في مصر سنة 567هـ (1171م) وأعاد الدعاء للعباسيين؟", ["صلاح الدين الأيوبي", "نور الدين زنكي", "بيبرس", "جوهر الصقلي"], "بعد وفاة آخر الخلفاء الفاطميين العاضد أقام صلاح الدين الخطبة للخليفة العباسي وأسس الدولة الأيوبية، أما جوهر فمؤسس القاهرة للفاطميين."] },

  { id: "hs-076", s: "history", g: 3, d: 3, t: ["seljuks", "abbasids"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 447 AH",
    en: ["What happened in 447 AH (1055 CE) when the Seljuk leader Ṭughril Beg entered Baghdad?", ["He ended Buyid domination and became the protector of the Abbasid caliph", "He abolished the Abbasid caliphate", "He handed Baghdad to the Fatimids", "He was defeated by the caliph's army"], "The Seljuks, Sunni Turks, replaced the Shīʿī Buyid amirs as the dominant power in Baghdad while keeping the Abbasid caliph as religious head. The caliph gave Ṭughril the title of sultan."],
    de: ["Was geschah 447 n. H. (1055 n. Chr.), als der Seldschukenführer Ṭuġril Beg in Bagdad einzog?", ["Er beendete die Vorherrschaft der Buyiden und wurde Schutzherr des abbasidischen Kalifen", "Er schaffte das abbasidische Kalifat ab", "Er übergab Bagdad den Fatimiden", "Er wurde vom Heer des Kalifen geschlagen"], "Die Seldschuken, sunnitische Türken, lösten die schiitischen Buyidenemire als Vormacht in Bagdad ab und behielten den abbasidischen Kalifen als religiöses Oberhaupt. Der Kalif verlieh Ṭuġril den Titel Sultan."],
    ar: ["ماذا حدث سنة 447هـ (1055م) حين دخل السلجوقي طغرل بك بغداد؟", ["أنهى نفوذ البويهيين وصار حامي الخليفة العباسي", "ألغى الخلافة العباسية", "سلّم بغداد للفاطميين", "هزمه جيش الخليفة"], "حلّ السلاجقة، وهم أتراك سنة، محل الأمراء البويهيين الشيعة قوةً مهيمنة في بغداد وأبقوا الخليفة العباسي رأسًا دينيًّا، ولقّبه الخليفة بالسلطان."] },

  { id: "hs-077", s: "history", g: 3, d: 3, t: ["seljuks", "battles"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 463 AH",
    en: ["Which Seljuk sultan defeated and captured the Byzantine emperor Romanos Diogenes at Malāzgird in 463 AH (1071 CE)?", ["Alp Arslān", "Malikshāh", "Ṭughril Beg", "Sanjar"], "Alp Arslān's victory at Malāzgird (Manzikert) opened Anatolia to Turkish settlement. His son Malikshāh succeeded him and his vizier Niẓām al-Mulk shaped the state."],
    de: ["Welcher Seldschukensultan besiegte und fing den byzantinischen Kaiser Romanos Diogenes 463 n. H. (1071 n. Chr.) bei Malāzgird?", ["Alp Arslān", "Malikšāh", "Ṭuġril Beg", "Sanǧar"], "Alp Arslāns Sieg bei Malāzgird (Manzikert) öffnete Anatolien für türkische Besiedlung. Sein Sohn Malikšāh folgte ihm, und sein Wesir Niẓām al-Mulk prägte den Staat."],
    ar: ["أي سلطان سلجوقي هزم الإمبراطور البيزنطي رومانوس ديوجين وأسره في ملاذكرد سنة 463هـ (1071م)؟", ["ألب أرسلان", "ملكشاه", "طغرل بك", "سنجر"], "فتح انتصار ألب أرسلان في ملاذكرد الأناضول أمام الاستيطان التركي، وخلفه ابنه ملكشاه وكان لوزيره نظام الملك أثر كبير في الدولة."] },

  { id: "hs-078", s: "history", g: 3, d: 3, t: ["seljuks", "education"], src: "Ibn Khallikān, Wafayāt al-Aʿyān, biography of Niẓām al-Mulk",
    en: ["What was the main purpose of the Niẓāmiyya madrasas founded by the vizier Niẓām al-Mulk, the first being in Baghdad (459 AH)?", ["State-supported colleges to train jurists and teachers, in the Shāfiʿī school", "Military academies for the Seljuk army", "Hospitals for the poor", "Libraries for translating Greek works"], "Niẓām al-Mulk endowed a network of colleges in the Seljuk lands that taught Shāfiʿī law and Ashʿarī theology, with salaried professors. Al-Ghazālī and al-Juwaynī taught in them."],
    de: ["Was war der Hauptzweck der Niẓāmiyya-Madrasen, die der Wesir Niẓām al-Mulk gründete, die erste in Bagdad (459 n. H.)?", ["Staatlich geförderte Kollegs zur Ausbildung von Juristen und Lehrern in der schafiitischen Schule", "Militärakademien für das Seldschukenheer", "Krankenhäuser für die Armen", "Bibliotheken zum Übersetzen griechischer Werke"], "Niẓām al-Mulk stiftete ein Netz von Kollegs in den seldschukischen Ländern, in denen schafiitisches Recht und aschʿaritische Theologie mit besoldeten Professoren gelehrt wurden. Al-Ġazālī und al-Ǧuwainī lehrten dort."],
    ar: ["ما الغرض الأبرز للمدارس النظامية التي أنشأها الوزير نظام الملك وأولاها ببغداد (459هـ)؟", ["كليات تدعمها الدولة لتخريج الفقهاء والمدرسين على المذهب الشافعي", "أكاديميات عسكرية للجيش السلجوقي", "مستشفيات للفقراء", "مكتبات لترجمة الكتب اليونانية"], "أوقف نظام الملك شبكة من المدارس في بلاد السلاجقة تُدرّس الفقه الشافعي والعقيدة الأشعرية بأساتذة لهم رواتب، ودرّس فيها الغزالي والجويني."] },

  { id: "hs-079", s: "history", g: 3, d: 3, t: ["crusades", "jerusalem"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 492 AH",
    en: ["In which year (AH/CE) did the First Crusade capture Jerusalem?", ["492 AH (1099 CE)", "583 AH (1187 CE)", "658 AH (1260 CE)", "690 AH (1291 CE)"], "The Crusaders took Jerusalem in Shaʿbān 492 AH after a siege, and a large part of the population was killed. The other years are the recapture under Ṣalāḥ al-Dīn, ʿAyn Jālūt and the fall of Acre."],
    de: ["In welchem Jahr (n. H./n. Chr.) eroberte der Erste Kreuzzug Jerusalem?", ["492 n. H. (1099 n. Chr.)", "583 n. H. (1187 n. Chr.)", "658 n. H. (1260 n. Chr.)", "690 n. H. (1291 n. Chr.)"], "Die Kreuzfahrer nahmen Jerusalem im Šaʿbān 492 n. H. nach einer Belagerung ein, und ein großer Teil der Bevölkerung wurde getötet. Die anderen Jahre sind die Rückeroberung unter Ṣalāḥ ad-Dīn, ʿAin Ǧālūt und der Fall Akkons."],
    ar: ["في أي سنة (هجرية/ميلادية) احتل الحملة الصليبية الأولى القدس؟", ["492هـ (1099م)", "583هـ (1187م)", "658هـ (1260م)", "690هـ (1291م)"], "دخل الصليبيون القدس في شعبان 492هـ بعد حصار وقُتل كثير من أهلها، أما السنوات الأخرى فاسترداد صلاح الدين وعين جالوت وسقوط عكا."] },

  { id: "hs-080", s: "history", g: 3, d: 3, t: ["crusades", "zengids"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 539 AH",
    en: ["Which Muslim ruler's capture of Edessa (al-Ruhā) in 539 AH (1144 CE) marked the start of the Muslim counter-offensive against the Crusader states?", ["ʿImād al-Dīn Zangī", "Nūr al-Dīn Maḥmūd", "Ṣalāḥ al-Dīn", "Alp Arslān"], "ʿImād al-Dīn Zangī of Mosul took Edessa, the first Crusader state to fall, which led to the Second Crusade. His son Nūr al-Dīn continued the effort and brought Egypt into the same camp."],
    de: ["Der Eroberung von Edessa (ar-Ruhā) 539 n. H. (1144 n. Chr.) durch welchen muslimischen Herrscher gilt als Beginn der muslimischen Gegenoffensive gegen die Kreuzfahrerstaaten?", ["ʿImād ad-Dīn Zangī", "Nūr ad-Dīn Maḥmūd", "Ṣalāḥ ad-Dīn", "Alp Arslān"], "ʿImād ad-Dīn Zangī von Mosul nahm Edessa, den ersten Kreuzfahrerstaat, der fiel, was den Zweiten Kreuzzug auslöste. Sein Sohn Nūr ad-Dīn setzte die Anstrengung fort und band Ägypten in dasselbe Lager ein."],
    ar: ["فتح أي حاكم مسلم الرها سنة 539هـ (1144م) وكان بداية الهجوم المضاد على الإمارات الصليبية؟", ["عماد الدين زنكي", "نور الدين محمود", "صلاح الدين", "ألب أرسلان"], "استولى عماد الدين زنكي صاحب الموصل على الرها وهي أول إمارة صليبية تسقط، فتبعتها الحملة الصليبية الثانية، ثم واصل ابنه نور الدين الجهد وضمّ مصر إلى الصف نفسه."] },

  { id: "hs-081", s: "history", g: 3, d: 3, t: ["crusades", "mamluks"], src: "al-Maqrīzī, al-Sulūk li-Maʿrifat Duwal al-Mulūk, events of 690 AH",
    en: ["Which Mamluk sultan captured Acre, the last major Crusader stronghold, in 690 AH (1291 CE)?", ["al-Ashraf Khalīl ibn Qalāwūn", "Baybars", "Qutuz", "al-Nāṣir Muḥammad"], "After a siege, al-Ashraf Khalīl took Acre in 1291, and the remaining Crusader coastal towns were abandoned soon after. His father Qalāwūn had prepared the campaign."],
    de: ["Welcher Mamlukensultan eroberte Akkon, die letzte bedeutende Kreuzfahrerfestung, 690 n. H. (1291 n. Chr.)?", ["al-Ašraf Ḫalīl ibn Qalāwūn", "Baibars", "Quṭuz", "an-Nāṣir Muḥammad"], "Nach einer Belagerung nahm al-Ašraf Ḫalīl 1291 Akkon ein, und die übrigen Küstenstädte der Kreuzfahrer wurden bald danach aufgegeben. Sein Vater Qalāwūn hatte den Feldzug vorbereitet."],
    ar: ["أي سلطان مملوكي فتح عكا آخر معاقل الصليبيين الكبرى سنة 690هـ (1291م)؟", ["الأشرف خليل بن قلاوون", "بيبرس", "قطز", "الناصر محمد"], "فتح الأشرف خليل عكا سنة 1291 بعد حصار، وتخلّى الصليبيون بعدها عن بقية مدنهم الساحلية، وكان أبوه قلاوون قد مهّد للحملة."] },

  { id: "hs-082", s: "history", g: 3, d: 3, t: ["mamluks", "ayyubids"], src: "al-Maqrīzī, al-Sulūk li-Maʿrifat Duwal al-Mulūk, events of 648 AH",
    en: ["Who became ruler of Egypt in 648 AH (1250 CE) after the death of the Ayyubid sultan al-Ṣāliḥ, and is counted as the founder of the Mamluk line?", ["Shajar al-Durr", "Qutuz", "Aybak", "Baybars"], "Shajar al-Durr, widow of al-Ṣāliḥ Ayyūb, concealed his death during the Crusade of Louis IX, then ruled and married the Mamluk commander Aybak. She is a rare example of a woman who held sovereign power in Egypt."],
    de: ["Wer wurde 648 n. H. (1250 n. Chr.) nach dem Tod des aiyubidischen Sultans aṣ-Ṣāliḥ Herrscher Ägyptens und gilt als Begründerin der Mamlukenlinie?", ["Šaǧar ad-Durr", "Quṭuz", "Aibak", "Baibars"], "Šaǧar ad-Durr, Witwe von aṣ-Ṣāliḥ Aiyūb, verbarg seinen Tod während des Kreuzzugs Ludwigs IX., regierte dann und heiratete den Mamlukenführer Aibak. Sie ist ein seltenes Beispiel einer Frau mit souveräner Macht in Ägypten."],
    ar: ["من تولت حكم مصر سنة 648هـ (1250م) بعد وفاة السلطان الصالح أيوب وتُعدّ مؤسسة الخط المملوكي؟", ["شجر الدر", "قطز", "أيبك", "بيبرس"], "أخفت شجر الدر أرملة الصالح أيوب نبأ وفاته أثناء حملة لويس التاسع ثم حكمت وتزوجت القائد المملوكي أيبك، وهي مثال نادر لامرأة تولت سلطة في مصر."] },

  { id: "hs-083", s: "history", g: 3, d: 3, t: ["ottomans", "origins"], src: "Standard histories of the Ottoman Empire (e.g. Inalcik, The Ottoman Empire: The Classical Age)",
    en: ["Which leader is regarded as the founder of the Ottoman dynasty, around the end of the 7th century AH (c. 1299 CE)?", ["ʿUthmān (Osman) I", "Orhan", "Murād I", "Bāyezīd I"], "The dynasty takes its name from Osman, a frontier leader in north-western Anatolia whose state grew from a small principality. His son Orhan took Bursa and expanded further."],
    de: ["Welcher Anführer gilt als Begründer der osmanischen Dynastie, um das Ende des 7. Jh. n. H. (ca. 1299 n. Chr.)?", ["ʿUṯmān (Osman) I.", "Orhan", "Murād I.", "Bāyezīd I."], "Die Dynastie trägt den Namen von Osman, einem Grenzfürsten im Nordwesten Anatoliens, dessen Staat aus einem kleinen Fürstentum wuchs. Sein Sohn Orhan nahm Bursa ein und dehnte die Herrschaft weiter aus."],
    ar: ["أي زعيم يُعدّ مؤسس الأسرة العثمانية في أواخر القرن السابع الهجري (نحو 1299م)؟", ["عثمان الأول", "أورخان", "مراد الأول", "بايزيد الأول"], "تحمل الأسرة اسم عثمان وهو زعيم ثغري في شمال غرب الأناضول نمت إمارته الصغيرة إلى دولة، وفتح ابنه أورخان بورصة وتوسع بعده."] },

  { id: "hs-084", s: "history", g: 3, d: 3, t: ["ottomans", "battles"], src: "Standard histories of the Ottoman Empire (e.g. Imber, The Ottoman Empire 1300–1650)",
    en: ["Which victory of Sulaymān the Magnificent in 1526 CE (932 AH) brought most of Hungary under Ottoman control?", ["Mohács", "Chaldiran", "Lepanto", "Ankara"], "At Mohács the Ottoman army destroyed the Hungarian army and killed King Louis II. Chaldiran (1514) was against the Safavids, Lepanto (1571) was an Ottoman defeat at sea and Ankara (1402) was Timur's victory."],
    de: ["Welcher Sieg Sulaimans des Prächtigen 1526 n. Chr. (932 n. H.) brachte den größten Teil Ungarns unter osmanische Kontrolle?", ["Mohács", "Çaldıran", "Lepanto", "Ankara"], "Bei Mohács vernichtete das osmanische Heer das ungarische Heer und tötete König Ludwig II. Çaldıran (1514) war gegen die Safawiden, Lepanto (1571) eine osmanische Seeniederlage und Ankara (1402) Timurs Sieg."],
    ar: ["أي انتصار لسليمان القانوني سنة 1526م (932هـ) أخضع معظم المجر للعثمانيين؟", ["موهاكس", "جالديران", "ليبانتو", "أنقرة"], "دمّر الجيش العثماني في موهاكس الجيش المجري وقتل الملك لويس الثاني، أما جالديران (1514) فضد الصفويين وليبانتو (1571) هزيمة بحرية عثمانية وأنقرة (1402) انتصار تيمور."] },

  { id: "hs-085", s: "history", g: 3, d: 3, t: ["mughals", "india"], src: "Standard histories of the Mughal empire (e.g. Richards, The Mughal Empire)",
    en: ["Which ruler founded the Mughal empire in India by winning the First Battle of Pānīpat in 1526 CE?", ["Bābur", "Akbar", "Humāyūn", "Aurangzeb"], "Zahīr al-Dīn Bābur, a Timurid prince from Central Asia, defeated the Sultan of Delhi, Ibrāhīm Lodī, at Pānīpat. His grandson Akbar consolidated and enlarged the empire."],
    de: ["Welcher Herrscher gründete das Mogulreich in Indien durch den Sieg in der ersten Schlacht von Pānīpat 1526 n. Chr.?", ["Bābur", "Akbar", "Humāyūn", "Aurangzeb"], "Zahīr ad-Dīn Bābur, ein timuridischer Prinz aus Zentralasien, besiegte bei Pānīpat den Sultan von Delhi, Ibrāhīm Lodī. Sein Enkel Akbar festigte und vergrößerte das Reich."],
    ar: ["أي حاكم أسس الإمبراطورية المغولية في الهند بانتصاره في معركة بانيبت الأولى سنة 1526م؟", ["بابر", "أكبر", "همايون", "أورنكزيب"], "هزم ظهير الدين بابر، وهو أمير تيموري من آسيا الوسطى، سلطان دلهي إبراهيم اللودي في بانيبت، ووطّد حفيده أكبر الدولة ووسّعها."] },

  { id: "hs-086", s: "history", g: 3, d: 3, t: ["africa", "songhai"], src: "al-Saʿdī, Taʾrīkh al-Sūdān; Maḥmūd Kaʿti, Taʾrīkh al-Fattāsh",
    en: ["Which ruler of the Songhai empire made the pilgrimage to Makka in 1496–97 CE and was given the title of caliph of the Sudan?", ["Askia Muḥammad (Muḥammad Ture)", "Sunni ʿAlī", "Mansa Mūsā", "Samori Touré"], "Askia Muḥammad took power from the Sunni dynasty, made a famous pilgrimage and received a title from the Abbasid caliph in Cairo. Under him Timbuktu became a leading centre of Islamic scholarship."],
    de: ["Welcher Herrscher des Songhai-Reiches unternahm 1496–97 n. Chr. die Pilgerfahrt nach Mekka und erhielt den Titel eines Kalifen des Sudan?", ["Askia Muḥammad (Muḥammad Ture)", "Sunni ʿAlī", "Mansa Mūsā", "Samori Touré"], "Askia Muḥammad übernahm die Macht von der Sunni-Dynastie, unternahm eine berühmte Pilgerfahrt und erhielt von dem abbasidischen Kalifen in Kairo einen Titel. Unter ihm wurde Timbuktu zu einem führenden Zentrum islamischer Gelehrsamkeit."],
    ar: ["أي حاكم لإمبراطورية سنغاي حجّ سنة 1496–97م ونال لقب خليفة بلاد السودان؟", ["أسكيا محمد (محمد توري)", "سني علي", "منسا موسى", "ساموري توري"], "انتزع أسكيا محمد الحكم من أسرة سني وحجّ حجّة مشهورة ونال لقبًا من الخليفة العباسي في القاهرة، وصارت تمبكتو في عهده مركزًا علميًّا إسلاميًّا كبيرًا."] },

  { id: "hs-087", s: "history", g: 3, d: 3, t: ["africa", "reform-movements"], src: "Standard histories of West Africa (e.g. Last, The Sokoto Caliphate)",
    en: ["Which scholar led the reform movement that founded the Sokoto Caliphate in northern Nigeria in the early 19th century CE?", ["Usman dan Fodio", "ʿUmar Tall", "Sunni ʿAlī", "Muḥammad Aḥmad al-Mahdī"], "Usman dan Fodio, a Fulani scholar of the Qādirī order and the Mālikī school, called for a return to the sharīʿa from 1804; his son Muḥammad Bello and brother ʿAbd Allāh consolidated the caliphate."],
    de: ["Welcher Gelehrte führte die Reformbewegung an, die im frühen 19. Jh. n. Chr. das Kalifat von Sokoto im Norden Nigerias gründete?", ["Usman dan Fodio", "ʿUmar Tall", "Sunni ʿAlī", "Muḥammad Aḥmad al-Mahdī"], "Usman dan Fodio, ein Fulbe-Gelehrter des Qādirīya-Ordens und der malikitischen Schule, rief ab 1804 zur Rückkehr zur Scharia auf; sein Sohn Muḥammad Bello und sein Bruder ʿAbd Allāh festigten das Kalifat."],
    ar: ["أي عالم قاد حركة الإصلاح التي أسست خلافة صكتو في شمال نيجيريا في مطلع القرن التاسع عشر؟", ["عثمان بن فودي", "عمر تال", "سني علي", "محمد أحمد المهدي"], "دعا عثمان بن فودي، وهو عالم فلاني قادري مالكي، إلى العودة إلى الشريعة منذ 1804، ووطّد الخلافة ابنه محمد بلو وأخوه عبد الله."] },

  { id: "hs-088", s: "history", g: 3, d: 3, t: ["scholars-lives", "ibn-taymiyya"], src: "al-Dhahabī, Dhayl Tārīkh al-Islām; Ibn ʿAbd al-Hādī, al-ʿUqūd al-Durriyya",
    en: ["Where was Ibn Taymiyya born in 661 AH, and where did he die in 728 AH?", ["Born in Ḥarrān; died in the citadel of Damascus", "Born in Baghdad; died in Cairo", "Born in Cordoba; died in Fez", "Born in Makka; died in Madīna"], "Ibn Taymiyya's family moved from Ḥarrān to Damascus because of the Mongol threat. He was imprisoned several times, and died in 728 AH in the Damascus citadel."],
    de: ["Wo wurde Ibn Taimiyya 661 n. H. geboren und wo starb er 728 n. H.?", ["Geboren in Ḥarrān; gestorben in der Zitadelle von Damaskus", "Geboren in Bagdad; gestorben in Kairo", "Geboren in Córdoba; gestorben in Fès", "Geboren in Mekka; gestorben in Medina"], "Ibn Taimiyyas Familie zog wegen der mongolischen Bedrohung von Ḥarrān nach Damaskus. Er wurde mehrmals inhaftiert und starb 728 n. H. in der Zitadelle von Damaskus."],
    ar: ["أين وُلد ابن تيمية سنة 661هـ وأين توفي سنة 728هـ؟", ["وُلد في حرّان وتوفي في قلعة دمشق", "وُلد في بغداد وتوفي في القاهرة", "وُلد في قرطبة وتوفي في فاس", "وُلد في مكة وتوفي في المدينة"], "انتقلت أسرة ابن تيمية من حرّان إلى دمشق بسبب الخطر المغولي، وسُجن مرات، وتوفي سنة 728هـ في قلعة دمشق."] },

  { id: "hs-089", s: "history", g: 3, d: 3, t: ["scholars-lives", "shafii"], src: "al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, biography of al-Nawawī",
    en: ["Which Shāfiʿī scholar of Syria (631–676 AH, commonly given), from the village of Nawā, wrote Riyāḍ al-Ṣāliḥīn and al-Arbaʿūn?", ["Yaḥyā ibn Sharaf al-Nawawī", "Ibn Ḥajar al-ʿAsqalānī", "al-Suyūṭī", "Ibn Qudāma"], "Al-Nawawī lived most of his life in Damascus and, though he died at about forty-five, wrote Sharḥ Ṣaḥīḥ Muslim, al-Majmūʿ and Riyāḍ al-Ṣāliḥīn. Ibn Qudāma was a Ḥanbalī scholar of the preceding century."],
    de: ["Welcher schafiitische Gelehrte Syriens (631–676 n. H., gängige Angabe) aus dem Dorf Nawā schrieb Riyāḍ aṣ-Ṣāliḥīn und al-Arbaʿūn?", ["Yaḥyā ibn Šaraf an-Nawawī", "Ibn Ḥaǧar al-ʿAsqalānī", "as-Suyūṭī", "Ibn Qudāma"], "An-Nawawī lebte die meiste Zeit in Damaskus und schrieb, obwohl er mit etwa fünfundvierzig starb, Šarḥ Ṣaḥīḥ Muslim, al-Maǧmūʿ und Riyāḍ aṣ-Ṣāliḥīn. Ibn Qudāma war ein hanbalitischer Gelehrter des vorangehenden Jahrhunderts."],
    ar: ["أي عالم شافعي من الشام (631–676هـ على المشهور) من قرية نوى ألّف «رياض الصالحين» و«الأربعين»؟", ["يحيى بن شرف النووي", "ابن حجر العسقلاني", "السيوطي", "ابن قدامة"], "عاش النووي معظم عمره في دمشق وألّف مع وفاته في نحو الخامسة والأربعين «شرح صحيح مسلم» و«المجموع» و«رياض الصالحين»، أما ابن قدامة فحنبلي من القرن السابق."] },

  { id: "hs-090", s: "history", g: 3, d: 3, t: ["scholars-lives", "andalus"], src: "Ibn Abī Uṣaybiʿa, ʿUyūn al-Anbāʾ; al-Dhahabī, Siyar Aʿlām al-Nubalāʾ, biography of Ibn Rushd",
    en: ["Which Andalusian scholar of Cordoba (520–595 AH, commonly given) wrote Bidāyat al-Mujtahid on comparative fiqh and commentaries on Aristotle?", ["Ibn Rushd (Averroes)", "Ibn Ḥazm", "al-Shāṭibī", "Ibn al-ʿArabī al-Maʿāfirī"], "Ibn Rushd, qāḍī of Seville and Córdoba, wrote the Bidāya on the disagreement of the jurists and philosophical commentaries. Ibn Ḥazm lived a century earlier and al-Shāṭibī in Granada in the 8th century AH."],
    de: ["Welcher andalusische Gelehrte aus Córdoba (520–595 n. H., gängige Angabe) schrieb Bidāyat al-Muǧtahid über vergleichendes Fiqh und Kommentare zu Aristoteles?", ["Ibn Rušd (Averroes)", "Ibn Ḥazm", "aš-Šāṭibī", "Ibn al-ʿArabī al-Maʿāfirī"], "Ibn Rušd, Qāḍī von Sevilla und Córdoba, schrieb die Bidāya über die Meinungsverschiedenheit der Juristen sowie philosophische Kommentare. Ibn Ḥazm lebte ein Jahrhundert früher und aš-Šāṭibī im 8. Jh. n. H. in Granada."],
    ar: ["أي عالم أندلسي من قرطبة (520–595هـ على المشهور) ألّف «بداية المجتهد» في الفقه المقارن وشروحًا لأرسطو؟", ["ابن رشد", "ابن حزم", "الشاطبي", "ابن العربي المعافري"], "كتب ابن رشد قاضي إشبيلية وقرطبة «البداية» في اختلاف الفقهاء وشروحًا فلسفية، أما ابن حزم فسبقه بقرن والشاطبي عاش في غرناطة في القرن الثامن."] },

  { id: "hs-091", s: "history", g: 3, d: 3, t: ["scholars-lives", "hadith"], src: "Ibn Ḥajar, al-Durar al-Kāmina; al-Sakhāwī, al-Ḍawʾ al-Lāmiʿ",
    en: ["Which hadith scholar of Cairo (773–852 AH, commonly given) wrote Fatḥ al-Bārī, the most widely used commentary on Ṣaḥīḥ al-Bukhārī?", ["Ibn Ḥajar al-ʿAsqalānī", "al-Nawawī", "al-Dhahabī", "al-Suyūṭī"], "Ibn Ḥajar served as chief judge in Cairo and spent around twenty-five years on Fatḥ al-Bārī. Al-Nawawī wrote on Muslim; al-Dhahabī and al-Suyūṭī wrote on many other fields."],
    de: ["Welcher Hadithgelehrte aus Kairo (773–852 n. H., gängige Angabe) schrieb Fatḥ al-Bārī, den meistgenutzten Kommentar zu Ṣaḥīḥ al-Buḫārī?", ["Ibn Ḥaǧar al-ʿAsqalānī", "an-Nawawī", "aḏ-Ḏahabī", "as-Suyūṭī"], "Ibn Ḥaǧar war Oberrichter in Kairo und arbeitete rund fünfundzwanzig Jahre an Fatḥ al-Bārī. An-Nawawī schrieb zu Muslim; aḏ-Ḏahabī und as-Suyūṭī schrieben zu vielen anderen Gebieten."],
    ar: ["أي عالم حديث من القاهرة (773–852هـ على المشهور) ألّف «فتح الباري» أشهر شروح صحيح البخاري؟", ["ابن حجر العسقلاني", "النووي", "الذهبي", "السيوطي"], "تولى ابن حجر قضاء القضاة في القاهرة وأمضى نحو خمس وعشرين سنة في «فتح الباري»، أما النووي فشرح مسلمًا والذهبي والسيوطي كتبا في فنون أخرى."] },

  { id: "hs-092", s: "history", g: 3, d: 3, t: ["resistance", "colonial-era"], src: "Standard histories of Libya (e.g. Ahmida, The Making of Modern Libya)",
    en: ["Which Libyan teacher of the Qurʾān and resistance leader, executed by the Italians in 1931, is known as the ‘Lion of the Desert’?", ["ʿUmar al-Mukhtār", "Idrīs al-Sanūsī", "al-Amīr ʿAbd al-Qādir", "Muḥammad Aḥmad al-Mahdī"], "ʿUmar al-Mukhtār led the Sanūsī-linked resistance in Cyrenaica against Italian colonisation for about twenty years, and was captured and hanged in September 1931 at about seventy."],
    de: ["Welcher libysche Koranlehrer und Widerstandsführer, 1931 von den Italienern hingerichtet, ist als ‚Löwe der Wüste‘ bekannt?", ["ʿUmar al-Muḫtār", "Idrīs as-Sanūsī", "al-Amīr ʿAbd al-Qādir", "Muḥammad Aḥmad al-Mahdī"], "ʿUmar al-Muḫtār führte etwa zwanzig Jahre lang den sanusitisch geprägten Widerstand in der Kyrenaika gegen die italienische Kolonisierung und wurde im September 1931 mit etwa siebzig Jahren gefangen genommen und gehängt."],
    ar: ["أي معلم قرآن ومقاوم ليبي أعدمه الإيطاليون سنة 1931 ويلقب بأسد الصحراء؟", ["عمر المختار", "إدريس السنوسي", "الأمير عبد القادر", "محمد أحمد المهدي"], "قاد عمر المختار المقاومة المرتبطة بالسنوسية في برقة ضد الاستعمار الإيطالي نحو عشرين عامًا، ثم أُسر وأُعدم شنقًا في سبتمبر 1931 وهو في نحو السبعين."] },

  // ---------- Stage 4 (university) ----------
  { id: "hs-093", s: "history", g: 4, d: 4, t: ["political-theory", "caliphate", "rashidun"], tr: ["sunni"], src: "al-Māwardī, al-Aḥkām al-Sulṭāniyya, ch. 1 on the contract of the imamate; al-Bāqillānī, al-Tamhīd",
    en: ["According to the view of the majority of Sunni jurists and theologians (e.g. al-Bāqillānī, al-Māwardī), how was the caliphate of Abū Bakr established?", ["By the choice and pledge of the community (ikhtiyār and bayʿa), without an explicit designation by the Prophet", "By an explicit written designation by the Prophet", "By inheritance within the Prophet's family", "By a decree of the Anṣār alone"], "The majority held that the imamate is contracted by the choice of the people of authority (ahl al-ḥall wa-l-ʿaqd) and the pledge of the community, as happened for Abū Bakr. Some, such as al-Ḥasan al-Baṣrī and a group of hadith scholars, thought the Prophet had hinted at Abū Bakr (implicit designation), and other groups held that ʿAlī had been designated."],
    de: ["Wie wurde nach der Ansicht der Mehrheit der sunnitischen Juristen und Theologen (z. B. al-Bāqillānī, al-Māwardī) das Kalifat Abū Bakrs begründet?", ["Durch Wahl und Huldigung der Gemeinschaft (iḫtiyār und bayʿa), ohne ausdrückliche Bestimmung durch den Propheten", "Durch eine ausdrückliche schriftliche Bestimmung des Propheten", "Durch Vererbung innerhalb der Familie des Propheten", "Durch einen Beschluss allein der Anṣār"], "Die Mehrheit vertrat, das Imamat werde durch die Wahl der Entscheidungsträger (ahl al-ḥall wa-l-ʿaqd) und die Huldigung der Gemeinschaft geschlossen, wie es bei Abū Bakr geschah. Manche, etwa al-Ḥasan al-Baṣrī und eine Gruppe von Hadithgelehrten, meinten, der Prophet habe auf Abū Bakr hingedeutet (stillschweigende Bestimmung), und andere Gruppen hielten ʿAlī für bestimmt."],
    ar: ["على رأي جمهور فقهاء أهل السنة ومتكلميهم (كالباقلاني والماوردي)، كيف انعقدت خلافة أبي بكر؟", ["باختيار الأمة وبيعتها دون نص صريح من النبي ﷺ", "بنص مكتوب صريح من النبي ﷺ", "بالوراثة في أسرة النبي ﷺ", "بقرار الأنصار وحدهم"], "ذهب الجمهور إلى أن الإمامة تنعقد باختيار أهل الحل والعقد وبيعة الأمة كما جرى لأبي بكر. وقال الحسن البصري وطائفة من أهل الحديث بإشارة النبي ﷺ إليه إشارة خفية، وقال غيرهم بالنص على علي."] },

  { id: "hs-094", s: "history", g: 4, d: 4, t: ["political-theory", "caliphate"], tr: ["sunni"], src: "al-Māwardī, al-Aḥkām al-Sulṭāniyya, ch. 1; al-Juwaynī, Ghiyāth al-Umam",
    en: ["Which two ways of concluding the imamate does al-Māwardī accept in al-Aḥkām al-Sulṭāniyya?", ["Election by the people of authority, and designation by the previous imam", "Inheritance and conquest only", "Lot and consultation of the Anṣār", "Succession by seniority and military acclaim"], "Al-Māwardī describes the imamate as concluded either by election of the ahl al-ḥall wa-l-ʿaqd (as with Abū Bakr) or by designation of a successor by the imam (as with ʿUmar). Later jurists discussed the validity of the rule by conquest as a matter of necessity."],
    de: ["Welche zwei Wege zum Abschluss des Imamats erkennt al-Māwardī in al-Aḥkām as-Sulṭāniyya an?", ["Wahl durch die Entscheidungsträger und Bestimmung durch den vorherigen Imam", "Nur Vererbung und Eroberung", "Los und Beratung der Anṣār", "Nachfolge nach Alter und Akklamation durch das Heer"], "Al-Māwardī beschreibt das Imamat als entweder durch Wahl der ahl al-ḥall wa-l-ʿaqd (wie bei Abū Bakr) oder durch Bestimmung eines Nachfolgers durch den Imam (wie bei ʿUmar) geschlossen. Spätere Juristen erörterten die Gültigkeit der Herrschaft durch Eroberung als Notfall."],
    ar: ["ما طريقا انعقاد الإمامة اللذان يقرهما الماوردي في «الأحكام السلطانية»؟", ["اختيار أهل الحل والعقد وعهد الإمام السابق", "الوراثة والغلبة فقط", "القرعة ومشورة الأنصار", "التقدم بالسن وتأييد الجيش"], "يذكر الماوردي أن الإمامة تنعقد إما باختيار أهل الحل والعقد (كأبي بكر) وإما بعهد الإمام إلى من يخلفه (كعمر)، وناقش الفقهاء بعده صحة ولاية المتغلب للضرورة."] },

  { id: "hs-095", s: "history", g: 4, d: 4, t: ["umayyads", "reforms"], src: "al-Balādhurī, Futūḥ al-Buldān, on the dīwān and coinage; al-Maqrīzī, Shudhūr al-ʿUqūd",
    en: ["Which reform is attributed to the caliph ʿAbd al-Malik ibn Marwān in the years commonly dated 77–81 AH?", ["Introducing coins with Arabic-Islamic inscriptions and making Arabic the language of the state registers", "Moving the capital to Baghdad", "Abolishing the jizya", "Founding the first madrasa"], "ʿAbd al-Malik replaced Byzantine and Persian coin designs with a purely Arabic-Islamic coinage and had the dīwāns of Syria and Iraq kept in Arabic rather than Greek and Persian. Baghdad was founded by the Abbasids."],
    de: ["Welche Reform wird dem Kalifen ʿAbd al-Malik ibn Marwān in den Jahren zugeschrieben, die üblicherweise mit 77–81 n. H. angegeben werden?", ["Einführung von Münzen mit arabisch-islamischen Inschriften und Arabisch als Sprache der Staatsregister", "Verlegung der Hauptstadt nach Bagdad", "Abschaffung der Ǧizya", "Gründung der ersten Madrasa"], "ʿAbd al-Malik ersetzte byzantinische und persische Münzbilder durch eine rein arabisch-islamische Prägung und ließ die Dīwāne Syriens und des Irak auf Arabisch statt Griechisch und Persisch führen. Bagdad wurde von den Abbasiden gegründet."],
    ar: ["أي إصلاح يُنسب للخليفة عبد الملك بن مروان في السنوات المشهورة 77–81هـ؟", ["ضرب نقود عربية إسلامية وتعريب الدواوين", "نقل العاصمة إلى بغداد", "إلغاء الجزية", "تأسيس أول مدرسة"], "استبدل عبد الملك بنقوش الدنانير البيزنطية والدراهم الفارسية سكة عربية إسلامية خالصة، وعرّب دواوين الشام والعراق بعد أن كانت بالرومية والفارسية. أما بغداد فأسسها العباسيون."] },

  { id: "hs-096", s: "history", g: 4, d: 4, t: ["umayyads", "second-fitna"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, events of 64–73 AH",
    en: ["Who claimed the caliphate from Makka after the death of Yazīd I, ruling the Hijāz until he was killed by al-Ḥajjāj's forces in 73 AH?", ["ʿAbd Allāh ibn al-Zubayr", "ʿAbd Allāh ibn ʿAbbās", "Marwān ibn al-Ḥakam", "al-Mukhtār al-Thaqafī"], "Ibn al-Zubayr, son of the Companion al-Zubayr and grandson of Abū Bakr through Asmāʾ, was acknowledged in the Hijāz and elsewhere. The Umayyads under ʿAbd al-Malik beat him; the Kaʿba was damaged in the siege and later rebuilt."],
    de: ["Wer beanspruchte nach dem Tod Yazīds I. das Kalifat von Mekka aus und herrschte über den Hidschas, bis er 73 n. H. von al-Ḥaǧǧāǧs Truppen getötet wurde?", ["ʿAbd Allāh ibn az-Zubair", "ʿAbd Allāh ibn ʿAbbās", "Marwān ibn al-Ḥakam", "al-Muḫtār aṯ-Ṯaqafī"], "Ibn az-Zubair, Sohn des Gefährten az-Zubair und über Asmāʾ Enkel Abū Bakrs, wurde im Hidschas und anderswo anerkannt. Die Umayyaden unter ʿAbd al-Malik besiegten ihn; die Kaaba wurde bei der Belagerung beschädigt und später wiederaufgebaut."],
    ar: ["من الذي ادّعى الخلافة من مكة بعد وفاة يزيد الأول وحكم الحجاز حتى قتلته قوات الحجاج سنة 73هـ؟", ["عبد الله بن الزبير", "عبد الله بن عباس", "مروان بن الحكم", "المختار الثقفي"], "بويع ابن الزبير، ابن الصحابي الزبير وحفيد أبي بكر لأمه أسماء، في الحجاز وغيره، ثم هزمه الأمويون بقيادة عبد الملك، وتضررت الكعبة في الحصار وأُعيد بناؤها."] },

  { id: "hs-097", s: "history", g: 4, d: 4, t: ["umayyads", "marj-rahit"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk, events of 64 AH",
    en: ["After which battle in 64 AH did Marwān ibn al-Ḥakam consolidate Umayyad rule in Syria, shifting the caliphate to the Marwānid line?", ["Marj Rāhiṭ", "Ṣiffīn", "al-Ḥarra", "Dayr al-Jamājim"], "At Marj Rāhiṭ near Damascus, Marwān defeated the supporters of Ibn al-Zubayr, mainly the Qaysī tribes, with the support of the Yamanī tribes. After him the caliphate stayed in his descendants. Al-Ḥarra (63 AH) was the Umayyad victory over Madīna."],
    de: ["Nach welcher Schlacht des Jahres 64 n. H. festigte Marwān ibn al-Ḥakam die umayyadische Herrschaft in Syrien und verlagerte das Kalifat auf die Marwāniden-Linie?", ["Marǧ Rāhiṭ", "Ṣiffīn", "al-Ḥarra", "Dair al-Ǧamāǧim"], "Bei Marǧ Rāhiṭ nahe Damaskus besiegte Marwān die Anhänger Ibn az-Zubairs, vor allem die qaisitischen Stämme, mit Unterstützung der jemenitischen Stämme. Danach blieb das Kalifat in seinen Nachkommen. Al-Ḥarra (63 n. H.) war der umayyadische Sieg über Medina."],
    ar: ["بعد أي معركة سنة 64هـ ثبّت مروان بن الحكم الحكم الأموي في الشام وانتقلت الخلافة إلى فرع آل مروان؟", ["مرج راهط", "صفين", "الحرة", "دير الجماجم"], "هزم مروان في مرج راهط قرب دمشق أنصار ابن الزبير وهم قبائل قيس بدعم من قبائل اليمن، وبقيت الخلافة بعده في ذريته، أما الحرة (63هـ) ففيها انتصر الأمويون على أهل المدينة."] },

  { id: "hs-098", s: "history", g: 4, d: 4, t: ["umayyads", "conquests"], src: "al-Balādhurī, Futūḥ al-Buldān, on Transoxiana and Sind",
    en: ["Under al-Walīd I (86–96 AH), which commanders led the conquests of Transoxiana and of Sind respectively?", ["Qutayba ibn Muslim and Muḥammad ibn al-Qāsim", "Ṭāriq ibn Ziyād and Mūsā ibn Nuṣayr", "Khālid ibn al-Walīd and ʿAmr ibn al-ʿĀṣ", "ʿUqba ibn Nāfiʿ and Ḥassān ibn al-Nuʿmān"], "Qutayba ibn Muslim, governor of Khurāsān, extended Muslim rule across the Oxus to Bukhārā, Samarkand and beyond, while the young Muḥammad ibn al-Qāsim al-Thaqafī conquered Sind around 93 AH. Ṭāriq and Mūsā conquered al-Andalus under the same caliph."],
    de: ["Welche Befehlshaber führten unter al-Walīd I. (86–96 n. H.) die Eroberung von Transoxanien bzw. von Sind an?", ["Qutaiba ibn Muslim und Muḥammad ibn al-Qāsim", "Ṭāriq ibn Ziyād und Mūsā ibn Nuṣair", "Ḫālid ibn al-Walīd und ʿAmr ibn al-ʿĀṣ", "ʿUqba ibn Nāfiʿ und Ḥassān ibn an-Nuʿmān"], "Qutaiba ibn Muslim, Statthalter von Ḫurāsān, dehnte die muslimische Herrschaft über den Oxus bis Buchara, Samarkand und darüber hinaus aus, während der junge Muḥammad ibn al-Qāsim aṯ-Ṯaqafī um 93 n. H. Sind eroberte. Ṭāriq und Mūsā eroberten unter demselben Kalifen al-Andalus."],
    ar: ["في عهد الوليد الأول (86–96هـ)، من القائدان اللذان فتحا ما وراء النهر والسند على التوالي؟", ["قتيبة بن مسلم ومحمد بن القاسم", "طارق بن زياد وموسى بن نصير", "خالد بن الوليد وعمرو بن العاص", "عقبة بن نافع وحسان بن النعمان"], "وسّع قتيبة بن مسلم والي خراسان الحكم الإسلامي عبر جيحون إلى بخارى وسمرقند وما وراءهما، وفتح الشاب محمد بن القاسم الثقفي السند نحو سنة 93هـ، أما طارق وموسى ففتحا الأندلس في العهد نفسه."] },

  { id: "hs-099", s: "history", g: 4, d: 4, t: ["maghrib", "idrisids"], src: "Ibn Abī Zarʿ, Rawḍ al-Qirṭās, on the Idrīsids",
    en: ["Who founded the first independent Muslim dynasty in Morocco, the Idrīsids, around 172 AH?", ["Idrīs ibn ʿAbd Allāh, a descendant of al-Ḥasan ibn ʿAlī", "Yūsuf ibn Tāshfīn", "Ibn Tūmart", "ʿUqba ibn Nāfiʿ"], "Idrīs I fled the Abbasid suppression of a revolt in the Hijāz, reached Walīlī in the Maghrib and was recognised by Berber tribes. His son Idrīs II founded Fez as the capital."],
    de: ["Wer gründete um 172 n. H. die erste unabhängige muslimische Dynastie in Marokko, die Idrisiden?", ["Idrīs ibn ʿAbd Allāh, ein Nachkomme von al-Ḥasan ibn ʿAlī", "Yūsuf ibn Tāšufīn", "Ibn Tūmart", "ʿUqba ibn Nāfiʿ"], "Idrīs I. floh vor der abbasidischen Niederschlagung eines Aufstands im Hidschas, erreichte Walīlī im Maghreb und wurde von Berberstämmen anerkannt. Sein Sohn Idrīs II. gründete Fès als Hauptstadt."],
    ar: ["من أسس أول دولة إسلامية مستقلة في المغرب الأقصى، الأدارسة، نحو سنة 172هـ؟", ["إدريس بن عبد الله من ذرية الحسن بن علي", "يوسف بن تاشفين", "ابن تومرت", "عقبة بن نافع"], "فرّ إدريس الأول بعد قمع العباسيين لثورة في الحجاز ووصل وليلي في المغرب فبايعته قبائل البربر، وأسس ابنه إدريس الثاني مدينة فاس عاصمة."] },

  { id: "hs-100", s: "history", g: 4, d: 4, t: ["mediterranean", "aghlabids"], src: "al-Balādhurī, Futūḥ al-Buldān; Ibn al-Athīr, al-Kāmil, events of 212 AH",
    en: ["Which North African dynasty began the conquest of Sicily in 212 AH (827 CE) under the judge Asad ibn al-Furāt?", ["The Aghlabids of Ifrīqiya", "The Fatimids of Egypt", "The Almohads of Marrakesh", "The Ayyubids of Syria"], "The Aghlabids, nominally under the Abbasids, ruled from Qayrawān and launched the long conquest of Sicily, completed in the following decades. The Fatimids later took over their territory."],
    de: ["Welche nordafrikanische Dynastie begann 212 n. H. (827 n. Chr.) unter dem Richter Asad ibn al-Furāt die Eroberung Siziliens?", ["Die Aghlabiden von Ifrīqiya", "Die Fatimiden Ägyptens", "Die Almohaden von Marrakesch", "Die Aiyubiden Syriens"], "Die Aghlabiden, nominell den Abbasiden unterstellt, regierten von Qairawān aus und begannen die lange Eroberung Siziliens, die in den folgenden Jahrzehnten abgeschlossen wurde. Die Fatimiden übernahmen später ihr Gebiet."],
    ar: ["أي دولة في شمال إفريقيا بدأت فتح صقلية سنة 212هـ (827م) بقيادة القاضي أسد بن الفرات؟", ["الأغالبة في إفريقية", "الفاطميون في مصر", "الموحدون في مراكش", "الأيوبيون في الشام"], "حكم الأغالبة، وهم تابعون للعباسيين اسميًّا، من القيروان وبدؤوا فتح صقلية الطويل الذي اكتمل في العقود التالية، ثم ورث الفاطميون بلادهم."] },

  { id: "hs-101", s: "history", g: 4, d: 4, t: ["abbasids", "buyids"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 334 AH",
    en: ["Which dynasty took control of Baghdad in 334 AH (945 CE), reducing the Abbasid caliph to a nominal head?", ["The Buyids (Banū Buwayh)", "The Seljuks", "The Fatimids", "The Mamluks"], "Aḥmad ibn Buwayh (Muʿizz al-Dawla) entered Baghdad and the caliph became subordinate to the Buyid amirs, who held real power until the Seljuk entry in 447 AH."],
    de: ["Welche Dynastie übernahm 334 n. H. (945 n. Chr.) die Kontrolle über Bagdad und machte den abbasidischen Kalifen zu einem nominellen Oberhaupt?", ["Die Buyiden (Banū Buwaih)", "Die Seldschuken", "Die Fatimiden", "Die Mamluken"], "Aḥmad ibn Buwaih (Muʿizz ad-Daula) zog in Bagdad ein, und der Kalif wurde den buyidischen Emiren untergeordnet, die bis zum Einzug der Seldschuken 447 n. H. die reale Macht hielten."],
    ar: ["أي أسرة سيطرت على بغداد سنة 334هـ (945م) وجعلت الخليفة العباسي رئيسًا اسميًّا؟", ["البويهيون (بنو بويه)", "السلاجقة", "الفاطميون", "المماليك"], "دخل أحمد بن بويه (معز الدولة) بغداد وصار الخليفة تابعًا للأمراء البويهيين الذين احتفظوا بالسلطة الفعلية حتى دخول السلاجقة سنة 447هـ."] },

  { id: "hs-102", s: "history", g: 4, d: 5, t: ["abbasids", "qarmatians"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 317 and 339 AH",
    en: ["What did the Qarmaṭians, a breakaway Ismāʿīlī group of eastern Arabia, do at Makka in 317 AH (930 CE)?", ["They attacked the pilgrims and removed the Black Stone, which was returned about twenty years later", "They besieged and conquered Cairo", "They destroyed the Prophet's Mosque in Madīna", "They founded the city of Baghdad"], "The Qarmaṭians under Abū Ṭāhir al-Jannābī raided Makka during the Ḥajj and carried off the Black Stone to al-Aḥsāʾ. It was restored in 339 AH (951 CE)."],
    de: ["Was taten die Qarmaten, eine abgespaltene ismailitische Gruppe Ostarabiens, 317 n. H. (930 n. Chr.) in Mekka?", ["Sie griffen die Pilger an und entfernten den Schwarzen Stein, der etwa zwanzig Jahre später zurückgegeben wurde", "Sie belagerten und eroberten Kairo", "Sie zerstörten die Prophetenmoschee in Medina", "Sie gründeten die Stadt Bagdad"], "Die Qarmaten unter Abū Ṭāhir al-Ǧannābī überfielen Mekka während des Ḥaǧǧ und führten den Schwarzen Stein nach al-Aḥsāʾ fort. Er wurde 339 n. H. (951 n. Chr.) zurückgegeben."],
    ar: ["ماذا فعل القرامطة، وهم فرقة إسماعيلية خرجت في شرق الجزيرة العربية، في مكة سنة 317هـ (930م)؟", ["هاجموا الحجاج وانتزعوا الحجر الأسود ثم أُعيد بعد نحو عشرين سنة", "حاصروا القاهرة وفتحوها", "هدموا المسجد النبوي بالمدينة", "أسسوا مدينة بغداد"], "أغار القرامطة بقيادة أبي طاهر الجنابي على مكة في موسم الحج وحملوا الحجر الأسود إلى الأحساء، وأُعيد سنة 339هـ (951م)."] },

  { id: "hs-103", s: "history", g: 4, d: 4, t: ["crusades", "treaties"], src: "Ibn Shaddād, al-Nawādir al-Sulṭāniyya wa-l-Maḥāsin al-Yūsufiyya",
    en: ["Which treaty of 588 AH (1192 CE) between Ṣalāḥ al-Dīn and Richard I ended the Third Crusade?", ["The treaty of Ramla", "The treaty of Ḥudaybiya", "The treaty of Karlowitz", "The treaty of Nymphaeum"], "After Acre fell to the Crusaders in 587 AH, a truce was concluded at Ramla: Jerusalem remained in Muslim hands, with Christian pilgrims allowed to visit, while the Crusaders kept a coastal strip. Ibn Shaddād, Ṣalāḥ al-Dīn's secretary, narrates it."],
    de: ["Welcher Vertrag des Jahres 588 n. H. (1192 n. Chr.) zwischen Ṣalāḥ ad-Dīn und Richard I. beendete den Dritten Kreuzzug?", ["Der Vertrag von Ramla", "Der Vertrag von Ḥudaibiya", "Der Vertrag von Karlowitz", "Der Vertrag von Nymphaion"], "Nach dem Fall Akkons an die Kreuzfahrer 587 n. H. wurde in Ramla ein Waffenstillstand geschlossen: Jerusalem blieb in muslimischer Hand, christliche Pilger durften es besuchen, die Kreuzfahrer behielten einen Küstenstreifen. Ibn Šaddād, Sekretär Ṣalāḥ ad-Dīns, berichtet davon."],
    ar: ["أي معاهدة سنة 588هـ (1192م) بين صلاح الدين وريتشارد الأول أنهت الحملة الصليبية الثالثة؟", ["صلح الرملة", "صلح الحديبية", "معاهدة كارلوفيتز", "معاهدة نيمفايون"], "بعد سقوط عكا في أيدي الصليبيين سنة 587هـ عُقدت هدنة الرملة: بقيت القدس بيد المسلمين مع السماح لحجاج النصارى بالزيارة، واحتفظ الصليبيون بشريط ساحلي، ويرويها ابن شداد كاتب صلاح الدين."] },

  { id: "hs-104", s: "history", g: 4, d: 4, t: ["mamluks", "abbasids"], src: "al-Maqrīzī, al-Sulūk li-Maʿrifat Duwal al-Mulūk, events of 659 AH",
    en: ["Why did Sultan Baybars install an Abbasid prince as caliph in Cairo in 659 AH (1261 CE)?", ["To give the Mamluk sultanate religious legitimacy after the destruction of the caliphate in Baghdad", "Because the Abbasids had conquered Egypt", "Because the Fatimids requested it", "To start a campaign against Spain"], "After the Mongol fall of Baghdad, Baybars welcomed a surviving Abbasid, al-Mustanṣir, and had him recognised as caliph. The line stayed in Cairo as a ceremonial caliphate until the Ottoman conquest of 1517."],
    de: ["Warum setzte Sultan Baibars 659 n. H. (1261 n. Chr.) einen abbasidischen Prinzen als Kalifen in Kairo ein?", ["Um dem Mamlukensultanat religiöse Legitimität nach der Zerstörung des Kalifats in Bagdad zu verschaffen", "Weil die Abbasiden Ägypten erobert hatten", "Weil die Fatimiden es verlangten", "Um einen Feldzug gegen Spanien zu beginnen"], "Nach dem mongolischen Fall Bagdads nahm Baibars einen überlebenden Abbasiden, al-Mustanṣir, auf und ließ ihn als Kalifen anerkennen. Die Linie blieb als zeremonielles Kalifat in Kairo bis zur osmanischen Eroberung 1517."],
    ar: ["لماذا نصّب السلطان بيبرس أميرًا عباسيًّا خليفةً في القاهرة سنة 659هـ (1261م)؟", ["ليمنح السلطنة المملوكية شرعية دينية بعد زوال الخلافة في بغداد", "لأن العباسيين فتحوا مصر", "لأن الفاطميين طلبوا ذلك", "لبدء حملة على الأندلس"], "بعد سقوط بغداد على يد المغول استقبل بيبرس أحد الناجين من العباسيين وهو المستنصر وبايعه خليفة، وبقيت هذه السلالة في القاهرة خلافةً رمزية حتى الفتح العثماني سنة 1517."] },

  { id: "hs-105", s: "history", g: 4, d: 4, t: ["andalus", "reconquista"], src: "Ibn Abī Zarʿ, Rawḍ al-Qirṭās; Ibn ʿIdhārī, al-Bayān al-Mughrib",
    en: ["Which defeat of the Almohad caliph al-Nāṣir in 609 AH (1212 CE) marked the turning point of the Reconquista?", ["al-ʿIqāb (Las Navas de Tolosa)", "Alarcos", "al-Zallāqa", "Balāṭ al-Shuhadāʾ"], "At al-ʿIqāb in the Sierra Morena the combined Christian kings defeated the Almohad army. Alarcos (591 AH) was a Muslim victory, al-Zallāqa (479 AH) as well. Cordoba fell in 1236 and Seville in 1248, and Granada stayed as the last Muslim kingdom."],
    de: ["Welche Niederlage des Almohadenkalifen an-Nāṣir 609 n. H. (1212 n. Chr.) markierte den Wendepunkt der Reconquista?", ["Al-ʿIqāb (Las Navas de Tolosa)", "Alarcos", "Az-Zallāqa", "Balāṭ aš-Šuhadāʾ"], "Bei al-ʿIqāb in der Sierra Morena besiegten die vereinigten christlichen Könige das Almohadenheer. Alarcos (591 n. H.) war ein muslimischer Sieg, ebenso az-Zallāqa (479 n. H.). Córdoba fiel 1236 und Sevilla 1248; Granada blieb als letztes muslimisches Königreich."],
    ar: ["أي هزيمة للخليفة الموحدي الناصر سنة 609هـ (1212م) كانت نقطة التحول في حركة الاسترداد؟", ["العقاب (لاس نافاس دي تولوسا)", "الأرك", "الزلاقة", "بلاط الشهداء"], "هزم ملوك النصارى المتحالفون الجيش الموحدي في العقاب بجبال سييرا مورينا، أما الأرك (591هـ) والزلاقة (479هـ) فانتصاران للمسلمين. وسقطت قرطبة سنة 1236 وإشبيلية سنة 1248 وبقيت غرناطة آخر الممالك."] },

  { id: "hs-106", s: "history", g: 4, d: 4, t: ["mongols", "ilkhanate"], src: "Rashīd al-Dīn, Jāmiʿ al-Tawārīkh; Ibn Kathīr, al-Bidāya wa-l-Nihāya",
    en: ["What significant event occurred around 694 AH (1295 CE) in the Mongol Ilkhanate of Iran?", ["The Ilkhan Ghāzān converted to Islam, making Islam the religion of the ruling house", "The Ilkhans destroyed Baghdad", "The Ilkhanate was conquered by the Mamluks", "The Ilkhans moved to China"], "Ghāzān accepted Islam and proclaimed it the religion of the state, which transformed the relation between Mongol rulers and Muslim subjects. His vizier Rashīd al-Dīn compiled the great history Jāmiʿ al-Tawārīkh. Baghdad had been destroyed earlier, in 656 AH."],
    de: ["Welches bedeutende Ereignis geschah um 694 n. H. (1295 n. Chr.) im mongolischen Ilchanat in Iran?", ["Der Ilchan Ġāzān trat zum Islam über und machte ihn zur Religion des Herrscherhauses", "Die Ilchane zerstörten Bagdad", "Das Ilchanat wurde von den Mamluken erobert", "Die Ilchane zogen nach China"], "Ġāzān nahm den Islam an und erklärte ihn zur Staatsreligion, was das Verhältnis zwischen den mongolischen Herrschern und den muslimischen Untertanen veränderte. Sein Wesir Rašīd ad-Dīn verfasste die große Geschichte Ǧāmiʿ at-Tawārīḫ. Bagdad war schon früher, 656 n. H., zerstört worden."],
    ar: ["أي حدث مهم وقع نحو سنة 694هـ (1295م) في الإيلخانية المغولية في إيران؟", ["أسلم الإيلخان غازان وجعل الإسلام دين البيت الحاكم", "دمّر الإيلخانيون بغداد", "فتح المماليك الإيلخانية", "انتقل الإيلخانيون إلى الصين"], "أسلم غازان وأعلن الإسلام دين الدولة، فتغيرت العلاقة بين الحكام المغول والرعايا المسلمين، وألّف وزيره رشيد الدين «جامع التواريخ»، أما بغداد فدُمّرت قبل ذلك سنة 656هـ."] },

  { id: "hs-107", s: "history", g: 4, d: 4, t: ["india", "delhi-sultanate"], src: "Minhāj al-Sirāj al-Jūzjānī, Ṭabaqāt-i Nāṣirī; standard histories of the Delhi Sultanate",
    en: ["Which commander of the Ghurids became the first sultan of Delhi and founded the dynasty known as the Mamluk (slave) dynasty, around 602 AH (1206 CE)?", ["Quṭb al-Dīn Aybak", "Maḥmūd of Ghazna", "Iltutmish", "Bābur"], "After the death of Muʿizz al-Dīn Muḥammad of Ghūr, his slave general Quṭb al-Dīn Aybak ruled from Lahore and Delhi, founding the Delhi Sultanate. Iltutmish was his son-in-law and later successor, Maḥmūd of Ghazna belonged to the previous century, and Bābur founded the Mughals."],
    de: ["Welcher Feldherr der Ghuriden wurde um 602 n. H. (1206 n. Chr.) erster Sultan von Delhi und Begründer der Mamluken-(Sklaven-)Dynastie?", ["Quṭb ad-Dīn Aibak", "Maḥmūd von Ġazna", "Iltutmiš", "Bābur"], "Nach dem Tod von Muʿizz ad-Dīn Muḥammad von Ġūr herrschte sein Sklavengeneral Quṭb ad-Dīn Aibak von Lahore und Delhi aus und begründete das Sultanat von Delhi. Iltutmiš war sein Schwiegersohn und späterer Nachfolger, Maḥmūd von Ġazna gehörte dem vorigen Jahrhundert an, und Bābur begründete die Moguln."],
    ar: ["أي قائد من الغوريين صار أول سلطان لدلهي وأسس أسرة المماليك (العبيد) نحو سنة 602هـ (1206م)؟", ["قطب الدين أيبك", "محمود الغزنوي", "إلتتمش", "بابر"], "بعد وفاة معز الدين محمد الغوري حكم قائده المملوك قطب الدين أيبك من لاهور ودلهي وأسس سلطنة دلهي، وكان إلتتمش صهره وخليفته من بعد، أما محمود الغزنوي فمن القرن السابق وبابر مؤسس المغول."] },

  { id: "hs-108", s: "history", g: 4, d: 4, t: ["ottomans", "battles"], src: "Standard histories of the Ottoman Empire (e.g. Imber, The Ottoman Empire 1300–1650)",
    en: ["Which battle of 1514 CE (920 AH) between Selim I and Shāh Ismāʿīl, the first Safavid ruler, confirmed Ottoman control of eastern Anatolia?", ["Chaldiran", "Mohács", "Marj Dābiq", "Lepanto"], "At Chaldiran in north-western Iran the Ottoman army with firearms defeated the Safavid cavalry, and Shāh Ismāʿīl's advance westward was halted. Marj Dābiq (1516) was against the Mamluks."],
    de: ["Welche Schlacht von 1514 n. Chr. (920 n. H.) zwischen Selim I. und Šāh Ismāʿīl, dem ersten Safawidenherrscher, bestätigte die osmanische Kontrolle über Ostanatolien?", ["Çaldıran", "Mohács", "Marǧ Dābiq", "Lepanto"], "Bei Çaldıran im Nordwesten Irans besiegte das osmanische Heer mit Feuerwaffen die safawidische Kavallerie, und Šāh Ismāʿīls Vorstoß nach Westen wurde gestoppt. Marǧ Dābiq (1516) war gegen die Mamluken."],
    ar: ["أي معركة سنة 1514م (920هـ) بين سليم الأول والشاه إسماعيل أول ملوك الصفويين ثبّتت سيطرة العثمانيين على شرق الأناضول؟", ["جالديران", "موهاكس", "مرج دابق", "ليبانتو"], "هزم الجيش العثماني بأسلحته النارية الفرسان الصفويين في جالديران شمال غرب إيران وتوقف تقدم الشاه إسماعيل غربًا، أما مرج دابق (1516) فضد المماليك."] },

  { id: "hs-109", s: "history", g: 4, d: 4, t: ["ottomans", "treaties"], src: "Standard histories of the Ottoman Empire (e.g. Finkel, Osman's Dream)",
    en: ["Which treaty of 1699 CE (1110 AH), after the failed siege of Vienna in 1683, is regarded as the first major Ottoman territorial loss in Europe?", ["The treaty of Karlowitz", "The treaty of Küçük Kaynarca", "The treaty of Sèvres", "The treaty of Lausanne"], "At Karlowitz the Ottomans ceded Hungary and Transylvania to the Habsburgs. Küçük Kaynarca (1774) followed as a defeat by Russia. Sèvres (1920) and Lausanne (1923) belong to the end of the empire."],
    de: ["Welcher Vertrag von 1699 n. Chr. (1110 n. H.), nach der gescheiterten Belagerung Wiens 1683, gilt als erster großer osmanischer Gebietsverlust in Europa?", ["Der Vertrag von Karlowitz", "Der Vertrag von Küçük Kaynarca", "Der Vertrag von Sèvres", "Der Vertrag von Lausanne"], "In Karlowitz traten die Osmanen Ungarn und Siebenbürgen an die Habsburger ab. Küçük Kaynarca (1774) folgte als Niederlage gegen Russland. Sèvres (1920) und Lausanne (1923) gehören zum Ende des Reiches."],
    ar: ["أي معاهدة سنة 1699م (1110هـ) بعد فشل حصار فيينا سنة 1683 تُعدّ أول خسارة إقليمية كبرى للعثمانيين في أوروبا؟", ["معاهدة كارلوفيتز", "معاهدة كوتشوك قينارجة", "معاهدة سيفر", "معاهدة لوزان"], "تنازل العثمانيون في كارلوفيتز عن المجر وترانسلفانيا للهابسبورغ، وتلتها قينارجة (1774) هزيمةً أمام روسيا، أما سيفر (1920) ولوزان (1923) فمن نهاية الدولة."] },

  { id: "hs-110", s: "history", g: 4, d: 4, t: ["ottomans", "reform"], src: "Standard histories of the Ottoman Empire (e.g. Lewis, The Emergence of Modern Turkey)",
    en: ["What was the Tanzimat, begun with the Edict of Gülhane in 1839?", ["A period of Ottoman administrative, legal and military reform", "A Mamluk revolt in Egypt", "A Safavid religious movement", "A treaty with Russia"], "The Tanzimat (‘reorganisation’) introduced legal guarantees of life and property, reorganised the army and administration, and later produced new codes of law and the first Ottoman constitution in 1876."],
    de: ["Was war die Tanzimat, mit dem Edikt von Gülhane 1839 begonnen?", ["Eine Zeit osmanischer Verwaltungs-, Rechts- und Militärreformen", "Ein Mamlukenaufstand in Ägypten", "Eine religiöse Bewegung der Safawiden", "Ein Vertrag mit Russland"], "Die Tanzimat (‚Neuordnung‘) führte rechtliche Garantien für Leben und Eigentum ein, ordnete Heer und Verwaltung neu und brachte später neue Gesetzbücher und 1876 die erste osmanische Verfassung hervor."],
    ar: ["ما التنظيمات التي بدأت بخط كلخانة سنة 1839؟", ["حقبة إصلاحات إدارية وقانونية وعسكرية في الدولة العثمانية", "ثورة مملوكية في مصر", "حركة دينية صفوية", "معاهدة مع روسيا"], "أقرت التنظيمات ضمانات قانونية للنفس والمال وأعادت تنظيم الجيش والإدارة، وأنتجت لاحقًا قوانين جديدة وأول دستور عثماني سنة 1876."] },

  { id: "hs-111", s: "history", g: 4, d: 4, t: ["historians", "ibn-khaldun"], src: "Ibn Khaldūn, al-Muqaddima, ch. 2 on the bedouin civilisation and ʿaṣabiyya",
    en: ["In Ibn Khaldūn's Muqaddima, what is ʿaṣabiyya?", ["Group solidarity that drives the rise of dynasties and weakens as luxury grows", "A legal term for inheritance shares", "A school of grammar", "A method of verifying chains of narrators"], "Ibn Khaldūn explains the rise and fall of states by ʿaṣabiyya, the bond of kinship or shared loyalty that helps a group win power; as the ruling group settles in luxury, solidarity fades and a new group with stronger ʿaṣabiyya replaces it, in a cycle of about three generations."],
    de: ["Was ist ʿaṣabiyya in Ibn Ḫaldūns Muqaddima?", ["Gruppenzusammenhalt, der den Aufstieg von Dynastien antreibt und mit wachsendem Luxus nachlässt", "Ein juristischer Begriff für Erbanteile", "Eine Grammatikschule", "Eine Methode zur Prüfung von Überliefererketten"], "Ibn Ḫaldūn erklärt Aufstieg und Fall von Staaten mit der ʿaṣabiyya, dem Band der Verwandtschaft oder gemeinsamen Loyalität, das einer Gruppe zur Macht verhilft; wenn die Herrschergruppe in Luxus verweichlicht, schwindet der Zusammenhalt, und eine Gruppe mit stärkerer ʿaṣabiyya löst sie in einem Kreislauf von etwa drei Generationen ab."],
    ar: ["ما العصبية في «مقدمة» ابن خلدون؟", ["التضامن الجماعي الذي يقيم الدول ويضعف مع الترف", "مصطلح فقهي في أنصبة الميراث", "مدرسة نحوية", "منهج في التحقق من أسانيد الرواة"], "فسّر ابن خلدون قيام الدول وسقوطها بالعصبية، وهي رابطة النسب أو الولاء المشترك التي تعين الجماعة على بلوغ الملك، فإذا استقر الحاكمون في الترف ضعفت وجاءت جماعة أقوى عصبية تحل محلها في دورة تقارب ثلاثة أجيال."] },

  { id: "hs-112", s: "history", g: 4, d: 4, t: ["historians", "works"], src: "al-Ṭabarī, Tārīkh al-Rusul wa-l-Mulūk; Ibn al-Athīr, al-Kāmil fī al-Tārīkh, introduction",
    en: ["Al-Ṭabarī's Tārīkh ends in the year 302 AH. Which historian wrote a work that built on it and continued the chronicle far beyond, down to 628 AH?", ["Ibn al-Athīr, in al-Kāmil fī al-Tārīkh", "Ibn Kathīr, in al-Bidāya wa-l-Nihāya", "Ibn Khaldūn, in Kitāb al-ʿIbar", "al-Dhahabī, in Tārīkh al-Islām"], "Ibn al-Athīr (555–630 AH) took al-Ṭabarī as his main source and abridged his chains of transmission, then continued the annals to the year 628. Later historians such as Ibn Kathīr in turn drew on Ibn al-Athīr."],
    de: ["Aṭ-Ṭabarīs Tārīḫ endet im Jahr 302 n. H. Welcher Historiker schrieb ein Werk, das darauf aufbaute und die Chronik weit darüber hinaus bis 628 n. H. fortführte?", ["Ibn al-Aṯīr in al-Kāmil fī t-Tārīḫ", "Ibn Kaṯīr in al-Bidāya wa-n-Nihāya", "Ibn Ḫaldūn in Kitāb al-ʿIbar", "aḏ-Ḏahabī in Tārīḫ al-Islām"], "Ibn al-Aṯīr (555–630 n. H.) nahm aṭ-Ṭabarī als Hauptquelle, kürzte dessen Überliefererketten und führte die Annalen bis zum Jahr 628 fort. Spätere Historiker wie Ibn Kaṯīr schöpften ihrerseits aus Ibn al-Aṯīr."],
    ar: ["ينتهي تاريخ الطبري سنة 302هـ. أي مؤرخ ألّف كتابًا اعتمد عليه وواصل الحوليات بعده حتى سنة 628هـ؟", ["ابن الأثير في «الكامل في التاريخ»", "ابن كثير في «البداية والنهاية»", "ابن خلدون في «كتاب العبر»", "الذهبي في «تاريخ الإسلام»"], "اعتمد ابن الأثير (555–630هـ) على الطبري أصلًا واختصر أسانيده ثم تابع الحوليات إلى سنة 628، ثم أفاد منه مؤرخون لاحقون كابن كثير."] },

  { id: "hs-113", s: "history", g: 4, d: 4, t: ["historians", "works"], src: "al-Masʿūdī, Murūj al-Dhahab wa-Maʿādin al-Jawhar, introduction",
    en: ["Which historian and geographer of the 4th century AH wrote Murūj al-Dhahab wa-Maʿādin al-Jawhar, mixing history by topics and peoples with geography and anecdotes?", ["al-Masʿūdī", "al-Balādhurī", "Ibn Saʿd", "Ibn Khallikān"], "Al-Masʿūdī (d. c. 345 AH) travelled widely and composed Murūj al-Dhahab, which treats the histories of nations and dynasties thematically rather than strictly year by year. Al-Balādhurī wrote on conquests, Ibn Saʿd on biographical classes."],
    de: ["Welcher Historiker und Geograph des 4. Jh. n. H. schrieb Murūǧ aḏ-Ḏahab wa-Maʿādin al-Ǧauhar, das Geschichte nach Themen und Völkern mit Geographie und Anekdoten verbindet?", ["al-Masʿūdī", "al-Balāḏurī", "Ibn Saʿd", "Ibn Ḫallikān"], "Al-Masʿūdī (gest. ca. 345 n. H.) reiste weit und verfasste Murūǧ aḏ-Ḏahab, das die Geschichte der Völker und Dynastien thematisch statt streng nach Jahren behandelt. Al-Balāḏurī schrieb über Eroberungen, Ibn Saʿd über biografische Klassen."],
    ar: ["أي مؤرخ وجغرافي من القرن الرابع الهجري ألّف «مروج الذهب ومعادن الجوهر» ومزج فيه التاريخ بحسب الموضوعات والأمم بالجغرافيا والطرائف؟", ["المسعودي", "البلاذري", "ابن سعد", "ابن خلكان"], "جاب المسعودي (ت نحو 345هـ) البلاد وألّف «مروج الذهب» الذي يعالج تواريخ الأمم والدول بحسب الموضوعات لا بحسب السنين فقط، أما البلاذري فكتب في الفتوح وابن سعد في الطبقات."] },

  { id: "hs-114", s: "history", g: 4, d: 4, t: ["historians", "genres"], src: "al-Sakhāwī, al-Iʿlān bi-l-Tawbīkh li-man Dhamma ahl al-Tārīkh; Franz Rosenthal, A History of Muslim Historiography",
    en: ["Which historical genre arranges events year by year?", ["Ḥawliyyāt (annals)", "Ṭabaqāt (biographical classes)", "Tarājim (biographical dictionaries by name)", "Rasāʾil (letters)"], "Annals (ḥawliyyāt) present events under each year, as in al-Ṭabarī and Ibn al-Athīr. Ṭabaqāt group persons by generation, as in Ibn Saʿd, while tarājim collect lives alphabetically or by city."],
    de: ["Welches Geschichtsgenre ordnet Ereignisse Jahr für Jahr?", ["Ḥauliyyāt (Annalen)", "Ṭabaqāt (biografische Klassen)", "Tarāǧim (biografische Wörterbücher nach Namen)", "Rasāʾil (Briefe)"], "Annalen (ḥauliyyāt) stellen die Ereignisse unter jedem Jahr dar, wie bei aṭ-Ṭabarī und Ibn al-Aṯīr. Ṭabaqāt gruppieren Personen nach Generationen, wie bei Ibn Saʿd, während Tarāǧim Lebensbeschreibungen alphabetisch oder nach Städten sammeln."],
    ar: ["أي فن تاريخي يرتب الأحداث على السنين؟", ["الحوليات", "الطبقات", "التراجم", "الرسائل"], "الحوليات تعرض الأحداث تحت كل سنة كما عند الطبري وابن الأثير، أما الطبقات فتجمع الأشخاص بحسب الأجيال كما عند ابن سعد، والتراجم تجمع السير على الحروف أو بحسب البلدان."] },

  { id: "hs-115", s: "history", g: 4, d: 4, t: ["historians", "works"], src: "Ibn Saʿd, al-Ṭabaqāt al-Kubrā, introduction",
    en: ["What type of work is Ibn Saʿd's al-Ṭabaqāt al-Kubrā?", ["A large collection of biographies of the Prophet, the Companions and the Successors arranged in classes", "A chronicle of the Abbasid caliphs year by year", "A geographical dictionary", "A commentary on Ṣaḥīḥ al-Bukhārī"], "Ibn Saʿd (d. 230 AH) was the secretary of al-Wāqidī and compiled al-Ṭabaqāt, the earliest large biographical work, with the Prophet first, then the Companions and later generations grouped by their time and place."],
    de: ["Um welche Art von Werk handelt es sich bei Ibn Saʿds al-Ṭabaqāt al-Kubrā?", ["Um eine große Sammlung von Biografien des Propheten, der Gefährten und der Nachfolger, in Klassen geordnet", "Um eine Chronik der abbasidischen Kalifen Jahr für Jahr", "Um ein geographisches Wörterbuch", "Um einen Kommentar zu Ṣaḥīḥ al-Buḫārī"], "Ibn Saʿd (gest. 230 n. H.) war Sekretär al-Wāqidīs und stellte al-Ṭabaqāt zusammen, das früheste große biografische Werk: zuerst der Prophet, dann die Gefährten und spätere Generationen, nach Zeit und Ort gruppiert."],
    ar: ["ما نوع كتاب «الطبقات الكبرى» لابن سعد؟", ["موسوعة تراجم للنبي ﷺ والصحابة والتابعين مرتبة على الطبقات", "حوليات للخلفاء العباسيين بحسب السنين", "معجم جغرافي", "شرح لصحيح البخاري"], "كان ابن سعد (ت 230هـ) كاتب الواقدي وألّف «الطبقات» وهو أقدم موسوعة تراجم كبرى، يبدأ بالنبي ﷺ ثم الصحابة ومن بعدهم مجموعين بحسب أزمنتهم وبلدانهم."] },

  { id: "hs-116", s: "history", g: 4, d: 4, t: ["historians", "works"], src: "Ibn Khallikān, Wafayāt al-Aʿyān wa-Anbāʾ Abnāʾ al-Zamān, introduction; al-Maqrīzī, al-Mawāʿiẓ wa-l-Iʿtibār",
    en: ["Which pair of authors and works matches correctly?", ["Ibn Khallikān: Wafayāt al-Aʿyān; al-Maqrīzī: al-Khiṭaṭ", "Ibn Khallikān: al-Khiṭaṭ; al-Maqrīzī: Wafayāt al-Aʿyān", "Ibn Khallikān: Murūj al-Dhahab; al-Maqrīzī: al-Kāmil", "Ibn Khallikān: Futūḥ al-Buldān; al-Maqrīzī: al-Bidāya"], "Ibn Khallikān (608–681 AH, commonly given) compiled the biographical dictionary Wafayāt al-Aʿyān, and the Cairo historian al-Maqrīzī (766–845 AH, commonly given) wrote al-Mawāʿiẓ wa-l-Iʿtibār (al-Khiṭaṭ) on the topography and history of Egypt."],
    de: ["Welches Paar von Autoren und Werken ist richtig zugeordnet?", ["Ibn Ḫallikān: Wafayāt al-Aʿyān; al-Maqrīzī: al-Ḫiṭaṭ", "Ibn Ḫallikān: al-Ḫiṭaṭ; al-Maqrīzī: Wafayāt al-Aʿyān", "Ibn Ḫallikān: Murūǧ aḏ-Ḏahab; al-Maqrīzī: al-Kāmil", "Ibn Ḫallikān: Futūḥ al-Buldān; al-Maqrīzī: al-Bidāya"], "Ibn Ḫallikān (608–681 n. H., gängige Angabe) stellte das biografische Wörterbuch Wafayāt al-Aʿyān zusammen, und der Kairoer Historiker al-Maqrīzī (766–845 n. H., gängige Angabe) schrieb al-Mawāʿiẓ wa-l-Iʿtibār (al-Ḫiṭaṭ) über Topographie und Geschichte Ägyptens."],
    ar: ["أي اقتران بين المؤلفين وكتبهم صحيح؟", ["ابن خلكان: وفيات الأعيان؛ المقريزي: الخطط", "ابن خلكان: الخطط؛ المقريزي: وفيات الأعيان", "ابن خلكان: مروج الذهب؛ المقريزي: الكامل", "ابن خلكان: فتوح البلدان؛ المقريزي: البداية"], "ألّف ابن خلكان (608–681هـ على المشهور) معجم التراجم «وفيات الأعيان»، وكتب مؤرخ القاهرة المقريزي (766–845هـ على المشهور) «المواعظ والاعتبار» (الخطط) في جغرافية مصر وتاريخها."] },

  { id: "hs-117", s: "history", g: 4, d: 4, t: ["mongols", "khwarazm"], src: "Ibn al-Athīr, al-Kāmil fī al-Tārīkh, events of 616 AH; al-Nasawī, Sīrat al-Sulṭān Jalāl al-Dīn",
    en: ["What event is commonly cited as the immediate cause of the Mongol invasion of the Khwārazmian empire in 616 AH (1219 CE)?", ["The killing of Mongol merchants and envoys at Otrar by the Khwārazmian governor", "A Mongol request to convert to Islam", "A Khwārazmian attack on Baghdad", "A dispute over the pilgrimage route"], "Chinggis Khan sent a trade caravan and envoys; at Otrar the governor had the merchants killed, and the Khwārazmshāh Muḥammad refused to give satisfaction. The Mongol campaign destroyed Bukhārā, Samarkand and Merv, and the empire fell. His son Jalāl al-Dīn resisted until 628 AH."],
    de: ["Welches Ereignis gilt allgemein als unmittelbarer Anlass der mongolischen Invasion des Chwarezmischen Reiches 616 n. H. (1219 n. Chr.)?", ["Die Tötung mongolischer Kaufleute und Gesandter in Otrar durch den chwarezmischen Statthalter", "Eine mongolische Aufforderung zur Bekehrung zum Islam", "Ein chwarezmischer Angriff auf Bagdad", "Ein Streit um die Pilgerroute"], "Dschingis Khan sandte eine Handelskarawane und Gesandte; in Otrar ließ der Statthalter die Kaufleute töten, und der Chwarezm-Schah Muḥammad verweigerte Genugtuung. Der mongolische Feldzug zerstörte Buchara, Samarkand und Merw, und das Reich fiel. Sein Sohn Ǧalāl ad-Dīn leistete bis 628 n. H. Widerstand."],
    ar: ["أي حدث يُذكر عادة سببًا مباشرًا لغزو المغول للدولة الخوارزمية سنة 616هـ (1219م)؟", ["قتل تجار المغول ورسلهم في أترار على يد والي الخوارزميين", "طلب مغولي بالدخول في الإسلام", "هجوم خوارزمي على بغداد", "نزاع على طريق الحج"], "أرسل جنكيز خان قافلة تجارية ورسلًا فقتل والي أترار التجار ورفض الشاه محمد الخوارزمي إرضاءه، فدمّرت الحملة بخارى وسمرقند ومرو وسقطت الدولة، وقاوم ابنه جلال الدين حتى 628هـ."] },

  { id: "hs-118", s: "history", g: 4, d: 4, t: ["crusades", "mamluks"], src: "Ibn ʿAbd al-Ẓāhir, al-Rawḍ al-Zāhir fī Sīrat al-Malik al-Ẓāhir; al-Maqrīzī, al-Sulūk",
    en: ["Which Crusader principality did Sultan Baybars capture in 666 AH (1268 CE)?", ["Antioch", "Edessa", "Jerusalem", "Tripoli"], "Baybars took Antioch, an important Crusader principality in northern Syria, after Edessa had fallen to Zangī in 1144 and Jerusalem to Ṣalāḥ al-Dīn in 1187. Tripoli was taken by Qalāwūn in 1289."],
    de: ["Welches Kreuzfahrerfürstentum eroberte Sultan Baibars 666 n. H. (1268 n. Chr.)?", ["Antiochia", "Edessa", "Jerusalem", "Tripolis"], "Baibars nahm Antiochia, ein wichtiges Kreuzfahrerfürstentum in Nordsyrien, ein, nachdem Edessa 1144 an Zangī und Jerusalem 1187 an Ṣalāḥ ad-Dīn gefallen waren. Tripolis wurde 1289 von Qalāwūn genommen."],
    ar: ["أي إمارة صليبية استولى عليها السلطان بيبرس سنة 666هـ (1268م)؟", ["أنطاكية", "الرها", "القدس", "طرابلس"], "فتح بيبرس أنطاكية وهي إمارة صليبية مهمة في شمال الشام، بعد أن سقطت الرها بيد زنكي سنة 1144 والقدس بيد صلاح الدين سنة 1187، أما طرابلس ففتحها قلاوون سنة 1289."] },

  { id: "hs-119", s: "history", g: 4, d: 5, t: ["andalus", "fall-of-granada"], src: "al-Maqqarī, Nafḥ al-Ṭīb; standard histories of the Naṣrid kingdom of Granada",
    en: ["Which dynasty ruled Granada from 629 AH (1232 CE) until its fall, and built the Alhambra?", ["The Naṣrids (Banū Naṣr, Banū al-Aḥmar)", "The Almohads", "The Umayyads of Córdoba", "The Almoravids"], "Muḥammad ibn Yūsuf ibn Naṣr (Ibn al-Aḥmar) founded the Naṣrid dynasty, which survived by paying tribute to Castile and trading across the Mediterranean. Its last ruler, Muḥammad XII (Abū ʿAbd Allāh, ‘Boabdil’), surrendered in 1492."],
    de: ["Welche Dynastie herrschte von 629 n. H. (1232 n. Chr.) bis zu seinem Fall über Granada und erbaute die Alhambra?", ["Die Nasriden (Banū Naṣr, Banū l-Aḥmar)", "Die Almohaden", "Die Umayyaden von Córdoba", "Die Almoraviden"], "Muḥammad ibn Yūsuf ibn Naṣr (Ibn al-Aḥmar) gründete die Nasridendynastie, die durch Tributzahlungen an Kastilien und Handel im Mittelmeerraum überlebte. Ihr letzter Herrscher, Muḥammad XII. (Abū ʿAbd Allāh, ‚Boabdil‘), ergab sich 1492."],
    ar: ["أي أسرة حكمت غرناطة منذ 629هـ (1232م) حتى سقوطها وبنت الحمراء؟", ["بنو نصر (بنو الأحمر)", "الموحدون", "أمويو قرطبة", "المرابطون"], "أسس محمد بن يوسف بن نصر (ابن الأحمر) الدولة النصرية التي بقيت بدفع الجزية لقشتالة والتجارة عبر المتوسط، وسلّم آخر ملوكها محمد الثاني عشر (أبو عبد الله) المدينة سنة 1492."] },
];
